INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C1','soc',3,2,'u1',1,'사회의 변화와 원인 — 사회의 모습은 끊임없이 변해 사라지는 모습, 새로 생기는 모습, 다른 모습으로 바뀌는 모습이 있음 · 원인: 사람 수의 변화, 평균 수명의 증가, 사람들의 생각 변화, 과학 기술의 발달, 다른 나라와의 교류(실제로는 여러 원인이 얽힘) · 옛 학교: 학생은 많고 교실은 부족해 오전반·오후반, 점심 도시락, 이름은 국민학교, 교실 난로 → 오늘날 급식·초등학교 · 학생이 줄어 문을 닫는 학교, 노인 복지관, 청소 로봇, 세계 음식 가게',ARRAY['[4사03-01] 최근 사회 변화의 양상과 특징을 파악하고, 그로 인해 나타난 생활 모습의 변화를 탐색한다.']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C2','soc',3,2,'u1',2,'저출산으로 달라진 생활 — 저출산은 태어나는 아이의 수가 줄어 출산율이 감소하는 현상 · 그래프(우리나라에서 연도별 태어나는 아이의 수, 가로 연도·세로 만 명): 1970년 101만 → 1980년 86만 → 1990년 65만 → 2000년 64만 → 2010년 47만 → 2020년 27만, 점점 줄어듦 · 까닭: 결혼하지 않거나 아이를 낳아 기르는 데 부담을 느끼는 사람이 많아짐 · 영향: 학생 수와 일할 수 있는 사람 수가 줄어듦 · 노력: 아이를 낳고 키우는 데 필요한 돈과 물품 지원, 안전하고 쾌적한 보육 시설, 부모가 일을 쉴 수 있는 제도',ARRAY['[4사03-01] 최근 사회 변화의 양상과 특징을 파악하고, 그로 인해 나타난 생활 모습의 변화를 탐색한다.']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C3','soc',3,2,'u1',3,'고령화로 달라진 생활 — 65세 이상을 노인이라 함 · 의학 기술이 발달하고 깨끗한 환경에서 생활하게 되어 오래 살게 됨 · 고령화는 전체 사람 수에서 노인의 수가 차지하는 비율이 높아지는 현상(비율 = 일정한 양을 기준으로 어떤 양이 차지하는 정도) · 100명 마을이라면 노인이 1980년 4명 정도 → 2020년 16명 정도 → 2050년(예상) 40명 정도 · 달라진 모습: 노인 복지관, 노인 전문 병원·요양 시설, 노인 배움 프로그램, 일하는 노인 · 노력: 복지 제도, 알맞은 일자리, 노인을 위한 물건 개발, 노후 생활 준비 지원',ARRAY['[4사03-01] 최근 사회 변화의 양상과 특징을 파악하고, 그로 인해 나타난 생활 모습의 변화를 탐색한다.']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C4','soc',3,2,'u1',4,'지능정보화로 달라진 생활 — 정보 통신 기술은 전화·컴퓨터 같은 기기로 정보를 주고받는 기술, 인공지능은 사람처럼 정보를 익히고 처리해 여러 상황에 적용하는 컴퓨터 시스템 · 지능정보화는 인공지능을 활용한 다양한 기술이 사회 전반에 폭넓은 영향을 미치는 현상 · 편리해진 점: 배달 로봇, 맞춤 교육, 목소리 인식 기기, 안전 운전 도움 · 문제: 사이버 범죄, 거짓 정보 확산, 인터넷·스마트폰 과의존, 일자리 감소 · 노력: 사이버 범죄 감시, 올바른 사용 습관 지원, 인공지능 활용 능력 교육, 직업 환경 대응 교육 · 장점은 누리고 단점은 보완 · 개인 정보를 함부로 공유하지 않기, 인터넷 정보를 비판 없이 믿지 않기, 정해진 규칙에 따라 사용하기',ARRAY['[4사03-01] 최근 사회 변화의 양상과 특징을 파악하고, 그로 인해 나타난 생활 모습의 변화를 탐색한다.']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C5','soc',3,2,'u1',5,'세계화로 달라진 생활 — 세계화는 세계 여러 나라가 다양한 분야에서 교류하며 전 세계가 하나로 연결되는 현상 · 모습: 다른 나라 음식·과일·영화, 함께하는 행사, 세종 학당(한국어와 한국에 관한 내용을 가르침), 한류(대한민국과 관련 있는 것들이 다른 나라에서 인기를 얻는 현상) · 물건은 다른 나라에서 들어오기도 하고(초콜릿·포도·청바지) 우리나라 회사가 다른 나라에 공장을 짓기도 함(라면·초코과자) — 서로 주고받으며 연결 · 문제: 각 나라의 전통적인 생활 양식 약화, 감염병이 빠르게 퍼짐 · 태도: 다른 나라의 생활 양식을 장단점을 따져 받아들이기, 우리 생활 양식 소중히 여기기, 세계 여러 나라의 문제를 함께 해결하려는 자세',ARRAY['[4사03-01] 최근 사회 변화의 양상과 특징을 파악하고, 그로 인해 나타난 생활 모습의 변화를 탐색한다.']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C6','soc',3,2,'u1',6,'사회 변화로 달라진 생활 정리 — 저출산·고령화·지능정보화·세계화의 뜻과 달라진 모습, 문제, 대응 방안을 차례로 정리(주제 → 모습 → 문제 → 대응 방안) · 복지 제도·정보 통신 기술·출산율 같은 낱말 · 카드 뉴스·포스터로 나타내기 · 사회 변화로 나타난 문제를 해결하려면 우리 모두 관심을 갖고 함께 노력해야 함',ARRAY['[4사03-01] 최근 사회 변화의 양상과 특징을 파악하고, 그로 인해 나타난 생활 모습의 변화를 탐색한다.']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C7','soc',3,2,'u1',7,'문화의 뜻과 특징 — 문화는 한 사회의 사람들이 지닌 공통의 생활 양식(사람들이 함께 생활하며 만들어지고 오래 전해져 내려오기도 함) · 배고파서 먹기·졸려서 자기처럼 태어날 때부터 하는 행동은 문화가 아님 · 의식주(옷·음식·집), 말과 글, 음악, 미술, 종교, 규범(마땅히 따르고 지켜야 할 생각이나 행동의 기준) 등 · 지역의 환경에 따라 생활 양식이 다양함(추운 곳 털옷, 햇볕 강한 곳 긴 옷) · 각 사회의 문화는 비슷한 점도 있고 다른 점도 있음(새 학년 시작 달, 인사 방법, 공부하는 과목) · 축제는 한 사회의 문화를 잘 드러냄',ARRAY['[4사03-02] 우리 사회에 다양한 문화가 확산되면서 나타나는 긍정적 효과와 문제를 분석하고, 나와 다른 사람이나 집단의 문화를 존중하는 태도를 기른다.']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C8','soc',3,2,'u1',8,'우리 사회의 다양한 문화 — 이주민은 다른 지역에서 옮겨 와 사는 사람 · 외국인 이주민 수가 늘어남(111만 명 → 213만 명), 세계화의 영향으로 직장·공부·결혼 등 여러 목적 · 1인 가구는 가족과 같이 살지 않고 혼자 사는 경우, 결혼에 관한 생각 변화·혼자 사는 노인 증가로 늘어남 · 반려동물은 사람과 더불어 살며 친밀감과 안정감을 주는 동물, 반려동물 놀이터·공원·행사가 생김 · 한 동네에 여러 문화가 함께 있음',ARRAY['[4사03-02] 우리 사회에 다양한 문화가 확산되면서 나타나는 긍정적 효과와 문제를 분석하고, 나와 다른 사람이나 집단의 문화를 존중하는 태도를 기른다.']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C9','soc',3,2,'u1',9,'다양한 문화 확산의 영향 — 좋은 점과 문제가 함께 나타남 · 외국인 이주민: 세계 여러 나라 문화를 경험할 기회가 늘어남 / 종교·언어·피부색이 다르다는 까닭으로 부당한 대우, 편견과 차별 · 1인 가구: 작은 가전제품·적은 양 포장 상품·장보기 등을 대신하는 활동 / 외로움·불안함, 도움을 청할 사람이 없음 · 반려동물: 마음의 안정, 수의사·훈련사·미용사 같은 직업 / 소음·배설물·냄새로 이웃 간 갈등(소음이 가장 많음), 버려지는 동물 · 편견은 공정하지 못하고 한쪽으로 치우친 생각, 차별은 편견을 가지고 다르게 대우하는 것',ARRAY['[4사03-02] 우리 사회에 다양한 문화가 확산되면서 나타나는 긍정적 효과와 문제를 분석하고, 나와 다른 사람이나 집단의 문화를 존중하는 태도를 기른다.']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C10','soc',3,2,'u1',10,'문제를 해결하려는 노력과 존중하는 태도 — 만화 영화 속 미나는 피부색을 이상하게 여길까 봐 모자를 씀 · 사회의 노력: 한국 생활에 필요한 정보를 다양한 언어로 제공, 국가 인권 위원회(편견과 차별을 막는 제도·기관), 1인 가구 프로그램과 안전 지원, 반려견 산책 때 입마개·목줄, 유니버설 디자인(누구나 쓰기 쉽게 디자인) · 바람직한 태도: 편견을 갖지 않고 차별하지 않기, 다른 문화의 사람들이 겪는 어려움에 관심, 서로 다름을 인정하고 존중 — 바람직하지 못한 태도(무시·경계, 이상하게 여기기, 비난)가 하나라도 있으면 안 됨',ARRAY['[4사03-02] 우리 사회에 다양한 문화가 확산되면서 나타나는 긍정적 효과와 문제를 분석하고, 나와 다른 사람이나 집단의 문화를 존중하는 태도를 기른다.']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C11','soc',3,2,'u1',11,'다양한 문화에 대한 이해와 존중 정리 — 문화·이주민·1인 가구·반려동물·편견과 차별에 관한 설명이 알맞은지 가리기 · 축제 초대장 만들기: 주제 정하기 → 프로그램 계획 → 내용과 장소 정하기 → 초청하는 글 쓰기 · 이주민·1인 가구·반려동물 축제 프로그램 · 다양한 문화를 대할 때는 서로 다름을 인정하고 존중',ARRAY['[4사03-02] 우리 사회에 다양한 문화가 확산되면서 나타나는 긍정적 효과와 문제를 분석하고, 나와 다른 사람이나 집단의 문화를 존중하는 태도를 기른다.']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X01','soc',3,'u1',ARRAY['SO3-2-u1-C1']::text[],'사회의 모습은 한번 정해지면 변하지 않는다고, 또는 사라지거나 생기는 것 가운데 한쪽만 있다고 여긴다','사라지고 · 생기고 · 바뀌어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X02','soc',3,'u1',ARRAY['SO3-2-u1-C1']::text[],'사회가 변하는 원인을 한 가지로만 보거나, 사회와 관계없는 일(해가 뜨는 것 등)을 원인으로 여긴다','사람 수 · 수명 · 생각 · 기술 · 교류') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X03','soc',3,'u1',ARRAY['SO3-2-u1-C1']::text[],'옛날과 오늘날의 학교·생활 모습을 바꾸어 안다(옛날에 급식을 먹었다고 여기는 등)','옛날 도시락 · 오늘날 급식') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X04','soc',3,'u1',ARRAY['SO3-2-u1-C2']::text[],'저출산의 뜻을 거꾸로 안다(태어나는 아이의 수가 늘어나는 현상으로 여기는 등)','태어나는 아이가 줄어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X05','soc',3,'u1',ARRAY['SO3-2-u1-C2','SO3-2-u1-C3']::text[],'그래프·그림 자료를 잘못 읽는다(가로·세로·단위를 헷갈리거나, 거의 같으면 변하지 않았다고 여기는 등)','제목 · 가로 · 세로 · 단위') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X06','soc',3,'u1',ARRAY['SO3-2-u1-C2']::text[],'저출산이 계속될 때 달라지는 모습을 거꾸로 안다(학생 수나 일할 사람이 늘어난다고 여기는 등)','학생 수 · 일할 사람이 줄어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X07','soc',3,'u1',ARRAY['SO3-2-u1-C2']::text[],'저출산 문제를 해결하려는 노력을 잘못 안다(학교 문을 닫는 것을 노력으로 여기는 등)','지원 · 보육 시설 · 쉴 수 있는 제도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X08','soc',3,'u1',ARRAY['SO3-2-u1-C3']::text[],'고령화를 노인의 수만 늘어나는 것으로, 또는 노인의 비율이 낮아지는 것으로 여긴다','전체에서 노인이 차지하는 비율이 높아져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X09','soc',3,'u1',ARRAY['SO3-2-u1-C3']::text[],'사람들이 오래 살게 된 까닭을 잘못 안다','의학 기술 · 깨끗한 환경') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X10','soc',3,'u1',ARRAY['SO3-2-u1-C3']::text[],'고령화로 달라진 모습이나 대비하려는 노력을 거꾸로 안다(노인을 위한 시설이 줄어든다고 여기는 등)','시설 · 프로그램 · 일자리가 늘어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X11','soc',3,'u1',ARRAY['SO3-2-u1-C4']::text[],'정보 통신 기술·인공지능·지능정보화의 뜻을 서로 바꾸어 안다','주고받는 기술 · 생각하는 컴퓨터 · 넓은 영향') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X12','soc',3,'u1',ARRAY['SO3-2-u1-C4']::text[],'지능정보화로 편리해진 점과 생겨난 문제를 바꾸어 짝짓는다','누려요 · 보완해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X13','soc',3,'u1',ARRAY['SO3-2-u1-C4']::text[],'지능정보화를 한쪽으로만 본다(편리하니 문제는 걱정 없다, 또는 문제가 있으니 아예 쓰지 말자)','장점은 누리고 단점은 보완해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X14','soc',3,'u1',ARRAY['SO3-2-u1-C4']::text[],'인터넷·태블릿 컴퓨터를 쓸 때 지킬 점을 잘못 안다(개인 정보를 올리거나 정보를 그대로 믿는 등)','개인 정보 · 비판하며 · 규칙대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X15','soc',3,'u1',ARRAY['SO3-2-u1-C5']::text[],'세계화의 뜻을 잘못 안다(다른 나라 물건을 사기만 하는 것, 한 나라하고만 교류하는 것으로 여기는 등)','여러 나라가 하나로 연결돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X16','soc',3,'u1',ARRAY['SO3-2-u1-C5']::text[],'세계화로 다른 나라에서 들어오기만 한다고 여겨, 우리나라가 다른 나라에 영향을 주는 모습(한류·공장)을 놓친다','들어오고 나가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X17','soc',3,'u1',ARRAY['SO3-2-u1-C5']::text[],'세계화로 생긴 문제나 대응 태도를 잘못 안다(다른 나라 생활 양식을 무조건 따르거나 모두 거부하는 등)','장단점을 따져 받아들여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X18','soc',3,'u1',ARRAY['SO3-2-u1-C6','SO3-2-u1-C2','SO3-2-u1-C3','SO3-2-u1-C4','SO3-2-u1-C5']::text[],'저출산·고령화·지능정보화·세계화의 뜻이나 모습을 서로 바꾸어 짝짓는다','아이 · 노인 · 인공지능 · 여러 나라') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X19','soc',3,'u1',ARRAY['SO3-2-u1-C6']::text[],'사회 변화로 생긴 문제는 나라만 해결하면 되고 우리와는 관계없다고 여긴다','모두 관심을 갖고 함께 노력해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X20','soc',3,'u1',ARRAY['SO3-2-u1-C7']::text[],'배고파서 먹기·졸려서 자기처럼 태어날 때부터 하는 행동을 문화라고 여긴다','함께 만든 공통의 생활 양식') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X21','soc',3,'u1',ARRAY['SO3-2-u1-C7']::text[],'문화를 의식주만으로 좁게 보거나, 의식주·규범 같은 낱말의 뜻을 바꾸어 안다','말과 글 · 음악 · 종교 · 규범도 문화') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X22','soc',3,'u1',ARRAY['SO3-2-u1-C7']::text[],'다른 사회의 문화는 잘못되었다고, 또는 모든 사회의 문화가 똑같다고 여겨 비슷한 점과 다른 점을 놓친다','비슷한 점도 있고 다른 점도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X23','soc',3,'u1',ARRAY['SO3-2-u1-C7']::text[],'지역의 환경에 따라 생활 양식이 달라진다는 점을 놓친다','추운 곳 · 더운 곳 · 햇볕 강한 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X24','soc',3,'u1',ARRAY['SO3-2-u1-C8']::text[],'이주민·1인 가구·반려동물의 뜻을 서로 바꾸어 안다','옮겨 와 사는 사람 · 혼자 사는 집 · 더불어 사는 동물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X25','soc',3,'u1',ARRAY['SO3-2-u1-C8']::text[],'우리 사회의 다양한 문화가 늘어난 까닭이나 변화를 거꾸로 안다(1인 가구가 줄어든다고 여기는 등)','늘어나고 있어요 · 까닭이 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X26','soc',3,'u1',ARRAY['SO3-2-u1-C9']::text[],'다양한 문화가 확산된 영향을 한쪽으로만 본다(좋은 점만 있다, 또는 문제가 있는 문화는 없애야 한다)','밝은 면과 그늘 면이 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X27','soc',3,'u1',ARRAY['SO3-2-u1-C9']::text[],'편견과 차별의 뜻을 바꾸어 안다(편견을 행동으로, 차별을 생각으로 여기는 등)','편견은 생각 · 차별은 행동') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X28','soc',3,'u1',ARRAY['SO3-2-u1-C9']::text[],'다양한 문화가 확산된 영향을 사람들(이주민·1인 가구·반려동물과 함께 사는 사람)과 잘못 짝짓는다','누구와 관계있는 모습일까요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X29','soc',3,'u1',ARRAY['SO3-2-u1-C10']::text[],'문제를 해결하려는 사회의 노력을 잘못 알거나, 노력이 필요 없다고 여긴다','다양한 언어 · 인권 위원회 · 유니버설 디자인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X30','soc',3,'u1',ARRAY['SO3-2-u1-C10']::text[],'다른 문화를 무시하거나 이상하게 여기는 바람직하지 못한 태도를 괜찮다고 여긴다','하나라도 있으면 탑이 기울어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X31','soc',3,'u1',ARRAY['SO3-2-u1-C10']::text[],'다양한 문화를 대할 때 우리 문화만 소중히 여기고 다른 문화는 낮추어 본다','서로 다름을 인정하고 존중해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X32','soc',3,'u1',ARRAY['SO3-2-u1-C11']::text[],'축제 초대장 만들기 차례나 축제 프로그램을 잘못 짝짓는다','주제 → 프로그램 → 내용·장소 → 초청 글') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X33','soc',3,'u1',ARRAY['SO3-2-u1-C3']::text[],'고령화 자체를 사회 문제로 여기거나, 고령화로 생긴 문제의 책임을 노인에게 돌린다','고령화는 사회가 함께 대비할 변화 — 노인 탓이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X34','soc',3,'u1',ARRAY['SO3-2-u1-C9','SO3-2-u1-C10']::text[],'무심결에 하는 말(「한국에서 사니까 좋지요?」 등)에 담긴 편견을 알아차리지 못하고 괜찮다고 여긴다','그 말을 듣는 사람의 마음을 생각해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X35','soc',3,'u1',ARRAY['SO3-2-u1-C2','SO3-2-u1-C6','SO3-2-u1-C10']::text[],'여러 해결 방법 가운데 하나만 옳고 나머지는 쓸모없다고 여겨, 친구가 고른 다른 방법과 까닭을 받아들이지 않는다','방법마다 도움이 되는 점이 달라요 — 친구의 까닭을 들어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X36','soc',3,'u1',ARRAY['SO3-2-u1-C7','SO3-2-u1-C8']::text[],'문화는 나라마다 하나뿐이라 한 나라 안에서는 모두 같은 문화를 지닌다고 여긴다','한 나라 안에서도 다양한 문화가 나타나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_basic#1','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',1,'mc','auto','1991년 일기 속 교실 모습 가운데 오늘날과 다른 점은 무엇인가요?',ARRAY['SO3-2-u1-X03']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C1","difficulty":1,"kind":"mc","stem":"1991년 일기 속 교실 모습 가운데 오늘날과 다른 점은 무엇인가요?","options":[{"t":"교실에 난로가 있어 넣을 기름을 받아 와야 했어요","correct":true},{"t":"선생님께 공부를 배웠어요","mis":"SO3-2-u1-X03"},{"t":"점심시간에 급식을 먹었어요","mis":"SO3-2-u1-X03"},{"t":"아침에 스마트폰으로 숙제를 확인했어요","mis":"SO3-2-u1-X03"}],"explanation":["일기를 다시 읽어요.","교실 난로에 넣을 기름을 받아 왔어요.","오늘날 교실과 다른 모습이에요."],"asset":{"type":"passage","lines":["아침에 선생님께서 교실 난로에 넣을 기름을 받아 오라고 하셨다.","나는 학교 뒤편 창고에 가서 기름을 한 통 가득 받아 왔다.","칠판을 꽉 채운 분필 글씨를 공책에 옮겨 쓰고 선생님께 검사를 받았다.","바쁜 아침이었다."],"title":"1991년 어느 초등학생의 일기 — 교과서 12쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_basic#2','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',1,'sa','auto','1980년 신문 기사에서 옛날 초등학교를 부르던 이름을 찾아 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C1","difficulty":1,"kind":"sa","stem":"1980년 신문 기사에서 옛날 초등학교를 부르던 이름을 찾아 네 글자로 쓰세요.","answer":["국민학교"],"explanation":["기사 첫 줄을 봐요.","오늘날의 초등학교예요.","국민학교예요."],"asset":{"type":"passage","lines":["㉮ 한 국민학교는 전교생이 9천 명이 넘는다.","㉮ 2학년이 22반, 3학년이 21반 등 모두 115학급이 있다.","㉮ 1학년부터 4학년까지는 오전반, 오후반으로 나누어 수업한다.","㉯ 점심시간 종이 울리자 학생들은 환호성을 지르며 도시락을 꺼낸다.","㉯ 짝끼리 이야기를 나누며 먹고, 친구들끼리 반찬을 나눠 먹기도 한다."],"numbered":false,"title":"1980년 신문 기사 두 개 — 교과서 13쪽"},"mis":"SO3-2-u1-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_basic#3','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',1,'ox','auto','사회 곳곳에서는 예전에 있던 모습이 다른 모습으로 변하기도 해요.',ARRAY['SO3-2-u1-X01']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C1","difficulty":1,"kind":"ox","stem":"사회 곳곳에서는 예전에 있던 모습이 다른 모습으로 변하기도 해요.","answer":"O","reason_options":[{"t":"사라지는 모습, 새로 생기는 모습과 함께 다른 모습으로 바뀌는 모습도 있기 때문에","correct":true},{"t":"한번 생긴 모습은 언제나 그대로 남기 때문에","mis":"SO3-2-u1-X01"}],"mis":"SO3-2-u1-X01","explanation":["사회의 모습은 끊임없이 변해요.","바뀌는 모습도 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_basic#4','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',1,'mc','auto','교과서 14쪽에서 우리 사회가 변화하는 원인으로 든 것이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u1-X02']::text[],true,'{"seq":4,"concept":"SO3-2-u1-C1","difficulty":1,"kind":"mc","stem":"교과서 14쪽에서 우리 사회가 변화하는 원인으로 든 것이 아닌 것은 무엇인가요?","options":[{"t":"계절이 바뀌는 것","correct":true},{"t":"사람 수의 변화","mis":"SO3-2-u1-X02"},{"t":"평균 수명의 증가","mis":"SO3-2-u1-X02"},{"t":"다른 나라와의 교류","mis":"SO3-2-u1-X02"}],"explanation":["원인 다섯 가지를 떠올려요.","사람 수·수명·생각·과학 기술·교류예요.","계절은 들지 않았어요."],"variant_rule":{"alt":[{"stem":"교과서 14쪽에서 우리 사회가 변화하는 원인으로 든 것은 무엇인가요?","options":[{"t":"과학 기술의 발달","correct":true},{"t":"해가 뜨고 지는 것","mis":"SO3-2-u1-X02"},{"t":"달력이 넘어가는 것","mis":"SO3-2-u1-X02"},{"t":"계절이 바뀌는 것","mis":"SO3-2-u1-X02"}],"explanation":["사회를 바꾸는 원인을 찾아요.","새로운 기술이 생활을 바꿔요.","과학 기술의 발달이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_basic#5','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',2,'mc','auto','신문 기사 ㉮에서 1학년부터 4학년까지 오전반, 오후반으로 나누어 수업한 까닭은 무엇인가요?',ARRAY['SO3-2-u1-X03']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C1","difficulty":2,"kind":"mc","stem":"신문 기사 ㉮에서 1학년부터 4학년까지 오전반, 오후반으로 나누어 수업한 까닭은 무엇인가요?","options":[{"t":"학생은 많고 교실은 부족했기 때문이에요","correct":true},{"t":"학생이 적어 한 반이면 충분했기 때문이에요","mis":"SO3-2-u1-X03"},{"t":"점심 도시락을 두 번 먹기 위해서예요","mis":"SO3-2-u1-X03"},{"t":"선생님이 오후에만 오셨기 때문이에요","mis":"SO3-2-u1-X03"}],"explanation":["전교생이 9천 명이 넘었어요.","교실이 모자랐어요.","그래서 오전반, 오후반으로 나누었어요."],"asset":{"type":"passage","lines":["㉮ 한 국민학교는 전교생이 9천 명이 넘는다.","㉮ 2학년이 22반, 3학년이 21반 등 모두 115학급이 있다.","㉮ 1학년부터 4학년까지는 오전반, 오후반으로 나누어 수업한다.","㉯ 점심시간 종이 울리자 학생들은 환호성을 지르며 도시락을 꺼낸다.","㉯ 짝끼리 이야기를 나누며 먹고, 친구들끼리 반찬을 나눠 먹기도 한다."],"numbered":false,"title":"1980년 신문 기사 두 개 — 교과서 13쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_basic#6','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',2,'match','auto','교과서 14쪽 그림 속 장면과 그렇게 달라진 원인을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u1-C1","difficulty":2,"kind":"match","stem":"교과서 14쪽 그림 속 장면과 그렇게 달라진 원인을 이으세요.","pairs":[{"l":"㉠ 초등학교 폐교","r":"사람 수의 변화"},{"l":"㉡ 새로 생긴 노인 복지관","r":"평균 수명의 증가"},{"l":"㉢ 청소하는 로봇","r":"과학 기술의 발달"},{"l":"㉣ 세계 음식 문화 거리","r":"다른 나라와의 교류"}],"mis":"SO3-2-u1-X02","explanation":["어린이가 줄어 학교가 문을 닫아요.","오래 살게 되어 노인 복지관이 생겨요.","기술과 교류도 생활을 바꿔요."],"asset":{"type":"passage","lines":["㉠ 텔레비전 뉴스 — 초등학교 폐교 잇따라","㉡ 노인 복지관 앞 — 노인 복지관이 한 곳 더 생겼네요.","㉢ 광고 속 로봇 — 똑똑하고 완벽하게 끝내는 청소","㉣ 휴대 전화 화면 — #세계음식문화거리 #다양한음식"],"numbered":false,"title":"교과서 14쪽 그림 속 네 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_basic#7','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',2,'blank','auto','사람들이 오가거나 물건, 기술 등을 서로 주고받는 것을 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X02','SO3-2-u1-X01']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C1","difficulty":2,"kind":"blank","stem":"사람들이 오가거나 물건, 기술 등을 서로 주고받는 것을 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"교류","correct":true},{"t":"수명","mis":"SO3-2-u1-X02"},{"t":"폐교","mis":"SO3-2-u1-X02"},{"t":"변화","mis":"SO3-2-u1-X01"}],"explanation":["교과서 14쪽 낱말 풀이를 떠올려요.","서로 주고받는 것이에요.","교류예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_basic#8','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',2,'mc','auto','1980년 신문 기사 속 학교와 오늘날 학교를 견준 것으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X03','SO3-2-u1-X01']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C1","difficulty":2,"kind":"mc","stem":"1980년 신문 기사 속 학교와 오늘날 학교를 견준 것으로 알맞은 것은 무엇인가요?","options":[{"t":"옛날에는 3학년이 21반까지 있었지만 오늘날 우리 학교 3학년은 4반까지 있어요","correct":true},{"t":"옛날에도 오늘날처럼 점심시간에 급식을 먹었어요","mis":"SO3-2-u1-X03"},{"t":"옛날 학교가 오늘날보다 학생 수가 적었어요","mis":"SO3-2-u1-X03"},{"t":"옛날과 오늘날 학교 이름은 똑같아요","mis":"SO3-2-u1-X01"}],"explanation":["기사에 3학년이 21반까지 있었어요.","오늘날에는 반이 훨씬 적어요.","학교 모습이 달라졌어요."],"asset":{"type":"passage","lines":["㉮ 한 국민학교는 전교생이 9천 명이 넘는다.","㉮ 2학년이 22반, 3학년이 21반 등 모두 115학급이 있다.","㉮ 1학년부터 4학년까지는 오전반, 오후반으로 나누어 수업한다.","㉯ 점심시간 종이 울리자 학생들은 환호성을 지르며 도시락을 꺼낸다.","㉯ 짝끼리 이야기를 나누며 먹고, 친구들끼리 반찬을 나눠 먹기도 한다."],"numbered":false,"title":"1980년 신문 기사 두 개 — 교과서 13쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_basic#9','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',2,'ox','auto','교과서 14쪽 낱말 풀이에서 「폐교」는 운영하지 않고 문을 닫는 학교를 말해요.',ARRAY['SO3-2-u1-X01']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C1","difficulty":2,"kind":"ox","stem":"교과서 14쪽 낱말 풀이에서 「폐교」는 운영하지 않고 문을 닫는 학교를 말해요.","answer":"O","reason_options":[{"t":"교과서가 폐교를 운영하지 않고 문을 닫는 학교라고 풀이했기 때문에","correct":true},{"t":"새로 문을 연 학교를 폐교라고 하기 때문에","mis":"SO3-2-u1-X01"}],"mis":"SO3-2-u1-X01","explanation":["낱말 풀이를 봐요.","문을 닫은 학교예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_basic#10','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',3,'error','auto','사회 변화의 원인을 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X02']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C1","difficulty":3,"kind":"error","stem":"사회 변화의 원인을 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 다 — 「노인 복지관이 새로 생긴 건 다른 나라와 교류했기 때문이야.」","correct":true,"mis_target":"SO3-2-u1-X02"},{"t":"친구 가 — 「어린이 수가 줄어 문을 닫는 학교가 생겼어.」","mis":"SO3-2-u1-X02"},{"t":"친구 나 — 「과학 기술이 발달해 로봇이 집 청소를 해.」","mis":"SO3-2-u1-X02"}],"explanation":["노인 복지관은 노인과 관계있어요.","사람들이 오래 살게 되었어요.","친구 다가 원인을 잘못 짝지었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_challenge#1','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',2,'sa','auto','태어나서부터 죽을 때까지 살아 있는 기간을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C1","difficulty":2,"kind":"sa","stem":"태어나서부터 죽을 때까지 살아 있는 기간을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["수명"],"explanation":["교과서 14쪽 낱말 풀이예요.","평균 ○○의 증가에 나와요.","수명이에요."],"mis":"SO3-2-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_challenge#2','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',2,'ox','auto','1980년 두 번째 기사에서 학생들은 점심시간에 짝끼리 이야기를 나누며 도시락을 먹었어요.',ARRAY['SO3-2-u1-X03']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C1","difficulty":2,"kind":"ox","stem":"1980년 두 번째 기사에서 학생들은 점심시간에 짝끼리 이야기를 나누며 도시락을 먹었어요.","answer":"O","reason_options":[{"t":"종이 울리자 도시락을 꺼내 짝끼리 이야기를 나누며 먹었다고 했기 때문에","correct":true},{"t":"옛날에도 오늘날처럼 급식을 받아 먹었기 때문에","mis":"SO3-2-u1-X03"}],"mis":"SO3-2-u1-X03","explanation":["기사 ㉯를 읽어요.","도시락을 꺼냈어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 한 국민학교는 전교생이 9천 명이 넘는다.","㉮ 2학년이 22반, 3학년이 21반 등 모두 115학급이 있다.","㉮ 1학년부터 4학년까지는 오전반, 오후반으로 나누어 수업한다.","㉯ 점심시간 종이 울리자 학생들은 환호성을 지르며 도시락을 꺼낸다.","㉯ 짝끼리 이야기를 나누며 먹고, 친구들끼리 반찬을 나눠 먹기도 한다."],"numbered":false,"title":"1980년 신문 기사 두 개 — 교과서 13쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_challenge#3','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',3,'mc','auto','자료의 기사 세 개 가운데 어린이 수가 줄어든 것과 가장 관계있는 것은 무엇인가요?',ARRAY['SO3-2-u1-X02','SO3-2-u1-X01']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C1","difficulty":3,"kind":"mc","stem":"자료의 기사 세 개 가운데 어린이 수가 줄어든 것과 가장 관계있는 것은 무엇인가요?","options":[{"t":"원생이 부족해 문을 닫는 어린이집이 늘고 있다는 기사","correct":true},{"t":"노인 복지 시설이 늘었다는 기사","mis":"SO3-2-u1-X02"},{"t":"로봇 직원이 음식을 만든다는 기사","mis":"SO3-2-u1-X02"},{"t":"세 기사 모두 관계없어요","mis":"SO3-2-u1-X01"}],"explanation":["원생은 어린이집에 다니는 아이예요.","아이가 줄면 원생도 줄어요.","어린이집 기사예요."],"asset":{"type":"passage","lines":["어린이집 기사 — 원생이 부족해 문을 닫는 어린이집이 늘고 있다.","　(전국 어린이집 5곳 중 1곳이 문을 닫았다.)","노인 복지 시설 기사 — 5년 동안 3,737곳에서 4,335곳으로 늘었다.","로봇 기사 — 로봇 직원이 주문을 받아 3분 만에 조리하고 포장한다."],"numbered":false,"title":"사회 변화를 보여 주는 신문 기사 세 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_challenge#4','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',3,'mc','auto','자료에서 노인 복지 시설은 5년 동안 몇 곳 늘었나요?',ARRAY['SO3-2-u1-X05']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C1","difficulty":3,"kind":"mc","stem":"자료에서 노인 복지 시설은 5년 동안 몇 곳 늘었나요?","options":[{"t":"598곳","correct":true},{"t":"3,737곳","mis":"SO3-2-u1-X05"},{"t":"4,335곳","mis":"SO3-2-u1-X05"},{"t":"5곳","mis":"SO3-2-u1-X05"}],"explanation":["처음 수와 나중 수를 찾아요.","3,737곳에서 4,335곳이 되었어요.","598곳 늘었어요."],"asset":{"type":"passage","lines":["어린이집 기사 — 원생이 부족해 문을 닫는 어린이집이 늘고 있다.","　(전국 어린이집 5곳 중 1곳이 문을 닫았다.)","노인 복지 시설 기사 — 5년 동안 3,737곳에서 4,335곳으로 늘었다.","로봇 기사 — 로봇 직원이 주문을 받아 3분 만에 조리하고 포장한다."],"numbered":false,"title":"사회 변화를 보여 주는 신문 기사 세 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_challenge#5','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',3,'mc','auto','로봇 기사처럼 사람 대신 로봇이 일하는 모습이 늘어난 원인으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X02']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C1","difficulty":3,"kind":"mc","stem":"로봇 기사처럼 사람 대신 로봇이 일하는 모습이 늘어난 원인으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"과학 기술의 발달","correct":true},{"t":"평균 수명의 증가","mis":"SO3-2-u1-X02"},{"t":"사람 수의 변화","mis":"SO3-2-u1-X02"},{"t":"다른 나라와의 교류","mis":"SO3-2-u1-X02"}],"explanation":["로봇이 주문을 받고 조리해요.","새 기술 덕분이에요.","과학 기술의 발달이에요."],"asset":{"type":"passage","lines":["어린이집 기사 — 원생이 부족해 문을 닫는 어린이집이 늘고 있다.","　(전국 어린이집 5곳 중 1곳이 문을 닫았다.)","노인 복지 시설 기사 — 5년 동안 3,737곳에서 4,335곳으로 늘었다.","로봇 기사 — 로봇 직원이 주문을 받아 3분 만에 조리하고 포장한다."],"numbered":false,"title":"사회 변화를 보여 주는 신문 기사 세 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_challenge#6','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',3,'error','auto','1991년 일기와 1980년 기사를 읽고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X01','SO3-2-u1-X03']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C1","difficulty":3,"kind":"error","stem":"1991년 일기와 1980년 기사를 읽고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 나 — 「옛날 학교는 오늘날 학교와 다른 점이 하나도 없어.」","correct":true,"mis_target":"SO3-2-u1-X01"},{"t":"친구 가 — 「옛날 교실에는 난로가 있었어.」","mis":"SO3-2-u1-X03"},{"t":"친구 다 — 「옛날 학교는 지금보다 반이 훨씬 많았어.」","mis":"SO3-2-u1-X03"}],"explanation":["난로와 기름을 떠올려요.","반이 21반까지 있었어요.","친구 나가 바르지 않게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_challenge#7','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',3,'ox','auto','학교 이름이 국민학교에서 초등학교로 바뀐 것처럼 예전에 있던 모습이 다른 모습으로 변하는 것도 사회 변화예요.',ARRAY['SO3-2-u1-X01']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C1","difficulty":3,"kind":"ox","stem":"학교 이름이 국민학교에서 초등학교로 바뀐 것처럼 예전에 있던 모습이 다른 모습으로 변하는 것도 사회 변화예요.","answer":"O","reason_options":[{"t":"사회 변화에는 사라지고 생기는 모습뿐 아니라 다른 모습으로 바뀌는 모습도 있기 때문에","correct":true},{"t":"이름만 바뀐 것은 사회 모습이 변한 것이 아니기 때문에","mis":"SO3-2-u1-X01"}],"mis":"SO3-2-u1-X01","explanation":["바뀌는 모습도 사회 변화예요.","국민학교가 초등학교가 되었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_challenge#8','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',4,'mc','auto','교과서 14쪽 그림의 네 장면을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X02','SO3-2-u1-X01','SO3-2-u1-X03']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C1","difficulty":4,"kind":"mc","stem":"교과서 14쪽 그림의 네 장면을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"여러 가지 원인으로 사회가 변하면서 사람들의 생활 모습도 달라지고 있어요","correct":true},{"t":"사회는 과학 기술 한 가지 때문에만 변해요","mis":"SO3-2-u1-X02"},{"t":"사회 모습은 사라지기만 하고 새로 생기지는 않아요","mis":"SO3-2-u1-X01"},{"t":"네 장면은 옛날 모습이라 오늘날과 관계없어요","mis":"SO3-2-u1-X03"}],"explanation":["네 장면의 원인이 서로 달라요.","사회가 여러 까닭으로 변해요.","생활 모습도 달라져요."],"asset":{"type":"passage","lines":["㉠ 텔레비전 뉴스 — 초등학교 폐교 잇따라","㉡ 노인 복지관 앞 — 노인 복지관이 한 곳 더 생겼네요.","㉢ 광고 속 로봇 — 똑똑하고 완벽하게 끝내는 청소","㉣ 휴대 전화 화면 — #세계음식문화거리 #다양한음식"],"numbered":false,"title":"교과서 14쪽 그림 속 네 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_challenge#9','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',4,'mc','auto','옛날 학교에 오전반, 오후반이 있었던 것과 오늘날 문을 닫는 학교가 생기는 것에 공통으로 영향을 준 원인은 무엇인가요?',ARRAY['SO3-2-u1-X02']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C1","difficulty":4,"kind":"mc","stem":"옛날 학교에 오전반, 오후반이 있었던 것과 오늘날 문을 닫는 학교가 생기는 것에 공통으로 영향을 준 원인은 무엇인가요?","options":[{"t":"사람 수의 변화","correct":true},{"t":"과학 기술의 발달","mis":"SO3-2-u1-X02"},{"t":"다른 나라와의 교류","mis":"SO3-2-u1-X02"},{"t":"평균 수명의 증가","mis":"SO3-2-u1-X02"}],"explanation":["옛날에는 학생이 많았어요.","오늘날에는 어린이가 줄었어요.","둘 다 사람 수의 변화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L01_challenge#10','soc',3,2,'u1','L01','tb_g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',4,'essay','teacher','교과서 자료나 주변 어른께 들은 이야기를 떠올려, 옛날과 오늘날 달라진 생활 모습 한 가지를 쓰고 그렇게 달라진 원인을 교과서의 원인 다섯 가지 가운데 하나와 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C1","difficulty":4,"kind":"essay","stem":"교과서 자료나 주변 어른께 들은 이야기를 떠올려, 옛날과 오늘날 달라진 생활 모습 한 가지를 쓰고 그렇게 달라진 원인을 교과서의 원인 다섯 가지 가운데 하나와 이어 쓰세요.","answer_guide":{"answer":"예: 옛날에는 3학년이 21반까지 있었지만 오늘날 우리 학교 3학년은 4반까지 있어요. 어린이의 수가 줄어든 사람 수의 변화 때문이에요.","scoring_points":["옛날과 오늘날 모습을 견주었는가","원인 다섯 가지 가운데 하나를 골랐는가","모습과 원인이 알맞게 이어지는가"]},"explanation":["옛날 모습과 오늘 모습을 견줘요.","원인 다섯 가지를 떠올려요.","알맞은 원인과 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_basic#1','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',1,'mc','auto','태어나는 아이의 수가 줄어들어 출산율이 감소하는 현상을 가리키는 말은 무엇인가요?',ARRAY['SO3-2-u1-X04']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C2","difficulty":1,"kind":"mc","stem":"태어나는 아이의 수가 줄어들어 출산율이 감소하는 현상을 가리키는 말은 무엇인가요?","options":[{"t":"저출산","correct":true},{"t":"출산율","mis":"SO3-2-u1-X04"},{"t":"평균 수명","mis":"SO3-2-u1-X04"},{"t":"교류","mis":"SO3-2-u1-X04"}],"explanation":["태어나는 아이가 줄어요.","출산율이 감소해요.","저출산이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_basic#2','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',1,'sa','auto','그래프에서 1990년에 태어난 아이의 수는 몇만 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"SO3-2-u1-C2","difficulty":1,"kind":"sa","stem":"그래프에서 1990년에 태어난 아이의 수는 몇만 명인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["1990년 막대를 찾아요.","단위는 만 명이에요.","65만 명이에요."],"asset":{"type":"passage","lines":["1970년 — 101만 명 · 1980년 — 86만 명","1990년 — 65만 명 · 2000년 — 64만 명","2010년 — 47만 명 · 2020년 — 27만 명","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"numbered":false,"title":"우리나라에서 연도별 태어나는 아이의 수 — 교과서 15쪽 그래프"},"mis":"SO3-2-u1-X05","variant_rule":{"alt":[{"stem":"그래프에서 2010년에 태어난 아이의 수는 몇만 명인가요? 숫자로 쓰세요.","answer":["47"],"explanation":["2010년 막대를 찾아요.","단위는 만 명이에요.","47만 명이에요."],"asset":{"type":"passage","lines":["1970년 — 101만 명 · 1980년 — 86만 명","1990년 — 65만 명 · 2000년 — 64만 명","2010년 — 47만 명 · 2020년 — 27만 명","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"numbered":false,"title":"우리나라에서 연도별 태어나는 아이의 수 — 교과서 15쪽 그래프"}},{"stem":"그래프에서 1980년에 태어난 아이의 수는 몇만 명인가요? 숫자로 쓰세요.","answer":["86"],"explanation":["1980년 막대를 찾아요.","단위는 만 명이에요.","86만 명이에요."],"asset":{"type":"passage","lines":["1970년 — 101만 명 · 1980년 — 86만 명","1990년 — 65만 명 · 2000년 — 64만 명","2010년 — 47만 명 · 2020년 — 27만 명","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"numbered":false,"title":"우리나라에서 연도별 태어나는 아이의 수 — 교과서 15쪽 그래프"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_basic#3','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',1,'ox','auto','그래프를 읽을 때는 먼저 그래프의 제목을 확인해요.',ARRAY['SO3-2-u1-X05']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C2","difficulty":1,"kind":"ox","stem":"그래프를 읽을 때는 먼저 그래프의 제목을 확인해요.","answer":"O","reason_options":[{"t":"제목 확인 → 가로와 세로 확인 → 막대가 나타내는 수 확인 차례로 읽기 때문에","correct":true},{"t":"막대 길이만 보면 제목은 몰라도 되기 때문에","mis":"SO3-2-u1-X05"}],"mis":"SO3-2-u1-X05","explanation":["그래프 읽는 방법을 떠올려요.","제목이 첫 번째예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_basic#4','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',1,'blank','auto','저출산이 계속되면 학생 수가 (    ) 일할 수 있는 사람의 수도 줄어들 거예요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X06']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C2","difficulty":1,"kind":"blank","stem":"저출산이 계속되면 학생 수가 (    ) 일할 수 있는 사람의 수도 줄어들 거예요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"줄어들고","correct":true},{"t":"늘어나고","mis":"SO3-2-u1-X06"},{"t":"그대로이고","mis":"SO3-2-u1-X06"},{"t":"두 배가 되고","mis":"SO3-2-u1-X06"}],"explanation":["태어나는 아이가 줄어요.","학교에 다닐 어린이도 줄어요.","줄어들고예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_basic#5','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',2,'mc','auto','그래프의 가로와 세로가 나타내는 것을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u1-X05']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C2","difficulty":2,"kind":"mc","stem":"그래프의 가로와 세로가 나타내는 것을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"가로 — 연도, 세로 — 태어나는 아이의 수","correct":true},{"t":"가로 — 태어나는 아이의 수, 세로 — 연도","mis":"SO3-2-u1-X05"},{"t":"가로 — 학생 수, 세로 — 학교 수","mis":"SO3-2-u1-X05"},{"t":"가로 — 연도, 세로 — 학교의 수","mis":"SO3-2-u1-X05"}],"explanation":["아래쪽 줄은 몇 년인지예요.","세로는 몇만 명인지예요.","가로는 연도, 세로는 태어나는 아이의 수예요."],"asset":{"type":"passage","lines":["1970년 — 101만 명 · 1980년 — 86만 명","1990년 — 65만 명 · 2000년 — 64만 명","2010년 — 47만 명 · 2020년 — 27만 명","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"numbered":false,"title":"우리나라에서 연도별 태어나는 아이의 수 — 교과서 15쪽 그래프"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_basic#6','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',2,'match','auto','교과서 17쪽 저출산 해결 방법과 친구가 그 방법을 고른 까닭을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u1-C2","difficulty":2,"kind":"match","stem":"교과서 17쪽 저출산 해결 방법과 친구가 그 방법을 고른 까닭을 이으세요.","pairs":[{"l":"가 — 돈과 물품 지원","r":"아이를 키우는 데 돈이 필요하기 때문에"},{"l":"나 — 보육 시설 운영","r":"아이를 믿고 맡길 수 있는 곳이 필요하기 때문에"},{"l":"다 — 일을 쉴 수 있는 제도","r":"부모와 아이가 함께 지내는 시간이 중요하기 때문에"}],"mis":"SO3-2-u1-X07","explanation":["돈이 드는 일을 도와요.","맡길 곳을 만들어요.","함께 지낼 시간을 줘요."],"asset":{"type":"passage","lines":["가 — 아이를 낳고 키우는 데 필요한 돈과 물품 등을 지원해요.","　(어린 자녀가 있거나 자녀가 많은 가정에 전기·가스·수도 요금 할인)","나 — 안전하고 쾌적한 보육 시설을 만들고 운영해요.","다 — 부모가 자녀를 키우기 위해 일정 기간 일을 쉴 수 있는 제도를 운영해요."],"numbered":false,"title":"저출산 문제를 해결하기 위한 방법 — 교과서 17쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_basic#7','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',2,'mc','auto','교과서 16쪽에서 저출산으로 나타나는 일상생활 모습이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u1-X06']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C2","difficulty":2,"kind":"mc","stem":"교과서 16쪽에서 저출산으로 나타나는 일상생활 모습이 아닌 것은 무엇인가요?","options":[{"t":"출산을 도와주는 병원의 수가 늘어나요","correct":true},{"t":"가족 구성원의 수가 줄어들어요","mis":"SO3-2-u1-X06"},{"t":"학생 수가 줄어들어요","mis":"SO3-2-u1-X06"},{"t":"일할 수 있는 사람의 수가 줄어들 것으로 예상돼요","mis":"SO3-2-u1-X06"}],"explanation":["아이가 줄면 무엇이 달라질까요?","출산을 도와주는 병원도 줄어요.","늘어난다는 말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_basic#8','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',2,'blank','auto','여성 한 명이 임신이 가능한 기간(15~49세)에 낳을 것으로 예상되는 평균적인 아이의 수로 알 수 있는 것은 (    )이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X04']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C2","difficulty":2,"kind":"blank","stem":"여성 한 명이 임신이 가능한 기간(15~49세)에 낳을 것으로 예상되는 평균적인 아이의 수로 알 수 있는 것은 (    )이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"출산율","correct":true},{"t":"저출산","mis":"SO3-2-u1-X04"},{"t":"보육","mis":"SO3-2-u1-X04"},{"t":"평균 수명","mis":"SO3-2-u1-X04"}],"explanation":["교과서 15쪽 옆 풀이예요.","아이를 낳는 정도예요.","출산율이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_basic#9','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',2,'ox','auto','결혼하더라도 아이를 낳아 기르는 것에 부담을 느끼는 사람이 많아진 것은 저출산이 나타나는 까닭 가운데 하나예요.',ARRAY['SO3-2-u1-X04']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C2","difficulty":2,"kind":"ox","stem":"결혼하더라도 아이를 낳아 기르는 것에 부담을 느끼는 사람이 많아진 것은 저출산이 나타나는 까닭 가운데 하나예요.","answer":"O","reason_options":[{"t":"교과서 16쪽에서 아이를 기르는 데 부담을 느끼는 사람이 많아지며 저출산이 나타난다고 했기 때문에","correct":true},{"t":"저출산은 아이를 낳으려는 사람이 많아져서 생기기 때문에","mis":"SO3-2-u1-X04"}],"mis":"SO3-2-u1-X04","explanation":["부담을 느끼는 사람이 많아요.","아이를 적게 낳아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_basic#10','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',3,'error','auto','그래프를 읽고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X05','SO3-2-u1-X04']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C2","difficulty":3,"kind":"error","stem":"그래프를 읽고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 나 — 「2020년에 태어난 아이는 27명이야.」","correct":true,"mis_target":"SO3-2-u1-X05"},{"t":"친구 가 — 「1970년에는 101만 명이 태어났어.」","mis":"SO3-2-u1-X05"},{"t":"친구 다 — 「태어나는 아이의 수가 점점 줄어들고 있어.」","mis":"SO3-2-u1-X04"}],"explanation":["세로의 단위를 봐요.","단위는 만 명이에요.","친구 나는 27만 명을 27명으로 읽었어요."],"asset":{"type":"passage","lines":["1970년 — 101만 명 · 1980년 — 86만 명","1990년 — 65만 명 · 2000년 — 64만 명","2010년 — 47만 명 · 2020년 — 27만 명","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"numbered":false,"title":"우리나라에서 연도별 태어나는 아이의 수 — 교과서 15쪽 그래프"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_challenge#1','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',2,'sa','auto','어린아이들을 돌보아 기르는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C2","difficulty":2,"kind":"sa","stem":"어린아이들을 돌보아 기르는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["보육"],"explanation":["교과서 17쪽 낱말 풀이예요.","○○ 시설에 나와요.","보육이에요."],"mis":"SO3-2-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_challenge#2','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',2,'ox','auto','그래프에서 2000년에는 1990년보다 태어난 아이가 1만 명 적어요.',ARRAY['SO3-2-u1-X05']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C2","difficulty":2,"kind":"ox","stem":"그래프에서 2000년에는 1990년보다 태어난 아이가 1만 명 적어요.","answer":"O","reason_options":[{"t":"1990년은 65만 명, 2000년은 64만 명이라 1만 명 줄었기 때문에","correct":true},{"t":"막대 높이가 거의 같으면 수도 똑같기 때문에","mis":"SO3-2-u1-X05"}],"mis":"SO3-2-u1-X05","explanation":["65와 64를 견줘요.","조금이지만 줄었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["1970년 — 101만 명 · 1980년 — 86만 명","1990년 — 65만 명 · 2000년 — 64만 명","2010년 — 47만 명 · 2020년 — 27만 명","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"numbered":false,"title":"우리나라에서 연도별 태어나는 아이의 수 — 교과서 15쪽 그래프"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_challenge#3','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',3,'mc','auto','그래프에서 1970년과 2020년을 견주면 태어나는 아이의 수는 몇만 명 줄었나요?',ARRAY['SO3-2-u1-X05']::text[],true,'{"seq":3,"concept":"SO3-2-u1-C2","difficulty":3,"kind":"mc","stem":"그래프에서 1970년과 2020년을 견주면 태어나는 아이의 수는 몇만 명 줄었나요?","options":[{"t":"74만 명","correct":true},{"t":"27만 명","mis":"SO3-2-u1-X05"},{"t":"101만 명","mis":"SO3-2-u1-X05"},{"t":"128만 명","mis":"SO3-2-u1-X05"}],"explanation":["1970년에는 101만 명이에요.","2020년에는 27만 명이에요.","101에서 27을 빼면 74예요."],"asset":{"type":"passage","lines":["1970년 — 101만 명 · 1980년 — 86만 명","1990년 — 65만 명 · 2000년 — 64만 명","2010년 — 47만 명 · 2020년 — 27만 명","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"numbered":false,"title":"우리나라에서 연도별 태어나는 아이의 수 — 교과서 15쪽 그래프"},"variant_rule":{"alt":[{"stem":"그래프에서 1980년과 2010년을 견주면 태어나는 아이의 수는 몇만 명 줄었나요?","options":[{"t":"39만 명","correct":true},{"t":"47만 명","mis":"SO3-2-u1-X05"},{"t":"86만 명","mis":"SO3-2-u1-X05"},{"t":"133만 명","mis":"SO3-2-u1-X05"}],"explanation":["1980년에는 86만 명이에요.","2010년에는 47만 명이에요.","86에서 47을 빼면 39예요."],"asset":{"type":"passage","lines":["1970년 — 101만 명 · 1980년 — 86만 명","1990년 — 65만 명 · 2000년 — 64만 명","2010년 — 47만 명 · 2020년 — 27만 명","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"numbered":false,"title":"우리나라에서 연도별 태어나는 아이의 수 — 교과서 15쪽 그래프"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_challenge#4','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',3,'mc','auto','교과서 16쪽 생산 가능 인구 그래프를 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X06','SO3-2-u1-X05']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C2","difficulty":3,"kind":"mc","stem":"교과서 16쪽 생산 가능 인구 그래프를 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"일할 수 있는 사람의 수가 2020년보다 2050년에 더 적을 것으로 예상돼요","correct":true},{"t":"일할 수 있는 사람의 수가 점점 늘어날 것으로 예상돼요","mis":"SO3-2-u1-X06"},{"t":"그래프는 이미 지나간 해의 수만 나타내요","mis":"SO3-2-u1-X05"},{"t":"2030년의 수가 가장 많을 것으로 예상돼요","mis":"SO3-2-u1-X05"}],"explanation":["2020년에는 3,738만 명이에요.","2050년에는 2,444만 명으로 예상돼요.","일할 수 있는 사람이 줄어들어요."],"asset":{"type":"passage","lines":["2020년 — 3,738만 명","2030년 — 3,416만 명","2040년 — 2,902만 명","2050년 — 2,444만 명"],"numbered":false,"title":"생산 가능 인구(15~64세)의 변화 예상 — 교과서 16쪽 그래프"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_challenge#5','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',3,'mc','auto','자료의 ○○구가 하는 일이 저출산에 줄 영향을 예상한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X07','SO3-2-u1-X06']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C2","difficulty":3,"kind":"mc","stem":"자료의 ○○구가 하는 일이 저출산에 줄 영향을 예상한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"임산부나 아기를 키우는 가정에 도움이 되어 저출산 문제를 해결하는 데 보탬이 될 것 같아요","correct":true},{"t":"아이를 키우는 부담이 더 커질 것 같아요","mis":"SO3-2-u1-X07"},{"t":"저출산과는 아무 관계가 없을 것 같아요","mis":"SO3-2-u1-X07"},{"t":"학생 수가 더 빨리 줄어들 것 같아요","mis":"SO3-2-u1-X06"}],"explanation":["교통비와 물품을 지원해요.","아이를 키우는 부담이 줄어요.","저출산 문제 해결에 도움이 돼요."],"asset":{"type":"passage","lines":["임산부가 안전하게 이동할 수 있도록 교통비를 지원한다.","24개월 이하 아기를 키우는 가정에 택시 이용 포인트를 준다.","아이를 가지려고 노력하는 부부에게 의료비를 지원한다.","태어나는 아이를 위한 물품을 지원한다."],"numbered":false,"title":"○○구가 하는 일 — 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_challenge#6','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',3,'error','auto','교과서 17쪽 방법 가운데 가장 도움이 되는 것을 고르며 친구들이 나눈 이야기예요. 바르지 않게 말한 친구를 고르세요.',ARRAY['SO3-2-u1-X35','SO3-2-u1-X07']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C2","difficulty":3,"kind":"error","stem":"교과서 17쪽 방법 가운데 가장 도움이 되는 것을 고르며 친구들이 나눈 이야기예요. 바르지 않게 말한 친구를 고르세요.","options":[{"t":"친구 다 — 「보육 시설만 정답이야. 다른 방법을 고른 까닭은 들을 필요 없어.」","correct":true,"mis_target":"SO3-2-u1-X35"},{"t":"친구 가 — 「아이를 키우는 데 돈이 필요하니 돈과 물품 지원이 도움이 돼.」","mis":"SO3-2-u1-X07"},{"t":"친구 나 — 「부모와 아이가 함께 지내는 시간이 중요하니 일을 쉬는 제도가 좋아.」","mis":"SO3-2-u1-X07"}],"explanation":["세 방법 모두 도움이 돼요.","고른 까닭을 서로 들어 봐요.","친구 다가 바르지 않게 말했어요."],"asset":{"type":"passage","lines":["가 — 아이를 낳고 키우는 데 필요한 돈과 물품 등을 지원해요.","　(어린 자녀가 있거나 자녀가 많은 가정에 전기·가스·수도 요금 할인)","나 — 안전하고 쾌적한 보육 시설을 만들고 운영해요.","다 — 부모가 자녀를 키우기 위해 일정 기간 일을 쉴 수 있는 제도를 운영해요."],"numbered":false,"title":"저출산 문제를 해결하기 위한 방법 — 교과서 17쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_challenge#7','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',3,'ox','auto','어린 자녀가 있거나 자녀가 많은 가정에 전기, 가스, 수도, 주차 요금을 할인해 주는 것은 저출산 문제를 해결하려는 노력이에요.',ARRAY['SO3-2-u1-X07']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C2","difficulty":3,"kind":"ox","stem":"어린 자녀가 있거나 자녀가 많은 가정에 전기, 가스, 수도, 주차 요금을 할인해 주는 것은 저출산 문제를 해결하려는 노력이에요.","answer":"O","reason_options":[{"t":"아이를 낳고 키우는 데 드는 돈을 덜어 주는 지원이기 때문에","correct":true},{"t":"요금 할인은 아이를 키우는 일과 관계없기 때문에","mis":"SO3-2-u1-X07"}],"mis":"SO3-2-u1-X07","explanation":["돈과 물품 지원에 들어가요.","키우는 부담을 덜어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_challenge#8','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',4,'mc','auto','저출산이 계속될 때 우리 사회에 나타날 모습을 예상한 것으로 근거가 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X06']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C2","difficulty":4,"kind":"mc","stem":"저출산이 계속될 때 우리 사회에 나타날 모습을 예상한 것으로 근거가 가장 알맞은 것은 무엇인가요?","options":[{"t":"태어나는 아이가 줄어 유치원이나 초등학교의 수가 지금보다 더 줄어들 것 같아요","correct":true},{"t":"학생이 늘어 교실이 부족해질 것 같아요","mis":"SO3-2-u1-X06"},{"t":"출산을 도와주는 병원이 많아져 진료가 쉬워질 것 같아요","mis":"SO3-2-u1-X06"},{"t":"회사에서 일할 사람이 남아돌 것 같아요","mis":"SO3-2-u1-X06"}],"explanation":["태어나는 아이가 줄어요.","학교에 다닐 어린이도 줄어요.","유치원과 학교가 더 줄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_challenge#9','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',4,'mc','auto','친구들이 저출산 해결 방법을 서로 다르게 골랐을 때 가장 바람직한 태도는 무엇인가요?',ARRAY['SO3-2-u1-X35','SO3-2-u1-X07']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C2","difficulty":4,"kind":"mc","stem":"친구들이 저출산 해결 방법을 서로 다르게 골랐을 때 가장 바람직한 태도는 무엇인가요?","options":[{"t":"방법마다 도움이 되는 점이 다를 수 있으니 친구가 고른 까닭을 듣고 의견을 나눠요","correct":true},{"t":"가장 많은 친구가 고른 방법만 맞고 나머지는 쓸모없다고 해요","mis":"SO3-2-u1-X35"},{"t":"내가 고른 방법과 다르면 친구의 말을 듣지 않아요","mis":"SO3-2-u1-X35"},{"t":"저출산은 해결할 수 없으니 방법을 고를 필요가 없어요","mis":"SO3-2-u1-X07"}],"explanation":["세 방법은 돕는 점이 서로 달라요.","고른 까닭을 들어 봐요.","서로 의견을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L02_challenge#10','soc',3,2,'u1','L02','tb_g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',4,'essay','teacher','교과서 16쪽 그림과 그래프를 보고 저출산으로 달라지고 있는 우리 사회의 모습을 두 가지 쓰고, 저출산이 계속된다면 우리 사회가 어떻게 달라질지 근거를 들어 예상해 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C2","difficulty":4,"kind":"essay","stem":"교과서 16쪽 그림과 그래프를 보고 저출산으로 달라지고 있는 우리 사회의 모습을 두 가지 쓰고, 저출산이 계속된다면 우리 사회가 어떻게 달라질지 근거를 들어 예상해 쓰세요.","answer_guide":{"answer":"예: 가족 구성원의 수와 학생 수가 줄어들고 있어요. 생산 가능 인구가 2020년 3,738만 명에서 2050년 2,444만 명으로 줄어들 것으로 예상되니, 회사에서 일할 사람이 부족해질 것 같아요.","scoring_points":["달라지고 있는 모습 두 가지를 썼는가","그래프의 수를 근거로 들었는가","앞으로의 모습을 알맞게 예상했는가"]},"explanation":["16쪽 그림의 네 모습을 떠올려요.","그래프의 수를 근거로 들어요.","앞으로의 모습을 예상해요."],"asset":{"type":"passage","lines":["2020년 — 3,738만 명","2030년 — 3,416만 명","2040년 — 2,902만 명","2050년 — 2,444만 명"],"numbered":false,"title":"생산 가능 인구(15~64세)의 변화 예상 — 교과서 16쪽 그래프"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_basic#1','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',1,'mc','auto','교과서에서 노인이라고 하는 사람은 몇 세 이상인가요?',ARRAY['SO3-2-u1-X08']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C3","difficulty":1,"kind":"mc","stem":"교과서에서 노인이라고 하는 사람은 몇 세 이상인가요?","options":[{"t":"65세","correct":true},{"t":"15세","mis":"SO3-2-u1-X08"},{"t":"64세","mis":"SO3-2-u1-X08"},{"t":"100세","mis":"SO3-2-u1-X08"}],"explanation":["교과서 18쪽 말풍선을 봐요.","노인은 나이가 많은 어른이에요.","65세 이상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_basic#2','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',1,'sa','auto','일정한 양을 기준으로 어떤 양이 차지하는 정도를 나타낸 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C3","difficulty":1,"kind":"sa","stem":"일정한 양을 기준으로 어떤 양이 차지하는 정도를 나타낸 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["비율"],"explanation":["교과서 18쪽 낱말 풀이예요.","차지하는 정도예요.","비율이에요."],"mis":"SO3-2-u1-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_basic#3','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',1,'ox','auto','사람들이 오래 살게 된 까닭 가운데 하나는 깨끗한 환경에서 생활하게 된 것이에요.',ARRAY['SO3-2-u1-X09']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C3","difficulty":1,"kind":"ox","stem":"사람들이 오래 살게 된 까닭 가운데 하나는 깨끗한 환경에서 생활하게 된 것이에요.","answer":"O","reason_options":[{"t":"의학 기술이 발달하고 깨끗한 환경에서 생활하게 되면서 오래 살 수 있게 되었기 때문에","correct":true},{"t":"병원이 줄어 사람들이 덜 아프게 되었기 때문에","mis":"SO3-2-u1-X09"}],"mis":"SO3-2-u1-X09","explanation":["의학 기술이 발달했어요.","환경도 깨끗해졌어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_basic#4','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',1,'mc','auto','자료에서 2020년에는 100명 가운데 몇 명 정도가 노인이었나요?',ARRAY['SO3-2-u1-X05']::text[],true,'{"seq":4,"concept":"SO3-2-u1-C3","difficulty":1,"kind":"mc","stem":"자료에서 2020년에는 100명 가운데 몇 명 정도가 노인이었나요?","options":[{"t":"16명","correct":true},{"t":"4명","mis":"SO3-2-u1-X05"},{"t":"40명","mis":"SO3-2-u1-X05"},{"t":"65명","mis":"SO3-2-u1-X05"}],"explanation":["2020년 줄을 찾아요.","100명 가운데 노인의 수예요.","16명 정도예요."],"asset":{"type":"passage","lines":["1980년 — 100명 가운데 4명 정도가 노인이었어요.","2020년 — 100명 가운데 16명 정도가 노인이었어요.","2050년(예상) — 100명 가운데 40명 정도가 노인일 거예요.","(노인 — 65세 이상인 사람)"],"numbered":false,"title":"우리나라가 100명이 사는 마을이라면 — 교과서 18쪽"},"variant_rule":{"alt":[{"stem":"자료에서 1980년에는 100명 가운데 몇 명 정도가 노인이었나요?","options":[{"t":"4명","correct":true},{"t":"16명","mis":"SO3-2-u1-X05"},{"t":"40명","mis":"SO3-2-u1-X05"},{"t":"65명","mis":"SO3-2-u1-X05"}],"explanation":["1980년 줄을 찾아요.","100명 가운데 노인의 수예요.","4명 정도예요."],"asset":{"type":"passage","lines":["1980년 — 100명 가운데 4명 정도가 노인이었어요.","2020년 — 100명 가운데 16명 정도가 노인이었어요.","2050년(예상) — 100명 가운데 40명 정도가 노인일 거예요.","(노인 — 65세 이상인 사람)"],"numbered":false,"title":"우리나라가 100명이 사는 마을이라면 — 교과서 18쪽"}},{"stem":"자료에서 2050년(예상)에는 100명 가운데 몇 명 정도가 노인일까요?","options":[{"t":"40명","correct":true},{"t":"4명","mis":"SO3-2-u1-X05"},{"t":"16명","mis":"SO3-2-u1-X05"},{"t":"65명","mis":"SO3-2-u1-X05"}],"explanation":["2050년 줄을 찾아요.","예상한 수예요.","40명 정도예요."],"asset":{"type":"passage","lines":["1980년 — 100명 가운데 4명 정도가 노인이었어요.","2020년 — 100명 가운데 16명 정도가 노인이었어요.","2050년(예상) — 100명 가운데 40명 정도가 노인일 거예요.","(노인 — 65세 이상인 사람)"],"numbered":false,"title":"우리나라가 100명이 사는 마을이라면 — 교과서 18쪽"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_basic#5','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',2,'blank','auto','자료를 보고 고른 말로 알맞은 것은 무엇인가요? 1980년보다 2020년에는 전체 사람 수에서 노인의 수가 차지하는 비율이 (    ).',ARRAY['SO3-2-u1-X08','SO3-2-u1-X05']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C3","difficulty":2,"kind":"blank","stem":"자료를 보고 고른 말로 알맞은 것은 무엇인가요? 1980년보다 2020년에는 전체 사람 수에서 노인의 수가 차지하는 비율이 (    ).","options":[{"t":"높아졌어요","correct":true},{"t":"낮아졌어요","mis":"SO3-2-u1-X08"},{"t":"똑같아요","mis":"SO3-2-u1-X05"},{"t":"알 수 없어요","mis":"SO3-2-u1-X05"}],"explanation":["두 마을 모두 100명이에요.","노인이 4명에서 16명이 되었어요.","비율이 높아졌어요."],"asset":{"type":"passage","lines":["1980년 — 100명 가운데 4명 정도가 노인이었어요.","2020년 — 100명 가운데 16명 정도가 노인이었어요.","2050년(예상) — 100명 가운데 40명 정도가 노인일 거예요.","(노인 — 65세 이상인 사람)"],"numbered":false,"title":"우리나라가 100명이 사는 마을이라면 — 교과서 18쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_basic#6','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',2,'match','auto','교과서 19쪽 사진 속 모습과 그 모습이 노인에게 주는 도움을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u1-C3","difficulty":2,"kind":"match","stem":"교과서 19쪽 사진 속 모습과 그 모습이 노인에게 주는 도움을 이으세요.","pairs":[{"l":"① 노인 전문 병원·요양 시설","r":"건강을 돌보고 편히 쉬며 병을 치료해요"},{"l":"② 여러 가지 프로그램","r":"새로운 것을 배울 기회를 줘요"},{"l":"③ 학교나 회사에서 하는 일","r":"사람들에게 도움을 주며 일할 수 있어요"}],"mis":"SO3-2-u1-X10","explanation":["병원과 요양 시설은 건강을 돌봐요.","프로그램은 배움의 기회예요.","일을 하는 노인도 늘어요."],"asset":{"type":"passage","lines":["① 노인들의 건강을 위한 노인 전문 병원이나 요양 시설을 운영해요.","② 노인들에게 배움의 기회를 주는 여러 가지 프로그램을 운영해요.","③ 노인들이 학교나 회사 등에서 사람들에게 도움을 주는 일을 해요."],"numbered":false,"title":"고령화로 달라진 생활 모습 — 교과서 19쪽 사진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_basic#7','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',2,'blank','auto','편히 쉬면서 병을 치료하는 시설을 (    ) 시설이라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X10']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C3","difficulty":2,"kind":"blank","stem":"편히 쉬면서 병을 치료하는 시설을 (    ) 시설이라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"요양","correct":true},{"t":"보육","mis":"SO3-2-u1-X10"},{"t":"교육","mis":"SO3-2-u1-X10"},{"t":"복지","mis":"SO3-2-u1-X10"}],"explanation":["교과서 19쪽 낱말 풀이예요.","쉬면서 병을 치료해요.","요양 시설이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_basic#8','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',2,'mc','auto','교과서 20쪽에서 고령화로 생기는 문제로 든 것은 무엇인가요?',ARRAY['SO3-2-u1-X10','SO3-2-u1-X08','SO3-2-u1-X33']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C3","difficulty":2,"kind":"mc","stem":"교과서 20쪽에서 고령화로 생기는 문제로 든 것은 무엇인가요?","options":[{"t":"노인들의 건강을 관리하고 생활을 유지하는 데 필요한 비용이 점점 늘어나요","correct":true},{"t":"노인을 위한 시설이 모두 없어져요","mis":"SO3-2-u1-X10"},{"t":"노인의 비율이 낮아져 학교가 부족해져요","mis":"SO3-2-u1-X08"},{"t":"노인이 오래 사는 것 자체가 나쁜 일이에요","mis":"SO3-2-u1-X33"}],"explanation":["노인이 많아졌어요.","건강과 생활에 드는 돈이 늘어요.","그것이 고령화로 생기는 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_basic#9','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',2,'ox','auto','나라에서 노인에게 매달 돈을 주는 것은 노인의 생활을 돕는 복지 제도예요.',ARRAY['SO3-2-u1-X10']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C3","difficulty":2,"kind":"ox","stem":"나라에서 노인에게 매달 돈을 주는 것은 노인의 생활을 돕는 복지 제도예요.","answer":"O","reason_options":[{"t":"복지 제도는 사람들이 건강하고 행복하게 살 수 있도록 사회에서 지원하는 제도이기 때문에","correct":true},{"t":"복지 제도는 어린이만을 위한 제도이기 때문에","mis":"SO3-2-u1-X10"}],"mis":"SO3-2-u1-X10","explanation":["복지 제도의 뜻을 떠올려요.","사회가 생활을 지원해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_basic#10','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',3,'error','auto','고령화를 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X33','SO3-2-u1-X10']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C3","difficulty":3,"kind":"error","stem":"고령화를 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 가 — 「고령화로 생긴 문제는 오래 사는 노인들 탓이야.」","correct":true,"mis_target":"SO3-2-u1-X33"},{"t":"친구 나 — 「노인들에게 알맞은 일자리를 제공해.」","mis":"SO3-2-u1-X10"},{"t":"친구 다 — 「노인 전문 병원이나 요양 시설을 운영해.」","mis":"SO3-2-u1-X10"}],"explanation":["고령화는 사회 전체의 변화예요.","노인에게 책임을 돌리지 않아요.","친구 가가 바르지 않게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_challenge#1','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',2,'sa','auto','자료에서 1980년에 100명 가운데 노인이 아닌 사람은 몇 명 정도였나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C3","difficulty":2,"kind":"sa","stem":"자료에서 1980년에 100명 가운데 노인이 아닌 사람은 몇 명 정도였나요? 숫자로 쓰세요.","answer":["96"],"explanation":["1980년에는 100명 가운데 4명 정도가 노인이에요.","100에서 4를 빼요.","96명 정도예요."],"asset":{"type":"passage","lines":["1980년 — 100명 가운데 4명 정도가 노인이었어요.","2020년 — 100명 가운데 16명 정도가 노인이었어요.","2050년(예상) — 100명 가운데 40명 정도가 노인일 거예요.","(노인 — 65세 이상인 사람)"],"numbered":false,"title":"우리나라가 100명이 사는 마을이라면 — 교과서 18쪽"},"mis":"SO3-2-u1-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_challenge#2','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',2,'ox','auto','자료는 세 해 모두 마을 사람 수를 100명으로 똑같이 놓고 노인의 수를 나타냈어요.',ARRAY['SO3-2-u1-X05']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C3","difficulty":2,"kind":"ox","stem":"자료는 세 해 모두 마을 사람 수를 100명으로 똑같이 놓고 노인의 수를 나타냈어요.","answer":"O","reason_options":[{"t":"전체를 100명으로 똑같이 놓아야 노인이 차지하는 정도를 쉽게 견줄 수 있기 때문에","correct":true},{"t":"실제로 우리나라 사람이 100명뿐이기 때문에","mis":"SO3-2-u1-X05"}],"mis":"SO3-2-u1-X05","explanation":["세 마을 모두 100명이에요.","기준이 같아요.","그래서 O예요."],"asset":{"type":"passage","lines":["1980년 — 100명 가운데 4명 정도가 노인이었어요.","2020년 — 100명 가운데 16명 정도가 노인이었어요.","2050년(예상) — 100명 가운데 40명 정도가 노인일 거예요.","(노인 — 65세 이상인 사람)"],"numbered":false,"title":"우리나라가 100명이 사는 마을이라면 — 교과서 18쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_challenge#3','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',3,'mc','auto','고령화가 나타나는 까닭 두 가지를 바르게 묶은 것은 무엇인가요?',ARRAY['SO3-2-u1-X08','SO3-2-u1-X09']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C3","difficulty":3,"kind":"mc","stem":"고령화가 나타나는 까닭 두 가지를 바르게 묶은 것은 무엇인가요?","options":[{"t":"태어나는 아이의 수가 줄어들고, 사람들이 오래 살게 되었어요","correct":true},{"t":"태어나는 아이의 수가 늘어나고, 사람들이 오래 살게 되었어요","mis":"SO3-2-u1-X08"},{"t":"태어나는 아이의 수가 줄어들고, 사람들의 수명이 짧아졌어요","mis":"SO3-2-u1-X09"},{"t":"노인들이 모두 다른 나라로 떠났어요","mis":"SO3-2-u1-X08"}],"explanation":["아이는 줄어요.","사람들은 오래 살아요.","노인이 차지하는 비율이 높아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_challenge#4','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',3,'mc','auto','신문 기사에서 초등학교가 노인 센터로 바뀐 까닭을 가장 잘 설명한 것은 무엇인가요?',ARRAY['SO3-2-u1-X06','SO3-2-u1-X08','SO3-2-u1-X10']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C3","difficulty":3,"kind":"mc","stem":"신문 기사에서 초등학교가 노인 센터로 바뀐 까닭을 가장 잘 설명한 것은 무엇인가요?","options":[{"t":"학생이 줄어 학교가 문을 닫았고, 이 지역에는 65세 이상인 노인이 많이 살기 때문이에요","correct":true},{"t":"학생이 너무 많아 학교를 옮겼기 때문이에요","mis":"SO3-2-u1-X06"},{"t":"노인이 줄어 노인 센터가 남았기 때문이에요","mis":"SO3-2-u1-X08"},{"t":"아이들이 노인 센터에서 공부하기 때문이에요","mis":"SO3-2-u1-X10"}],"explanation":["졸업생 3명을 끝으로 문을 닫았어요.","주민 3명 중 1명꼴로 노인이에요.","그래서 노인 센터가 되었어요."],"asset":{"type":"passage","lines":["아이들 소리로 가득했던 초등학교가 2015년 졸업생 3명을 끝으로 문을 닫았다.","이듬해 이곳은 노인 센터로 바뀌었다.","이 지역은 주민 3명 중 1명꼴로 65세 이상인 노인이다.","70대부터 100세 넘은 어르신까지 42명이 9시에 등교하고 4시에 하교한다.","오전에는 건강 체크와 물리 치료, 오후에는 치매 예방 활동을 한다."],"numbered":false,"title":"초등학교에서 노인 센터로 — 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_challenge#5','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',3,'mc','auto','신문 기사 속 학교 건물이 노인 센터로 바뀐 뒤 3-3 교실의 표지판은 무엇으로 바뀌었을 것 같나요?',ARRAY['SO3-2-u1-X10']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C3","difficulty":3,"kind":"mc","stem":"신문 기사 속 학교 건물이 노인 센터로 바뀐 뒤 3-3 교실의 표지판은 무엇으로 바뀌었을 것 같나요?","options":[{"t":"물리 치료실","correct":true},{"t":"음악실","mis":"SO3-2-u1-X10"},{"t":"급식실","mis":"SO3-2-u1-X10"},{"t":"도서실","mis":"SO3-2-u1-X10"}],"explanation":["노인 센터에서 하는 일을 찾아요.","오전에 물리 치료를 받아요.","물리 치료실이 알맞아요."],"asset":{"type":"passage","lines":["아이들 소리로 가득했던 초등학교가 2015년 졸업생 3명을 끝으로 문을 닫았다.","이듬해 이곳은 노인 센터로 바뀌었다.","이 지역은 주민 3명 중 1명꼴로 65세 이상인 노인이다.","70대부터 100세 넘은 어르신까지 42명이 9시에 등교하고 4시에 하교한다.","오전에는 건강 체크와 물리 치료, 오후에는 치매 예방 활동을 한다."],"numbered":false,"title":"초등학교에서 노인 센터로 — 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_challenge#6','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',3,'error','auto','노인을 위한 물건을 개발한다면 넣고 싶은 기능을 친구들이 말했어요. 노인에게 도움이 되는 물건과 거리가 먼 생각을 고르세요.',ARRAY['SO3-2-u1-X10']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C3","difficulty":3,"kind":"error","stem":"노인을 위한 물건을 개발한다면 넣고 싶은 기능을 친구들이 말했어요. 노인에게 도움이 되는 물건과 거리가 먼 생각을 고르세요.","options":[{"t":"친구 다 — 「노인은 새로운 것을 배울 수 없으니 버튼이 많고 어려운 기계를 만들자.」","correct":true,"mis_target":"SO3-2-u1-X10"},{"t":"친구 가 — 「위급할 때 도움을 요청할 수 있는 리모컨을 만들자.」","mis":"SO3-2-u1-X10"},{"t":"친구 나 — 「노인의 운동을 도와주는 로봇을 만들자.」","mis":"SO3-2-u1-X10"}],"explanation":["노인에게 도움이 되는 기능이에요.","노인도 배움 프로그램에 참여해요.","친구 다의 생각이 거리가 멀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_challenge#7','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',3,'ox','auto','고령화는 노인들이 잘못해서 생긴 문제이므로 노인들이 스스로 해결해야 해요.',ARRAY['SO3-2-u1-X33']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C3","difficulty":3,"kind":"ox","stem":"고령화는 노인들이 잘못해서 생긴 문제이므로 노인들이 스스로 해결해야 해요.","answer":"X","reason_options":[{"t":"고령화는 사회가 함께 대비해야 할 변화이고, 우리 사회가 복지 제도와 일자리 등으로 노력하고 있기 때문에","correct":true},{"t":"노인이 많아진 것은 노인들의 책임이기 때문에","mis":"SO3-2-u1-X33"}],"mis":"SO3-2-u1-X33","explanation":["고령화는 누구의 잘못이 아니에요.","사회가 함께 대비해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_challenge#8','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',4,'mc','auto','교과서 20쪽에서 다양한 나이의 사람들이 서로 소통하고 배려하는 태도도 중요하다고 한 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X33','SO3-2-u1-X19','SO3-2-u1-X08']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C3","difficulty":4,"kind":"mc","stem":"교과서 20쪽에서 다양한 나이의 사람들이 서로 소통하고 배려하는 태도도 중요하다고 한 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"노인이 많아지는 사회에서는 여러 나이의 사람들이 함께 어울려 살아가야 하기 때문이에요","correct":true},{"t":"노인과 어린이는 서로 만날 일이 없기 때문이에요","mis":"SO3-2-u1-X33"},{"t":"노인을 위한 노력은 나라만 하면 되기 때문이에요","mis":"SO3-2-u1-X19"},{"t":"고령화는 곧 사라질 변화이기 때문이에요","mis":"SO3-2-u1-X08"}],"explanation":["노인이 점점 많아져요.","여러 나이의 사람이 함께 살아요.","서로 소통하고 배려해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_challenge#9','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',4,'mc','auto','자료의 변화가 계속된다면 우리 사회에 더 필요해질 노력으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X10','SO3-2-u1-X33']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C3","difficulty":4,"kind":"mc","stem":"자료의 변화가 계속된다면 우리 사회에 더 필요해질 노력으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"노인이 되어 지낼 생활을 미리 준비하도록 돕고, 노인에게 알맞은 일자리를 늘려요","correct":true},{"t":"노인 복지관을 줄이고 어린이 놀이터만 늘려요","mis":"SO3-2-u1-X10"},{"t":"노인을 위한 물건 개발을 멈춰요","mis":"SO3-2-u1-X10"},{"t":"노인들에게 모든 책임을 맡겨요","mis":"SO3-2-u1-X33"}],"explanation":["2050년에는 노인이 40명 정도예요.","노인이 더 많아져요.","노인을 위한 노력이 더 필요해요."],"asset":{"type":"passage","lines":["1980년 — 100명 가운데 4명 정도가 노인이었어요.","2020년 — 100명 가운데 16명 정도가 노인이었어요.","2050년(예상) — 100명 가운데 40명 정도가 노인일 거예요.","(노인 — 65세 이상인 사람)"],"numbered":false,"title":"우리나라가 100명이 사는 마을이라면 — 교과서 18쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L03_challenge#10','soc',3,2,'u1','L03','tb_g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',4,'essay','teacher','신문 기사 속 노인 센터를 보고 고령화로 달라진 생활 모습을 쓰고, 이 지역 노인들을 위해 우리 사회가 할 수 있는 노력을 교과서 20쪽 내용과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C3","difficulty":4,"kind":"essay","stem":"신문 기사 속 노인 센터를 보고 고령화로 달라진 생활 모습을 쓰고, 이 지역 노인들을 위해 우리 사회가 할 수 있는 노력을 교과서 20쪽 내용과 이어 쓰세요.","answer_guide":{"answer":"예: 문을 닫은 초등학교가 노인 센터로 바뀌어 노인들이 건강 체크와 물리 치료, 치매 예방 활동을 해요. 우리 사회는 노인의 건강하고 안정적인 생활을 돕는 복지 제도를 운영하고, 노인에게 알맞은 일자리를 제공할 수 있어요.","scoring_points":["노인 센터의 모습을 고령화와 이었는가","교과서 20쪽의 노력을 하나 이상 썼는가","노인의 안정된 생활과 이어지는가"]},"explanation":["학교가 노인 센터가 되었어요.","교과서 20쪽 노력을 떠올려요.","노인의 안정된 생활과 이어 써요."],"asset":{"type":"passage","lines":["아이들 소리로 가득했던 초등학교가 2015년 졸업생 3명을 끝으로 문을 닫았다.","이듬해 이곳은 노인 센터로 바뀌었다.","이 지역은 주민 3명 중 1명꼴로 65세 이상인 노인이다.","70대부터 100세 넘은 어르신까지 42명이 9시에 등교하고 4시에 하교한다.","오전에는 건강 체크와 물리 치료, 오후에는 치매 예방 활동을 한다."],"numbered":false,"title":"초등학교에서 노인 센터로 — 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_basic#1','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',1,'mc','auto','전화, 컴퓨터와 같은 기기를 이용해 정보를 주고받는 기술을 가리키는 말은 무엇인가요?',ARRAY['SO3-2-u1-X11']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"mc","stem":"전화, 컴퓨터와 같은 기기를 이용해 정보를 주고받는 기술을 가리키는 말은 무엇인가요?","options":[{"t":"정보 통신 기술","correct":true},{"t":"인공지능","mis":"SO3-2-u1-X11"},{"t":"지능정보화","mis":"SO3-2-u1-X11"},{"t":"가상 현실","mis":"SO3-2-u1-X11"}],"explanation":["교과서 21쪽 낱말 풀이예요.","정보를 주고받아요.","정보 통신 기술이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_basic#2','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',1,'sa','auto','컴퓨터 등을 활용해 디지털 공간에서 실제처럼 체험할 수 있게 해 주는 기술을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"sa","stem":"컴퓨터 등을 활용해 디지털 공간에서 실제처럼 체험할 수 있게 해 주는 기술을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["가상 현실","가상현실"],"explanation":["교과서 21쪽 낱말 풀이예요.","기기를 쓰고 놀이해요.","가상 현실이에요."],"mis":"SO3-2-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_basic#3','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',1,'ox','auto','지능정보화의 영향으로 많은 양의 정보를 빠르고 정확하게 처리하는 것이 어려워졌어요.',ARRAY['SO3-2-u1-X11']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"ox","stem":"지능정보화의 영향으로 많은 양의 정보를 빠르고 정확하게 처리하는 것이 어려워졌어요.","answer":"X","reason_options":[{"t":"인공지능이 발달해 많은 양의 정보를 더 빠르고 정확하게 처리할 수 있게 되었기 때문에","correct":true},{"t":"인공지능은 정보를 처리할수록 느려지기 때문에","mis":"SO3-2-u1-X11"}],"mis":"SO3-2-u1-X11","explanation":["인공지능이 발달하고 있어요.","정보를 빠르고 정확하게 처리해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_basic#4','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',1,'mc','auto','교과서 21쪽 사진 가운데 정보 통신 기술의 발달로 달라진 생활 모습이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u1-X12']::text[],true,'{"seq":4,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"mc","stem":"교과서 21쪽 사진 가운데 정보 통신 기술의 발달로 달라진 생활 모습이 아닌 것은 무엇인가요?","options":[{"t":"칠판의 분필 글씨를 공책에 옮겨 써요","correct":true},{"t":"스마트폰을 이용해 자전거를 빌려 타요","mis":"SO3-2-u1-X12"},{"t":"멀리 떨어져 있는 사람과 얼굴을 보며 대화해요","mis":"SO3-2-u1-X12"},{"t":"인터넷으로 필요한 정보를 찾아봐요","mis":"SO3-2-u1-X12"}],"explanation":["21쪽 사진 네 장을 떠올려요.","분필 글씨는 1991년 일기에 나와요.","정보 통신 기술과 관계없어요."],"variant_rule":{"alt":[{"stem":"교과서 21쪽 사진 가운데 가상 현실(VR) 기기로 하는 일은 무엇인가요?","options":[{"t":"놀이를 해요","correct":true},{"t":"자전거를 빌려 타요","mis":"SO3-2-u1-X12"},{"t":"얼굴을 보며 멀리 있는 사람과 대화해요","mis":"SO3-2-u1-X12"},{"t":"교실 난로에 기름을 넣어요","mis":"SO3-2-u1-X03"}],"explanation":["21쪽 두 번째 사진이에요.","실제처럼 체험해요.","가상 현실 기기로 놀이해요."],"asset":{"type":"passage","lines":["① 인터넷으로 필요한 정보를 찾아봐요.","② 가상 현실(VR) 기기를 이용해 놀이해요.","③ 멀리 떨어져 있는 사람과 얼굴을 보며 대화해요.","④ 스마트폰을 이용해 자전거를 빌려 타요."],"numbered":false,"title":"정보 통신 기술의 발달로 달라진 생활 모습 — 교과서 21쪽"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_basic#5','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',2,'mc','auto','자료 가운데 인공지능이 사람의 목소리를 인식해 기능을 하는 모습은 무엇인가요?',ARRAY['SO3-2-u1-X12']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C4","difficulty":2,"kind":"mc","stem":"자료 가운데 인공지능이 사람의 목소리를 인식해 기능을 하는 모습은 무엇인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"SO3-2-u1-X12"},{"t":"㉢","mis":"SO3-2-u1-X12"},{"t":"㉥","mis":"SO3-2-u1-X12"}],"explanation":["목소리를 인식하는 기기예요.","「오늘 날씨를 알려 줘.」라고 말해요.","㉡이에요."],"asset":{"type":"passage","lines":["㉠ 인공지능이 학생의 수준과 흥미를 고려해 교육 활동을 해요.","㉡ 목소리를 인식해 기능을 하는 인공지능 기기를 써요.","㉢ 애플리케이션으로 주문하면 로봇이 음식을 배달해 줘요.","㉣ 사람과 대화하듯이 인공지능과 의사소통하여 원하는 정보를 얻어요.","㉤ 인공지능을 활용해 사용자의 건강에 알맞은 운동을 해요.","㉥ 농작물의 상태를 관찰하고 관리하는 인공지능 기술로 농사를 지어요.","㉦ 인공지능이 주변 상황을 실시간으로 파악해 안전한 운전을 도와요."],"numbered":false,"title":"지능정보화로 나타난 생활 모습 — 교과서 22~23쪽 그림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_basic#6','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',2,'match','auto','지능정보화로 나타난 문제와 그 뜻을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u1-C4","difficulty":2,"kind":"match","stem":"지능정보화로 나타난 문제와 그 뜻을 이으세요.","pairs":[{"l":"사이버 범죄","r":"인터넷에서 다른 사람의 이름이나 전화번호 등을 함부로 쓰는 일"},{"l":"인터넷·스마트폰 과의존","r":"인터넷이나 스마트폰을 지나치게 이용해 문제가 되는 상태"},{"l":"일자리 감소","r":"사람이 하던 일을 인공지능이 대신 하면서 일자리가 줄어드는 것"}],"mis":"SO3-2-u1-X12","explanation":["함부로 쓰는 범죄예요.","지나치게 쓰는 상태예요.","인공지능이 일을 대신 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_basic#7','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',2,'blank','auto','다른 사람과 구별해 개인을 알 수 있는 모든 정보를 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X14','SO3-2-u1-X11']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C4","difficulty":2,"kind":"blank","stem":"다른 사람과 구별해 개인을 알 수 있는 모든 정보를 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"개인 정보","correct":true},{"t":"가짜 뉴스","mis":"SO3-2-u1-X14"},{"t":"상품 후기","mis":"SO3-2-u1-X14"},{"t":"인공지능","mis":"SO3-2-u1-X11"}],"explanation":["교과서 24쪽 낱말 풀이예요.","이름, 집 주소, 전화번호 같은 것이에요.","개인 정보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_basic#8','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',2,'mc','auto','신문 기사 「나」에서 지능정보화로 나타난 문제는 무엇인가요?',ARRAY['SO3-2-u1-X12']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C4","difficulty":2,"kind":"mc","stem":"신문 기사 「나」에서 지능정보화로 나타난 문제는 무엇인가요?","options":[{"t":"인공지능이 만들어 낸 거짓 정보가 인터넷에서 넘쳐 나요","correct":true},{"t":"인터넷에서 개인 정보가 노출되고 있어요","mis":"SO3-2-u1-X12"},{"t":"로봇이 음식을 배달해 줘요","mis":"SO3-2-u1-X12"},{"t":"인공지능이 학생 수준에 맞게 교육해요","mis":"SO3-2-u1-X12"}],"explanation":["기사 「나」를 읽어요.","가짜 뉴스와 가짜 상품 후기예요.","거짓 정보 확산이에요."],"asset":{"type":"passage","lines":["가 — 인터넷에서 이미지나 동영상 파일에 담긴 개인 정보가 노출되고 있다.","　노출된 정보: 이름, 성별, 나이, 주민 등록 번호, 집 주소, 전화번호 등","나 — 인공지능이 만들어 낸 거짓 정보가 인터넷에서 넘쳐 나고 있다.","　그럴듯한 가짜 뉴스를 만들거나 가짜 상품 후기를 가득 쓰기도 한다."],"numbered":false,"title":"지능정보화로 나타난 문제를 다룬 신문 기사 — 교과서 24쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_basic#9','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',2,'ox','auto','사람처럼 정보를 익히고 처리하여 다양한 상황에 적용할 수 있는 기능을 갖춘 컴퓨터 시스템을 인공지능이라고 해요.',ARRAY['SO3-2-u1-X11']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C4","difficulty":2,"kind":"ox","stem":"사람처럼 정보를 익히고 처리하여 다양한 상황에 적용할 수 있는 기능을 갖춘 컴퓨터 시스템을 인공지능이라고 해요.","answer":"O","reason_options":[{"t":"교과서 22쪽 낱말 풀이와 같기 때문에","correct":true},{"t":"전화나 컴퓨터로 정보를 주고받는 기술을 인공지능이라고 하기 때문에","mis":"SO3-2-u1-X11"}],"mis":"SO3-2-u1-X11","explanation":["인공지능의 뜻을 떠올려요.","사람처럼 정보를 익혀요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_basic#10','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',3,'error','auto','지능정보화를 대하는 태도를 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X13','SO3-2-u1-X14']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C4","difficulty":3,"kind":"error","stem":"지능정보화를 대하는 태도를 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 나 — 「편리하니까 문제는 생각하지 말고 마음껏 쓰면 돼.」","correct":true,"mis_target":"SO3-2-u1-X13"},{"t":"친구 가 — 「장점은 누리고 단점은 보완해야 해.」","mis":"SO3-2-u1-X13"},{"t":"친구 다 — 「인터넷에 있는 정보를 무조건 믿지 않을 거야.」","mis":"SO3-2-u1-X14"}],"explanation":["편리해진 점이 있어요.","문제도 생겼어요.","친구 나가 바르지 않게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_challenge#1','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',2,'sa','auto','인터넷이나 스마트폰을 지나치게 이용하여 문제가 되는 상태를 「인터넷·스마트폰 (    )」이라고 해요. 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C4","difficulty":2,"kind":"sa","stem":"인터넷이나 스마트폰을 지나치게 이용하여 문제가 되는 상태를 「인터넷·스마트폰 (    )」이라고 해요. 빈칸에 알맞은 말을 쓰세요.","answer":["과의존"],"explanation":["교과서 24쪽 낱말 풀이예요.","지나치게 기대요.","과의존이에요."],"mis":"SO3-2-u1-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_challenge#2','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',2,'ox','auto','사람이 하던 일을 인공지능이 대신 하면서 일자리가 줄어드는 것도 지능정보화로 나타난 문제예요.',ARRAY['SO3-2-u1-X12']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C4","difficulty":2,"kind":"ox","stem":"사람이 하던 일을 인공지능이 대신 하면서 일자리가 줄어드는 것도 지능정보화로 나타난 문제예요.","answer":"O","reason_options":[{"t":"인공지능이 발달해 사람이 하던 다양한 일을 대신 하기 때문에","correct":true},{"t":"인공지능은 사람의 일을 대신 할 수 없기 때문에","mis":"SO3-2-u1-X12"}],"mis":"SO3-2-u1-X12","explanation":["인공지능이 일을 대신 해요.","일자리가 줄 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_challenge#3','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',3,'mc','auto','신문 기사 「가」의 문제로 생길 수 있는 피해를 예상한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X12','SO3-2-u1-X13']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C4","difficulty":3,"kind":"mc","stem":"신문 기사 「가」의 문제로 생길 수 있는 피해를 예상한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"다른 사람이 나의 전화번호나 집 주소를 함부로 써서 범죄에 이용할 수 있어요","correct":true},{"t":"가짜 상품 후기에 속아 물건을 살 수 있어요","mis":"SO3-2-u1-X12"},{"t":"스마트폰을 지나치게 써서 잠이 부족해져요","mis":"SO3-2-u1-X12"},{"t":"피해가 생길 일은 없어요","mis":"SO3-2-u1-X13"}],"explanation":["기사 「가」는 개인 정보 노출이에요.","내 정보가 퍼질 수 있어요.","범죄에 쓰일 수 있어요."],"asset":{"type":"passage","lines":["가 — 인터넷에서 이미지나 동영상 파일에 담긴 개인 정보가 노출되고 있다.","　노출된 정보: 이름, 성별, 나이, 주민 등록 번호, 집 주소, 전화번호 등","나 — 인공지능이 만들어 낸 거짓 정보가 인터넷에서 넘쳐 나고 있다.","　그럴듯한 가짜 뉴스를 만들거나 가짜 상품 후기를 가득 쓰기도 한다."],"numbered":false,"title":"지능정보화로 나타난 문제를 다룬 신문 기사 — 교과서 24쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_challenge#4','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',3,'mc','auto','교과서 25쪽 ④처럼 인공지능 발달로 달라질 직업 환경에 대응하기 위한 교육을 하는 까닭은 무엇인가요?',ARRAY['SO3-2-u1-X12','SO3-2-u1-X14']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C4","difficulty":3,"kind":"mc","stem":"교과서 25쪽 ④처럼 인공지능 발달로 달라질 직업 환경에 대응하기 위한 교육을 하는 까닭은 무엇인가요?","options":[{"t":"사람이 하던 일을 인공지능이 대신 하면서 일자리가 줄어드는 문제에 대비하려고","correct":true},{"t":"사이버 범죄를 신고하려고","mis":"SO3-2-u1-X12"},{"t":"개인 정보를 인터넷에 널리 알리려고","mis":"SO3-2-u1-X14"},{"t":"인터넷을 더 오래 쓰려고","mis":"SO3-2-u1-X14"}],"explanation":["직업 환경이 달라져요.","일자리 감소 문제가 있어요.","미리 대비하는 교육이에요."],"asset":{"type":"passage","lines":["① 사이버 범죄를 감시하고 피해를 줄이려고 노력해요.","② 인터넷을 올바르게 사용하는 습관을 갖도록 지원해요.","③ 인공지능을 효과적으로 활용할 수 있는 능력을 길러요.","④ 인공지능 발달로 달라질 직업 환경에 대응하기 위한 교육을 해요."],"numbered":false,"title":"지능정보화로 나타난 문제를 해결하려는 노력 — 교과서 25쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_challenge#5','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',3,'mc','auto','「이름, 집 주소, 전화번호 같은 내 개인 정보를 인터넷에 함부로 올리지 않아요.」라는 약속이 막는 데 도움이 되는 문제는 무엇인가요?',ARRAY['SO3-2-u1-X12','SO3-2-u1-X14']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C4","difficulty":3,"kind":"mc","stem":"「이름, 집 주소, 전화번호 같은 내 개인 정보를 인터넷에 함부로 올리지 않아요.」라는 약속이 막는 데 도움이 되는 문제는 무엇인가요?","options":[{"t":"인터넷에서 개인 정보가 노출되는 문제","correct":true},{"t":"농작물을 관리하기 어려운 문제","mis":"SO3-2-u1-X12"},{"t":"거짓 정보로 사회가 혼란스러워지는 문제","mis":"SO3-2-u1-X14"},{"t":"일자리가 줄어드는 문제","mis":"SO3-2-u1-X12"}],"explanation":["약속은 개인 정보에 관한 것이에요.","함부로 올리지 않아요.","개인 정보 노출을 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_challenge#6','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',3,'error','auto','인공지능 전문가를 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X11']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C4","difficulty":3,"kind":"error","stem":"인공지능 전문가를 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 다 — 「인공지능 전문가가 되려면 수학과 과학은 공부하지 않아도 돼.」","correct":true,"mis_target":"SO3-2-u1-X11"},{"t":"친구 가 — 「로봇이 사람처럼 생각하고 일하는 기술을 개발해.」","mis":"SO3-2-u1-X11"},{"t":"친구 나 — 「일상생활에서 창의적으로 생각하는 습관을 기르는 것도 중요해.」","mis":"SO3-2-u1-X11"}],"explanation":["필요한 것을 찾아요.","수학과 과학 공부가 도움이 돼요.","친구 다가 바르지 않게 말했어요."],"asset":{"type":"passage","lines":["하는 일: 컴퓨터 시스템이나 로봇이 사람처럼 생각하고 일하는 기술을 개발해요.","기술 예: 지식을 배운 뒤 새로운 정보를 처리하는 기술","기술 예: 단순한 반복을 넘어 새로운 상황에 적용하는 기술","필요한 것: 논리적인 생각, 수학과 과학 공부, 창의적으로 생각하는 습관"],"title":"별별 직업 속으로 — 인공지능 전문가(교과서 26쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_challenge#7','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',3,'ox','auto','인공지능이 농작물의 상태를 관찰하고 관리하면 편리하게 농사를 지을 수 있어요.',ARRAY['SO3-2-u1-X12']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C4","difficulty":3,"kind":"ox","stem":"인공지능이 농작물의 상태를 관찰하고 관리하면 편리하게 농사를 지을 수 있어요.","answer":"O","reason_options":[{"t":"인공지능 기술이 농작물을 관찰하고 관리해 사람의 일을 도와주기 때문에","correct":true},{"t":"인공지능은 농사처럼 자연과 관계된 일에는 쓸 수 없기 때문에","mis":"SO3-2-u1-X12"}],"mis":"SO3-2-u1-X12","explanation":["교과서 23쪽 그림이에요.","농작물을 관찰하고 관리해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_challenge#8','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',4,'mc','auto','65세 이상 인구 비율이 계속 높아질 것으로 예상되는 자료와 인공지능 기술 사진을 함께 볼 때, 고령화로 생길 수 있는 문제를 지능정보화로 해결하는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X13','SO3-2-u1-X14']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C4","difficulty":4,"kind":"mc","stem":"65세 이상 인구 비율이 계속 높아질 것으로 예상되는 자료와 인공지능 기술 사진을 함께 볼 때, 고령화로 생길 수 있는 문제를 지능정보화로 해결하는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"노인들이 쓰기 쉬운 휴대용 건강 측정 기기를 만들어 건강을 관리하도록 도와요","correct":true},{"t":"노인이 인터넷을 쓰지 못하게 막아요","mis":"SO3-2-u1-X13"},{"t":"고령화 문제는 기술과 아무 관계가 없다고 생각해요","mis":"SO3-2-u1-X13"},{"t":"노인의 개인 정보를 인터넷에 널리 알려요","mis":"SO3-2-u1-X14"}],"explanation":["노인의 건강 관리 비용이 늘어요.","인공지능 기술이 건강을 살필 수 있어요.","두 변화를 이어 해결해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_challenge#9','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',4,'mc','auto','「인터넷을 사용할 수 없거나 휴대 전화가 없으면 어떤 일이 생길까요?」라는 물음에 알맞은 생각은 무엇인가요?',ARRAY['SO3-2-u1-X11']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C4","difficulty":4,"kind":"mc","stem":"「인터넷을 사용할 수 없거나 휴대 전화가 없으면 어떤 일이 생길까요?」라는 물음에 알맞은 생각은 무엇인가요?","options":[{"t":"도서관에서 책을 일일이 찾아보거나 은행 거래를 하러 직접 은행에 가야 할 것 같아요","correct":true},{"t":"먼 곳의 소식을 지금보다 더 빨리 알 것 같아요","mis":"SO3-2-u1-X11"},{"t":"생활이 지금과 하나도 다르지 않을 것 같아요","mis":"SO3-2-u1-X11"},{"t":"정보를 얻기가 지금보다 쉬워질 것 같아요","mis":"SO3-2-u1-X11"}],"explanation":["인터넷으로 정보를 찾아요.","없다면 시간과 품이 더 들어요.","직접 찾아가야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L04_challenge#10','soc',3,2,'u1','L04','tb_g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',4,'essay','teacher','교과서 22~23쪽 그림 속 지능정보화 모습 가운데 하나와 관련 있는 내 경험을 쓰고, 앞으로 우리 생활에서 인공지능을 활용하면 좋을 것 같은 상황을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C4","difficulty":4,"kind":"essay","stem":"교과서 22~23쪽 그림 속 지능정보화 모습 가운데 하나와 관련 있는 내 경험을 쓰고, 앞으로 우리 생활에서 인공지능을 활용하면 좋을 것 같은 상황을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 음식점에서 음식을 나르는 로봇을 본 적이 있어요. 앞으로 주변의 위험 상황을 미리 파악해 알려 주는 인공지능 장치를 쓰면 좋겠어요. 여러 사고로부터 입는 피해를 예방할 수 있기 때문이에요.","scoring_points":["그림 속 모습과 관련 있는 경험을 썼는가","인공지능을 활용할 상황을 썼는가","그렇게 생각한 까닭을 썼는가"]},"explanation":["그림 속 모습을 떠올려요.","내 경험과 이어요.","활용할 상황과 까닭을 써요."],"asset":{"type":"passage","lines":["㉠ 인공지능이 학생의 수준과 흥미를 고려해 교육 활동을 해요.","㉡ 목소리를 인식해 기능을 하는 인공지능 기기를 써요.","㉢ 애플리케이션으로 주문하면 로봇이 음식을 배달해 줘요.","㉣ 사람과 대화하듯이 인공지능과 의사소통하여 원하는 정보를 얻어요.","㉤ 인공지능을 활용해 사용자의 건강에 알맞은 운동을 해요.","㉥ 농작물의 상태를 관찰하고 관리하는 인공지능 기술로 농사를 지어요.","㉦ 인공지능이 주변 상황을 실시간으로 파악해 안전한 운전을 도와요."],"numbered":false,"title":"지능정보화로 나타난 생활 모습 — 교과서 22~23쪽 그림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_basic#1','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',1,'mc','auto','세계 여러 나라가 다양한 분야에서 교류하면서 전 세계가 하나로 연결되는 현상을 가리키는 말은 무엇인가요?',ARRAY['SO3-2-u1-X18','SO3-2-u1-X16','SO3-2-u1-X15']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C5","difficulty":1,"kind":"mc","stem":"세계 여러 나라가 다양한 분야에서 교류하면서 전 세계가 하나로 연결되는 현상을 가리키는 말은 무엇인가요?","options":[{"t":"세계화","correct":true},{"t":"지능정보화","mis":"SO3-2-u1-X18"},{"t":"한류","mis":"SO3-2-u1-X16"},{"t":"교류","mis":"SO3-2-u1-X15"}],"explanation":["세계 여러 나라가 교류해요.","하나로 연결돼요.","세계화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_basic#2','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',1,'sa','auto','사람들이 환경에 적응하면서 살아가는 생활 방식이나 사고방식을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C5","difficulty":1,"kind":"sa","stem":"사람들이 환경에 적응하면서 살아가는 생활 방식이나 사고방식을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["생활 양식","생활양식"],"explanation":["교과서 28쪽 낱말 풀이예요.","살아가는 방식이에요.","생활 양식이에요."],"mis":"SO3-2-u1-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_basic#3','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',1,'ox','auto','세계화에 대응하려면 우리의 전통적인 생활 양식만 소중히 여기면 돼요.',ARRAY['SO3-2-u1-X17']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C5","difficulty":1,"kind":"ox","stem":"세계화에 대응하려면 우리의 전통적인 생활 양식만 소중히 여기면 돼요.","answer":"X","reason_options":[{"t":"다른 나라의 생활 양식을 장단점을 따져 받아들이고 세계의 문제에도 관심을 가져야 하기 때문에","correct":true},{"t":"다른 나라의 생활 양식은 모두 받아들이지 않아야 하기 때문에","mis":"SO3-2-u1-X17"}],"mis":"SO3-2-u1-X17","explanation":["우리 것도 소중해요.","다른 나라 것은 따져 받아들여요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_basic#4','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',1,'mc','auto','교과서 27쪽 사진 ③에서 세계 여러 나라 사람이 다 같이 불을 끄는 「지구를 위한 시간」 행사의 뜻은 무엇인가요?',ARRAY['SO3-2-u1-X15']::text[],true,'{"seq":4,"concept":"SO3-2-u1-C5","difficulty":1,"kind":"mc","stem":"교과서 27쪽 사진 ③에서 세계 여러 나라 사람이 다 같이 불을 끄는 「지구를 위한 시간」 행사의 뜻은 무엇인가요?","options":[{"t":"지구의 환경을 보호하자는 뜻이에요","correct":true},{"t":"전기 요금을 아끼자는 뜻이에요","mis":"SO3-2-u1-X15"},{"t":"한 나라 사람끼리만 모이자는 뜻이에요","mis":"SO3-2-u1-X15"},{"t":"밤에 일찍 자자는 뜻이에요","mis":"SO3-2-u1-X15"}],"explanation":["세계 여러 나라 사람이 함께해요.","환경의 소중함을 생각해요.","지구 환경을 보호하자는 뜻이에요."],"variant_rule":{"alt":[{"stem":"교과서 27쪽 사진 ①에서 볼 수 있는 세계화 모습은 무엇인가요?","options":[{"t":"다른 나라에서 온 식품이나 물건을 구입해요","correct":true},{"t":"우리 마을에서 기른 채소만 먹어요","mis":"SO3-2-u1-X15"},{"t":"다른 나라 소식은 전혀 알 수 없어요","mis":"SO3-2-u1-X15"},{"t":"물건은 우리나라 안에서만 주고받아요","mis":"SO3-2-u1-X15"}],"explanation":["27쪽 첫 번째 사진이에요.","다른 나라에서 온 과일이에요.","구입할 수 있어요."],"asset":{"type":"passage","lines":["① 다른 나라에서 온 식품이나 물건을 구입해요.","② 다른 나라에서 만든 영화를 봐요.","③ 세계 여러 나라 사람과 함께하는 행사에 참여해요.","④ 학교에서 영어와 세계 여러 나라에 관한 내용을 배워요."],"numbered":false,"title":"우리 주변의 세계화 모습 — 교과서 27쪽 사진"}},{"stem":"교과서 27쪽 사진 ④에서 볼 수 있는 세계화 모습은 무엇인가요?","options":[{"t":"학교에서 영어와 세계 여러 나라에 관한 내용을 배워요","correct":true},{"t":"학교에서는 우리나라에 관한 것만 배워요","mis":"SO3-2-u1-X15"},{"t":"다른 나라에서 만든 영화를 볼 수 없어요","mis":"SO3-2-u1-X15"},{"t":"세계 여러 나라 사람과 함께하는 행사가 없어요","mis":"SO3-2-u1-X15"}],"explanation":["27쪽 네 번째 사진이에요.","학교에서 영어를 배워요.","세계 여러 나라를 배워요."],"asset":{"type":"passage","lines":["① 다른 나라에서 온 식품이나 물건을 구입해요.","② 다른 나라에서 만든 영화를 봐요.","③ 세계 여러 나라 사람과 함께하는 행사에 참여해요.","④ 학교에서 영어와 세계 여러 나라에 관한 내용을 배워요."],"numbered":false,"title":"우리 주변의 세계화 모습 — 교과서 27쪽 사진"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_basic#5','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',2,'mc','auto','신문 기사를 읽고 세종 학당이 다른 나라 사람들에게 미친 영향을 찾은 것으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X16']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"mc","stem":"신문 기사를 읽고 세종 학당이 다른 나라 사람들에게 미친 영향을 찾은 것으로 알맞은 것은 무엇인가요?","options":[{"t":"한국어를 가르쳐 주고, 우리의 말과 글, 음식, 한복 같은 생활 양식을 알려요","correct":true},{"t":"다른 나라의 과일을 우리나라에 들여와요","mis":"SO3-2-u1-X16"},{"t":"우리나라 사람에게 다른 나라 말만 가르쳐요","mis":"SO3-2-u1-X16"},{"t":"다른 나라에서 만든 영화를 상영해요","mis":"SO3-2-u1-X16"}],"explanation":["세종 학당은 한국어를 가르쳐요.","우리 생활 양식도 알려요.","우리나라가 세계에 영향을 줘요."],"asset":{"type":"passage","lines":["우리나라 회사의 세계 진출과 대중가요, 드라마, 영화 등을 앞세운","한류 열풍으로 우리나라에 관한 세계인의 관심이 높아졌다.","세종 학당은 우리의 말과 글, 음식, 한복 같은 생활 양식을 세계에 알린다.","다른 나라에서 한국어를 배우려는 사람에게 한국어를 중심으로 가르친다.","2022년 기준으로 세종 학당은 84개 나라에 244곳이 있다.","한국 요리, 역사, 관광 등 다양한 이유로 한국어를 배우는 사람이 늘었다."],"numbered":false,"title":"한류에 푹 빠진 세계인들 — 교과서 28쪽 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_basic#6','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',2,'match','auto','세계화로 나타나는 일과 그에 맞서 갖춰야 할 태도를 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"match","stem":"세계화로 나타나는 일과 그에 맞서 갖춰야 할 태도를 이으세요.","pairs":[{"l":"다른 나라의 생활 양식이 들어와요","r":"무조건 따르지 않고 장단점을 따져 받아들여요"},{"l":"전통적인 생활 양식이 약해질 수 있어요","r":"우리나라의 생활 양식을 소중히 여겨요"},{"l":"감염병이 전 세계로 빠르게 퍼질 수 있어요","r":"세계 여러 나라의 문제에 관심을 갖고 함께 해결하려고 노력해요"}],"mis":"SO3-2-u1-X17","explanation":["따져 받아들여요.","우리 것을 소중히 여겨요.","세계의 문제를 함께 해결해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_basic#7','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',2,'blank','auto','대한민국과 관련 있는 것들이 다른 나라에서 인기를 얻는 현상을 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X15','SO3-2-u1-X16']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"blank","stem":"대한민국과 관련 있는 것들이 다른 나라에서 인기를 얻는 현상을 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"한류","correct":true},{"t":"세계화","mis":"SO3-2-u1-X15"},{"t":"대중가요","mis":"SO3-2-u1-X16"},{"t":"교류","mis":"SO3-2-u1-X15"}],"explanation":["교과서 28쪽 낱말 풀이예요.","우리 것이 인기를 얻어요.","한류예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_basic#8','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',2,'mc','auto','교과서 30쪽에서 우리나라 회사가 미국, 중국 등에 공장을 지어 알리고 있는 음식은 무엇인가요?',ARRAY['SO3-2-u1-X16']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"mc","stem":"교과서 30쪽에서 우리나라 회사가 미국, 중국 등에 공장을 지어 알리고 있는 음식은 무엇인가요?","options":[{"t":"라면","correct":true},{"t":"초코과자","mis":"SO3-2-u1-X16"},{"t":"호떡","mis":"SO3-2-u1-X16"},{"t":"떡볶이","mis":"SO3-2-u1-X16"}],"explanation":["한국 영화나 드라마에 나왔어요.","세계인이 즐겨 먹어요.","한국 라면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_basic#9','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',2,'ox','auto','세계화로 우리나라는 다른 나라의 영향을 받기만 하고 다른 나라에 영향을 주지는 않아요.',ARRAY['SO3-2-u1-X16']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"ox","stem":"세계화로 우리나라는 다른 나라의 영향을 받기만 하고 다른 나라에 영향을 주지는 않아요.","answer":"X","reason_options":[{"t":"우리나라에서 만든 물건이 세계에서 팔리고, 생활 양식이 세계에 알려지기도 하기 때문에","correct":true},{"t":"세계화는 다른 나라 것이 들어오는 것만 말하기 때문에","mis":"SO3-2-u1-X16"}],"mis":"SO3-2-u1-X16","explanation":["우리 물건이 세계에서 팔려요.","우리 생활 양식도 알려져요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_basic#10','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',3,'error','auto','세계화로 달라진 생활을 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X17','SO3-2-u1-X15']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C5","difficulty":3,"kind":"error","stem":"세계화로 달라진 생활을 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 다 — 「세계화로 생활이 편리해졌으니 생긴 문제는 하나도 없어.」","correct":true,"mis_target":"SO3-2-u1-X17"},{"t":"친구 가 — 「다른 나라에서 만든 영화를 볼 수 있어.」","mis":"SO3-2-u1-X15"},{"t":"친구 나 — 「여러 나라를 오가는 사람이 많아져 감염병이 빨리 퍼질 수 있어.」","mis":"SO3-2-u1-X17"}],"explanation":["풍족하고 편리해졌어요.","문제도 생겼어요.","친구 다가 바르지 않게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_challenge#1','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',2,'sa','auto','신문 기사에서 2022년 기준으로 세종 학당은 몇 개 나라에 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"sa","stem":"신문 기사에서 2022년 기준으로 세종 학당은 몇 개 나라에 있나요? 숫자로 쓰세요.","answer":["84"],"explanation":["기사의 수를 찾아요.","나라 수와 곳 수가 있어요.","84개 나라예요."],"asset":{"type":"passage","lines":["우리나라 회사의 세계 진출과 대중가요, 드라마, 영화 등을 앞세운","한류 열풍으로 우리나라에 관한 세계인의 관심이 높아졌다.","세종 학당은 우리의 말과 글, 음식, 한복 같은 생활 양식을 세계에 알린다.","다른 나라에서 한국어를 배우려는 사람에게 한국어를 중심으로 가르친다.","2022년 기준으로 세종 학당은 84개 나라에 244곳이 있다.","한국 요리, 역사, 관광 등 다양한 이유로 한국어를 배우는 사람이 늘었다."],"numbered":false,"title":"한류에 푹 빠진 세계인들 — 교과서 28쪽 신문 기사"},"mis":"SO3-2-u1-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_challenge#2','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',2,'ox','auto','초코과자가 러시아, 중국, 베트남 등에서 큰 인기를 끌어 우리나라 회사가 그곳에 공장을 세웠어요.',ARRAY['SO3-2-u1-X16']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"ox","stem":"초코과자가 러시아, 중국, 베트남 등에서 큰 인기를 끌어 우리나라 회사가 그곳에 공장을 세웠어요.","answer":"O","reason_options":[{"t":"교과서 30쪽에서 그곳에 초코과자 공장을 세울 만큼 인기가 많다고 했기 때문에","correct":true},{"t":"우리나라 과자는 다른 나라에서 팔리지 않기 때문에","mis":"SO3-2-u1-X16"}],"mis":"SO3-2-u1-X16","explanation":["교과서 30쪽을 떠올려요.","공장을 세웠어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_challenge#3','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',3,'mc','auto','자료의 상품들을 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X15']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C5","difficulty":3,"kind":"mc","stem":"자료의 상품들을 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"세계 곳곳에서 들여온 상품을 우리나라에서 쉽게 구할 수 있어요","correct":true},{"t":"우리나라에서는 다른 나라 상품을 살 수 없어요","mis":"SO3-2-u1-X15"},{"t":"상품은 한 나라에서만 들여와요","mis":"SO3-2-u1-X15"},{"t":"들여온 상품은 우리 생활과 관계없어요","mis":"SO3-2-u1-X15"}],"explanation":["벨기에, 프랑스, 칠레, 미국, 독일이에요.","여러 나라에서 들여왔어요.","세계화의 모습이에요."],"asset":{"type":"passage","lines":["벨기에에서 만든 초콜릿 · 프랑스에서 만든 화장품","칠레에서 재배한 포도 · 미국에서 만든 청바지","독일에서 만든 프라이팬"],"title":"세계 곳곳에서 들여온 상품 — 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_challenge#4','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',3,'mc','auto','교과서 28쪽 기사에서 한류 열풍을 이끈 것으로 나오지 않은 것은 무엇인가요?',ARRAY['SO3-2-u1-X16']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C5","difficulty":3,"kind":"mc","stem":"교과서 28쪽 기사에서 한류 열풍을 이끈 것으로 나오지 않은 것은 무엇인가요?","options":[{"t":"지구를 위한 시간 행사","correct":true},{"t":"대중가요","mis":"SO3-2-u1-X16"},{"t":"드라마","mis":"SO3-2-u1-X16"},{"t":"영화","mis":"SO3-2-u1-X16"}],"explanation":["기사 첫 줄을 다시 읽어요.","대중가요, 드라마, 영화가 나와요.","불 끄기 행사는 나오지 않아요."],"asset":{"type":"passage","lines":["우리나라 회사의 세계 진출과 대중가요, 드라마, 영화 등을 앞세운","한류 열풍으로 우리나라에 관한 세계인의 관심이 높아졌다.","세종 학당은 우리의 말과 글, 음식, 한복 같은 생활 양식을 세계에 알린다.","다른 나라에서 한국어를 배우려는 사람에게 한국어를 중심으로 가르친다.","2022년 기준으로 세종 학당은 84개 나라에 244곳이 있다.","한국 요리, 역사, 관광 등 다양한 이유로 한국어를 배우는 사람이 늘었다."],"numbered":false,"title":"한류에 푹 빠진 세계인들 — 교과서 28쪽 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_challenge#5','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',3,'mc','auto','세 번째 광고 문구에 담긴 태도로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X17']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C5","difficulty":3,"kind":"mc","stem":"세 번째 광고 문구에 담긴 태도로 가장 알맞은 것은 무엇인가요?","options":[{"t":"세계 여러 나라의 문제에 관심을 갖고 함께 해결하려는 태도","correct":true},{"t":"다른 나라의 생활 양식을 무조건 따르는 태도","mis":"SO3-2-u1-X17"},{"t":"우리 생활 양식만 고집하는 태도","mis":"SO3-2-u1-X17"},{"t":"세계의 문제는 모른 체하는 태도","mis":"SO3-2-u1-X17"}],"explanation":["작은 관심이에요.","세계인의 더 큰 행복이에요.","함께 해결하려는 태도예요."],"asset":{"type":"passage","lines":["첫 번째 — 소중히 여기는 우리 전통, 더 나은 세계화","두 번째 — 세계인의 관심으로 만드는 모두가 행복한 세상","세 번째 — 우리의 작은 관심이 만드는 세계인의 더 큰 행복"],"title":"세계화에 대응하는 태도를 담은 광고 문구 — 교과서 29쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_challenge#6','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',3,'error','auto','세종 학당 기사를 읽고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X16']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C5","difficulty":3,"kind":"error","stem":"세종 학당 기사를 읽고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 나 — 「세종 학당은 우리나라 사람에게 다른 나라 말을 가르치는 곳이야.」","correct":true,"mis_target":"SO3-2-u1-X16"},{"t":"친구 가 — 「한국 요리나 역사, 관광 때문에 한국어를 배우는 사람도 늘었대.」","mis":"SO3-2-u1-X16"},{"t":"친구 다 — 「세종 학당은 우리 생활 양식을 세계 곳곳에 알려.」","mis":"SO3-2-u1-X16"}],"explanation":["누가 무엇을 배우나요?","다른 나라 사람이 한국어를 배워요.","친구 나가 바르지 않게 말했어요."],"asset":{"type":"passage","lines":["우리나라 회사의 세계 진출과 대중가요, 드라마, 영화 등을 앞세운","한류 열풍으로 우리나라에 관한 세계인의 관심이 높아졌다.","세종 학당은 우리의 말과 글, 음식, 한복 같은 생활 양식을 세계에 알린다.","다른 나라에서 한국어를 배우려는 사람에게 한국어를 중심으로 가르친다.","2022년 기준으로 세종 학당은 84개 나라에 244곳이 있다.","한국 요리, 역사, 관광 등 다양한 이유로 한국어를 배우는 사람이 늘었다."],"numbered":false,"title":"한류에 푹 빠진 세계인들 — 교과서 28쪽 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_challenge#7','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',3,'ox','auto','세계 사람들은 감염병 문제를 해결하려고 예방 수칙을 잘 지키고 예방 주사약과 치료 약 등을 나누려고 노력했어요.',ARRAY['SO3-2-u1-X17']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C5","difficulty":3,"kind":"ox","stem":"세계 사람들은 감염병 문제를 해결하려고 예방 수칙을 잘 지키고 예방 주사약과 치료 약 등을 나누려고 노력했어요.","answer":"O","reason_options":[{"t":"감염병처럼 세계 여러 나라에 퍼지는 문제는 함께 해결해야 하기 때문에","correct":true},{"t":"감염병은 한 나라에서만 생기는 문제이기 때문에","mis":"SO3-2-u1-X17"}],"mis":"SO3-2-u1-X17","explanation":["교과서 29쪽 물음을 떠올려요.","세계가 함께 노력했어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_challenge#8','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',4,'mc','auto','교과서 27~30쪽에서 공부한 세계화의 모습을 종합한 설명으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X16','SO3-2-u1-X17','SO3-2-u1-X15']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C5","difficulty":4,"kind":"mc","stem":"교과서 27~30쪽에서 공부한 세계화의 모습을 종합한 설명으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"다른 나라의 물건과 생활 양식이 들어오고, 우리나라의 물건과 생활 양식도 세계로 퍼지며, 문제도 함께 생겨요","correct":true},{"t":"다른 나라 것이 들어오기만 하고 우리 것은 나가지 않아요","mis":"SO3-2-u1-X16"},{"t":"세계화로 생긴 문제는 하나도 없어요","mis":"SO3-2-u1-X17"},{"t":"세계화는 한 나라하고만 교류하는 거예요","mis":"SO3-2-u1-X15"}],"explanation":["들어오는 것이 있어요.","나가는 것도 있어요.","문제도 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_challenge#9','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',4,'mc','auto','첫 번째 광고 문구가 해결에 도움을 주려는 세계화의 문제는 무엇인가요?',ARRAY['SO3-2-u1-X17','SO3-2-u1-X15','SO3-2-u1-X16']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C5","difficulty":4,"kind":"mc","stem":"첫 번째 광고 문구가 해결에 도움을 주려는 세계화의 문제는 무엇인가요?","options":[{"t":"전 세계 사람들의 생활 양식이 비슷해지면서 각 나라의 전통적인 생활 양식이 약해지는 문제","correct":true},{"t":"감염병이 전 세계로 빠르게 퍼지는 문제","mis":"SO3-2-u1-X17"},{"t":"다른 나라 영화를 볼 수 없는 문제","mis":"SO3-2-u1-X15"},{"t":"세종 학당이 줄어드는 문제","mis":"SO3-2-u1-X16"}],"explanation":["우리 전통을 소중히 여겨요.","전통이 약해지는 문제가 있어요.","그 문제에 대응하는 문구예요."],"asset":{"type":"passage","lines":["첫 번째 — 소중히 여기는 우리 전통, 더 나은 세계화","두 번째 — 세계인의 관심으로 만드는 모두가 행복한 세상","세 번째 — 우리의 작은 관심이 만드는 세계인의 더 큰 행복"],"title":"세계화에 대응하는 태도를 담은 광고 문구 — 교과서 29쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L05_challenge#10','soc',3,2,'u1','L05','tb_g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',4,'essay','teacher','우리나라의 생활 양식 가운데 다른 나라 사람들에게 소개하고 싶은 것 하나를 골라 까닭을 쓰고, 세계화에 대응하기 위해 우리가 갖춰야 할 태도를 광고 문구 한 문장으로 만들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C5","difficulty":4,"kind":"essay","stem":"우리나라의 생활 양식 가운데 다른 나라 사람들에게 소개하고 싶은 것 하나를 골라 까닭을 쓰고, 세계화에 대응하기 위해 우리가 갖춰야 할 태도를 광고 문구 한 문장으로 만들어 쓰세요.","answer_guide":{"answer":"예: 한복의 아름다움을 알리고 싶어요. 우리 전통이 담겨 있어 세계 사람들에게 우리 생활 양식을 보여 줄 수 있기 때문이에요. 광고 문구 — 우리 것은 소중히, 다른 나라 것은 따져 보고 받아들여요.","scoring_points":["소개하고 싶은 생활 양식과 까닭을 썼는가","광고 문구를 한 문장으로 썼는가","문구에 세계화에 대응하는 태도가 담겼는가"]},"explanation":["우리 생활 양식을 골라요.","까닭을 써요.","태도를 한 문장에 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L06_basic#1','soc',3,2,'u1','L06','tb_g3_2_soc_u1_L06_basic','lesson_basic','SO3-2-u1-C6',1,'mc','auto','낱말 퍼즐 세로 ❶의 열쇠 「사람들이 건강하고 행복하게 살 수 있도록 사회에서 지원하는 제도」에 알맞은 낱말은 무엇인가요?',ARRAY['SO3-2-u1-X18']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C6","difficulty":1,"kind":"mc","stem":"낱말 퍼즐 세로 ❶의 열쇠 「사람들이 건강하고 행복하게 살 수 있도록 사회에서 지원하는 제도」에 알맞은 낱말은 무엇인가요?","options":[{"t":"복지 제도","correct":true},{"t":"정보 통신 기술","mis":"SO3-2-u1-X18"},{"t":"출산율","mis":"SO3-2-u1-X18"},{"t":"고령화","mis":"SO3-2-u1-X18"}],"explanation":["사회에서 지원해요.","건강하고 행복하게 살도록요.","복지 제도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L06_basic#2','soc',3,2,'u1','L06','tb_g3_2_soc_u1_L06_basic','lesson_basic','SO3-2-u1-C6',1,'sa','auto','낱말 퍼즐의 가려진 칸을 모두 채우고 글자판에 남은 세 글자로 만든 낱말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C6","difficulty":1,"kind":"sa","stem":"낱말 퍼즐의 가려진 칸을 모두 채우고 글자판에 남은 세 글자로 만든 낱말을 쓰세요.","answer":["세계화"],"explanation":["퍼즐에 쓴 글자를 지워요.","세·계·화가 남아요.","세계화예요."],"asset":{"type":"passage","lines":["가로 ❷ 인공지능을 활용한 다양한 기술이 사회 전반에 폭넓은 영향을 미치는 현상","가로 ❻ 태어나는 아이의 수가 줄어들어 □□□이/가 감소하는 현상을 저출산이라고 해요.","세로 ❶ 사람들이 건강하고 행복하게 살 수 있도록 사회에서 지원하는 제도","세로 ❸ 전화, 컴퓨터와 같은 기기를 이용해 정보를 주고받는 기술","세로 ❹ 전체 사람 수에서 노인의 수가 차지하는 비율이 높아지는 현상","세로 ❺ 아이를 낳아 기르는 것에 부담을 느끼는 사람이 많아지며 나타나는 현상","글자판 — 출 세 지 화 산 능 정 령 복 계 보 통"],"numbered":false,"title":"재미있게 확인해요 — 낱말 퍼즐 열쇠(교과서 33쪽)"},"mis":"SO3-2-u1-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L06_basic#3','soc',3,2,'u1','L06','tb_g3_2_soc_u1_L06_basic','lesson_basic','SO3-2-u1-C6',1,'ox','auto','카드 뉴스를 만들 때는 먼저 오늘날의 다양한 사회 변화 가운데 하나를 골라 주제를 정해요.',ARRAY['SO3-2-u1-X19']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C6","difficulty":1,"kind":"ox","stem":"카드 뉴스를 만들 때는 먼저 오늘날의 다양한 사회 변화 가운데 하나를 골라 주제를 정해요.","answer":"O","reason_options":[{"t":"교과서 31쪽 차례에서 주제 정하기가 첫 번째이기 때문에","correct":true},{"t":"그림을 먼저 그리고 주제는 마지막에 정하기 때문에","mis":"SO3-2-u1-X19"}],"mis":"SO3-2-u1-X19","explanation":["31쪽 차례를 떠올려요.","주제가 먼저예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
