INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L08_basic#5','soc',3,2,'u1','L08','tb_g3_2_soc_u1_L08_basic','lesson_basic','SO3-2-u1-C8',2,'mc','auto','교과서 38~39쪽 그림 ⑤에 알맞은 붙임딱지의 대사는 무엇인가요?',ARRAY['SO3-2-u1-X24']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C8","difficulty":2,"kind":"mc","stem":"교과서 38~39쪽 그림 ⑤에 알맞은 붙임딱지의 대사는 무엇인가요?","options":[{"t":"「오늘은 1인분 간편식을 사 먹어야지.」","correct":true},{"t":"「우리 숙모는 베트남 사람이에요.」","mis":"SO3-2-u1-X24"},{"t":"「인도 요리사가 직접 음식을 만든다고 해요.」","mis":"SO3-2-u1-X24"},{"t":"「반려동물 전용 놀이터가 있어서 강아지들이 안전하게 뛰어놀 수 있구나.」","mis":"SO3-2-u1-X24"}],"explanation":["그림 ⑤는 상점이에요.","1인분 간편식을 골라요.","1인 가구와 관계있는 대사예요."],"asset":{"type":"passage","lines":["① 1층 바둑 두는 할아버지 · 2층 아프리카 미술 방송을 보는 부부","　· 3층 고양이가 좋아하는 간식을 알아보는 어린이","② 새로 문을 연 인도 음식점에서 맨손으로 음식을 먹는 사람들","③ 야외 결혼식장 — 한국인 남자와 외국인 여자의 결혼식","④ 공원의 반려동물 전용 놀이터에서 뛰노는 강아지들","⑤ 상점에서 1인분 간편식을 고르는 사람(간판 — 혼자 만들어 먹는 맛있는 집밥)","그 밖에 — 보조견과 산책하는 시각 장애인, 피자와 파스타를 먹는 할머니와 손자"],"numbered":false,"title":"교과서 38~39쪽 그림 속 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L08_basic#6','soc',3,2,'u1','L08','tb_g3_2_soc_u1_L08_basic','lesson_basic','SO3-2-u1-C8',2,'match','auto','그림 속 장면과 관계있는 우리 사회의 다양한 문화를 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u1-C8","difficulty":2,"kind":"match","stem":"그림 속 장면과 관계있는 우리 사회의 다양한 문화를 이으세요.","pairs":[{"l":"③ 야외 결혼식장","r":"외국인 이주민이 늘어나며 나타난 문화"},{"l":"⑤ 1인분 간편식","r":"1인 가구가 늘어나며 나타난 문화"},{"l":"④ 반려동물 전용 놀이터","r":"반려동물과 함께 사는 사람이 늘어나며 나타난 문화"}],"mis":"SO3-2-u1-X24","explanation":["한국인과 외국인이 결혼해요.","혼자 먹을 간편식이에요.","강아지들이 뛰놀아요."],"asset":{"type":"passage","lines":["① 1층 바둑 두는 할아버지 · 2층 아프리카 미술 방송을 보는 부부","　· 3층 고양이가 좋아하는 간식을 알아보는 어린이","② 새로 문을 연 인도 음식점에서 맨손으로 음식을 먹는 사람들","③ 야외 결혼식장 — 한국인 남자와 외국인 여자의 결혼식","④ 공원의 반려동물 전용 놀이터에서 뛰노는 강아지들","⑤ 상점에서 1인분 간편식을 고르는 사람(간판 — 혼자 만들어 먹는 맛있는 집밥)","그 밖에 — 보조견과 산책하는 시각 장애인, 피자와 파스타를 먹는 할머니와 손자"],"numbered":false,"title":"교과서 38~39쪽 그림 속 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L08_basic#7','soc',3,2,'u1','L08','tb_g3_2_soc_u1_L08_basic','lesson_basic','SO3-2-u1-C8',2,'blank','auto','세계화의 영향으로 직장, 공부, 결혼 등 다양한 목적으로 우리나라에서 사는 (    ) 이주민이 늘어났어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X25','SO3-2-u1-X24']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C8","difficulty":2,"kind":"blank","stem":"세계화의 영향으로 직장, 공부, 결혼 등 다양한 목적으로 우리나라에서 사는 (    ) 이주민이 늘어났어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"외국인","correct":true},{"t":"노인","mis":"SO3-2-u1-X25"},{"t":"어린이","mis":"SO3-2-u1-X25"},{"t":"1인","mis":"SO3-2-u1-X24"}],"explanation":["교과서 40쪽 본문이에요.","세계화의 영향이에요.","외국인 이주민이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L08_basic#8','soc',3,2,'u1','L08','tb_g3_2_soc_u1_L08_basic','lesson_basic','SO3-2-u1-C8',2,'mc','auto','반려동물과 함께 사는 사람이 많아진 까닭으로 교과서 42쪽에서 든 것은 무엇인가요?',ARRAY['SO3-2-u1-X25']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C8","difficulty":2,"kind":"mc","stem":"반려동물과 함께 사는 사람이 많아진 까닭으로 교과서 42쪽에서 든 것은 무엇인가요?","options":[{"t":"1인 가구가 늘어나고 생활 수준이 높아졌기 때문이에요","correct":true},{"t":"1인 가구가 줄어들었기 때문이에요","mis":"SO3-2-u1-X25"},{"t":"외국인 이주민이 줄었기 때문이에요","mis":"SO3-2-u1-X25"},{"t":"반려동물 놀이터가 없어졌기 때문이에요","mis":"SO3-2-u1-X25"}],"explanation":["혼자 사는 사람이 늘었어요.","생활 수준도 높아졌어요.","그래서 반려동물과 사는 사람이 많아졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L08_basic#9','soc',3,2,'u1','L08','tb_g3_2_soc_u1_L08_basic','lesson_basic','SO3-2-u1-C8',2,'ox','auto','오늘날 우리 사회에는 하나의 문화만 있어요.',ARRAY['SO3-2-u1-X36']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C8","difficulty":2,"kind":"ox","stem":"오늘날 우리 사회에는 하나의 문화만 있어요.","answer":"X","reason_options":[{"t":"외국인 이주민, 1인 가구, 반려동물과 함께 사는 사람이 늘며 한 나라 안에서도 다양한 문화가 나타나기 때문에","correct":true},{"t":"한 나라에는 하나의 문화만 있기 때문에","mis":"SO3-2-u1-X36"}],"mis":"SO3-2-u1-X36","explanation":["그림 속 동네를 떠올려요.","여러 문화가 함께 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L08_basic#10','soc',3,2,'u1','L08','tb_g3_2_soc_u1_L08_basic','lesson_basic','SO3-2-u1-C8',3,'error','auto','교과서 41쪽 두 사람의 생활 모습을 보고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X34','SO3-2-u1-X24','SO3-2-u1-X25']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C8","difficulty":3,"kind":"error","stem":"교과서 41쪽 두 사람의 생활 모습을 보고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 나 — 「혼자 사는 사람들은 모두 외롭게 집에만 있어.」","correct":true,"mis_target":"SO3-2-u1-X34"},{"t":"친구 가 — 「김○○ 씨는 운동하고 그림을 배우고 여행을 가며 지내.」","mis":"SO3-2-u1-X24"},{"t":"친구 다 — 「두 사람 모두 자신이 하고 싶은 것을 즐기며 살아.」","mis":"SO3-2-u1-X25"}],"explanation":["두 사람의 하루를 읽어요.","하고 싶은 것을 즐기며 살아요.","친구 나가 섣불리 판단했어요."],"asset":{"type":"passage","lines":["결혼하지 않고 혼자 사는 삶을 선택한 30대 여성 김○○ 씨","　아침마다 체육관에서 운동하고, 일을 마친 뒤에는 그림을 배우러 다녀요.","　친구들과 종종 여행을 가요.","오랜 꿈을 이루며 혼자 사는 60대 남성 박△△ 씨","　어린 시절 형편이 어려워 학교에 다니지 못했어요.","　요즘 노인 대학에서 열심히 공부하고, 오후에는 탁구를 배워요."],"numbered":false,"title":"혼자 사는 사람들의 생활 모습 — 교과서 41쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L08_challenge#1','soc',3,2,'u1','L08','tb_g3_2_soc_u1_L08_challenge','lesson_challenge','SO3-2-u1-C8',2,'sa','auto','그래프에서 외국인 이주민 수가 처음으로 200만 명을 넘은 해는 언제인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C8","difficulty":2,"kind":"sa","stem":"그래프에서 외국인 이주민 수가 처음으로 200만 명을 넘은 해는 언제인가요? 숫자로 쓰세요.","answer":["2018"],"explanation":["200만 명보다 많은 해를 찾아요.","2015년은 171만 명이에요.","2018년에 205만 명이 되었어요."],"asset":{"type":"passage","lines":["2009년 — 111만 명 · 2012년 — 141만 명","2015년 — 171만 명 · 2018년 — 205만 명","2021년 — 213만 명"],"numbered":false,"title":"우리나라의 외국인 이주민 수"},"mis":"SO3-2-u1-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L08_challenge#2','soc',3,2,'u1','L08','tb_g3_2_soc_u1_L08_challenge','lesson_challenge','SO3-2-u1-C8',2,'ox','auto','박△△ 씨는 어린 시절 형편이 어려워 학교에 다니지 못했지만, 요즘 노인 대학에서 공부하며 오랜 꿈을 이루고 있어요.',ARRAY['SO3-2-u1-X25']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C8","difficulty":2,"kind":"ox","stem":"박△△ 씨는 어린 시절 형편이 어려워 학교에 다니지 못했지만, 요즘 노인 대학에서 공부하며 오랜 꿈을 이루고 있어요.","answer":"O","reason_options":[{"t":"교과서 41쪽 두 번째 사례에 나온 내용이기 때문에","correct":true},{"t":"혼자 사는 노인은 배울 기회가 없기 때문에","mis":"SO3-2-u1-X25"}],"mis":"SO3-2-u1-X25","explanation":["두 번째 사례를 읽어요.","노인 대학에서 공부해요.","그래서 O예요."],"asset":{"type":"passage","lines":["결혼하지 않고 혼자 사는 삶을 선택한 30대 여성 김○○ 씨","　아침마다 체육관에서 운동하고, 일을 마친 뒤에는 그림을 배우러 다녀요.","　친구들과 종종 여행을 가요.","오랜 꿈을 이루며 혼자 사는 60대 남성 박△△ 씨","　어린 시절 형편이 어려워 학교에 다니지 못했어요.","　요즘 노인 대학에서 열심히 공부하고, 오후에는 탁구를 배워요."],"numbered":false,"title":"혼자 사는 사람들의 생활 모습 — 교과서 41쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L08_challenge#3','soc',3,2,'u1','L08','tb_g3_2_soc_u1_L08_challenge','lesson_challenge','SO3-2-u1-C8',3,'mc','auto','외국인 이주민 수 그래프에서 알 수 있는 변화로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X25','SO3-2-u1-X05']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C8","difficulty":3,"kind":"mc","stem":"외국인 이주민 수 그래프에서 알 수 있는 변화로 가장 알맞은 것은 무엇인가요?","options":[{"t":"2009년 111만 명에서 2021년 213만 명으로 우리나라에 사는 외국인 이주민이 늘어나고 있어요","correct":true},{"t":"외국인 이주민 수가 점점 줄어들고 있어요","mis":"SO3-2-u1-X25"},{"t":"외국인 이주민 수는 변화가 없어요","mis":"SO3-2-u1-X05"},{"t":"2012년에 가장 많았어요","mis":"SO3-2-u1-X05"}],"explanation":["처음과 끝을 견줘요.","111만 명에서 213만 명이 되었어요.","늘어나고 있어요."],"asset":{"type":"passage","lines":["2009년 — 111만 명 · 2012년 — 141만 명","2015년 — 171만 명 · 2018년 — 205만 명","2021년 — 213만 명"],"numbered":false,"title":"우리나라의 외국인 이주민 수 — 교과서 40쪽 그래프"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L08_challenge#4','soc',3,2,'u1','L08','tb_g3_2_soc_u1_L08_challenge','lesson_challenge','SO3-2-u1-C8',3,'mc','auto','교과서 40쪽 사진처럼 다양한 나라의 물건과 음식을 파는 거리가 있는 지역에서 나타날 생활 모습을 예상한 것으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X25','SO3-2-u1-X36']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C8","difficulty":3,"kind":"mc","stem":"교과서 40쪽 사진처럼 다양한 나라의 물건과 음식을 파는 거리가 있는 지역에서 나타날 생활 모습을 예상한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"다양한 나라의 물건과 음식을 사거나 구경하려고 사람들이 모여들 것 같아요","correct":true},{"t":"외국인 이주민이 모두 떠나 가게가 문을 닫을 것 같아요","mis":"SO3-2-u1-X25"},{"t":"한 나라의 음식만 팔 것 같아요","mis":"SO3-2-u1-X36"},{"t":"사람들이 찾지 않는 조용한 거리가 될 것 같아요","mis":"SO3-2-u1-X25"}],"explanation":["다양한 나라의 물건과 음식이 있어요.","사람들이 찾아와요.","사고 구경하려고 모여들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L08_challenge#5','soc',3,2,'u1','L08','tb_g3_2_soc_u1_L08_challenge','lesson_challenge','SO3-2-u1-C8',3,'mc','auto','교과서 41쪽 두 사례로 알 수 있는 혼자 사는 사람들의 생활 모습의 특징은 무엇인가요?',ARRAY['SO3-2-u1-X25']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C8","difficulty":3,"kind":"mc","stem":"교과서 41쪽 두 사례로 알 수 있는 혼자 사는 사람들의 생활 모습의 특징은 무엇인가요?","options":[{"t":"자신이 하고 싶은 것을 즐기며 살아요","correct":true},{"t":"하고 싶은 일을 하나도 하지 못해요","mis":"SO3-2-u1-X25"},{"t":"혼자 사는 사람은 모두 젊은 사람이에요","mis":"SO3-2-u1-X25"},{"t":"혼자 사는 사람은 모두 노인이에요","mis":"SO3-2-u1-X25"}],"explanation":["30대 김○○ 씨와 60대 박△△ 씨예요.","나이는 다르지만 즐기며 살아요.","하고 싶은 것을 즐겨요."],"asset":{"type":"passage","lines":["결혼하지 않고 혼자 사는 삶을 선택한 30대 여성 김○○ 씨","　아침마다 체육관에서 운동하고, 일을 마친 뒤에는 그림을 배우러 다녀요.","　친구들과 종종 여행을 가요.","오랜 꿈을 이루며 혼자 사는 60대 남성 박△△ 씨","　어린 시절 형편이 어려워 학교에 다니지 못했어요.","　요즘 노인 대학에서 열심히 공부하고, 오후에는 탁구를 배워요."],"numbered":false,"title":"혼자 사는 사람들의 생활 모습 — 교과서 41쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L08_challenge#6','soc',3,2,'u1','L08','tb_g3_2_soc_u1_L08_challenge','lesson_challenge','SO3-2-u1-C8',3,'error','auto','반려동물과 함께 사는 친구에게 물어본 말 가운데 서로 다른 문화를 존중하지 않는 말을 고르세요.',ARRAY['SO3-2-u1-X34','SO3-2-u1-X24']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C8","difficulty":3,"kind":"error","stem":"반려동물과 함께 사는 친구에게 물어본 말 가운데 서로 다른 문화를 존중하지 않는 말을 고르세요.","options":[{"t":"친구 다 — 「강아지를 가족이라고 하다니 이상하지 않니?」","correct":true,"mis_target":"SO3-2-u1-X34"},{"t":"친구 가 — 「반려동물을 키우는 까닭은 무엇이니?」","mis":"SO3-2-u1-X24"},{"t":"친구 나 — 「반려동물과 함께 있으면 어떤 점이 좋니?」","mis":"SO3-2-u1-X24"}],"explanation":["궁금한 것을 묻는 것은 좋아요.","상대의 생활을 이상하다고 하면 안 돼요.","친구 다의 말이 존중하지 않는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L08_challenge#7','soc',3,2,'u1','L08','tb_g3_2_soc_u1_L08_challenge','lesson_challenge','SO3-2-u1-C8',3,'ox','auto','교과서 38~39쪽 그림 ① 건물에서는 할아버지는 바둑을 두고, 부부는 아프리카 미술 방송을 보고, 어린이는 고양이 간식을 알아보는 등 여러 세대의 여가 생활이 나타나요.',ARRAY['SO3-2-u1-X36']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C8","difficulty":3,"kind":"ox","stem":"교과서 38~39쪽 그림 ① 건물에서는 할아버지는 바둑을 두고, 부부는 아프리카 미술 방송을 보고, 어린이는 고양이 간식을 알아보는 등 여러 세대의 여가 생활이 나타나요.","answer":"O","reason_options":[{"t":"한 건물 안에서도 사람마다 즐기는 생활 모습이 다양하기 때문에","correct":true},{"t":"한 건물에 사는 사람들은 모두 같은 여가 생활을 하기 때문에","mis":"SO3-2-u1-X36"}],"mis":"SO3-2-u1-X36","explanation":["1층, 2층, 3층을 봐요.","하는 일이 다 달라요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 1층 바둑 두는 할아버지 · 2층 아프리카 미술 방송을 보는 부부","　· 3층 고양이가 좋아하는 간식을 알아보는 어린이","② 새로 문을 연 인도 음식점에서 맨손으로 음식을 먹는 사람들","③ 야외 결혼식장 — 한국인 남자와 외국인 여자의 결혼식","④ 공원의 반려동물 전용 놀이터에서 뛰노는 강아지들","⑤ 상점에서 1인분 간편식을 고르는 사람(간판 — 혼자 만들어 먹는 맛있는 집밥)","그 밖에 — 보조견과 산책하는 시각 장애인, 피자와 파스타를 먹는 할머니와 손자"],"numbered":false,"title":"교과서 38~39쪽 그림 속 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L08_challenge#8','soc',3,2,'u1','L08','tb_g3_2_soc_u1_L08_challenge','lesson_challenge','SO3-2-u1-C8',4,'mc','auto','외국인 이주민, 1인 가구, 반려동물과 함께 사는 사람이 늘어난 까닭을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u1-X25']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C8","difficulty":4,"kind":"mc","stem":"외국인 이주민, 1인 가구, 반려동물과 함께 사는 사람이 늘어난 까닭을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"외국인 이주민 — 세계화의 영향 · 1인 가구 — 결혼에 관한 생각 변화 · 반려동물 — 생활 수준 향상","correct":true},{"t":"외국인 이주민 — 생활 수준 향상 · 1인 가구 — 세계화의 영향 · 반려동물 — 결혼에 관한 생각 변화","mis":"SO3-2-u1-X25"},{"t":"외국인 이주민 — 결혼에 관한 생각 변화 · 1인 가구 — 생활 수준 향상 · 반려동물 — 세계화의 영향","mis":"SO3-2-u1-X25"},{"t":"세 경우 모두 늘어나지 않고 줄어들고 있어요","mis":"SO3-2-u1-X25"}],"explanation":["이주민은 세계화의 영향이에요.","1인 가구는 결혼에 관한 생각 변화예요.","반려동물은 생활 수준 향상과 관계있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L08_challenge#9','soc',3,2,'u1','L08','tb_g3_2_soc_u1_L08_challenge','lesson_challenge','SO3-2-u1-C8',4,'mc','auto','친구들과 반려동물에 관해 묻고 답할 때 지켜야 할 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X36','SO3-2-u1-X34']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C8","difficulty":4,"kind":"mc","stem":"친구들과 반려동물에 관해 묻고 답할 때 지켜야 할 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"서로 다른 문화를 존중하며 궁금한 점을 묻고, 감정적으로 판단하는 말을 하지 않아요","correct":true},{"t":"반려동물을 키우지 않는 친구는 말하지 못하게 해요","mis":"SO3-2-u1-X36"},{"t":"내가 싫어하는 동물을 키우는 친구를 놀려요","mis":"SO3-2-u1-X34"},{"t":"반려동물은 가족이 될 수 없다고 정해 줘요","mis":"SO3-2-u1-X34"}],"explanation":["궁금한 점을 물어요.","친구의 생활을 존중해요.","감정적으로 판단하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L08_challenge#10','soc',3,2,'u1','L08','tb_g3_2_soc_u1_L08_challenge','lesson_challenge','SO3-2-u1-C8',4,'essay','teacher','교과서 38~39쪽 그림 가운데 두 장면을 골라 각각 어떤 문화가 나타나는지 쓰고, 그 문화와 관련 있는 내 경험을 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C8","difficulty":4,"kind":"essay","stem":"교과서 38~39쪽 그림 가운데 두 장면을 골라 각각 어떤 문화가 나타나는지 쓰고, 그 문화와 관련 있는 내 경험을 하나 쓰세요.","answer_guide":{"answer":"예: ② 인도 음식점에서 맨손으로 음식을 먹는 모습은 외국인 이주민이 늘어나며 나타난 문화이고, ④ 반려동물 전용 놀이터는 반려동물과 함께 사는 사람이 늘어나며 나타난 문화예요. 나는 공원에서 우리 집 강아지와 함께 산책한 적이 있어요.","scoring_points":["두 장면을 골랐는가","장면에 알맞은 문화를 썼는가","관련 있는 경험을 썼는가"]},"explanation":["두 장면을 골라요.","어떤 문화인지 써요.","내 경험과 이어요."],"asset":{"type":"passage","lines":["① 1층 바둑 두는 할아버지 · 2층 아프리카 미술 방송을 보는 부부","　· 3층 고양이가 좋아하는 간식을 알아보는 어린이","② 새로 문을 연 인도 음식점에서 맨손으로 음식을 먹는 사람들","③ 야외 결혼식장 — 한국인 남자와 외국인 여자의 결혼식","④ 공원의 반려동물 전용 놀이터에서 뛰노는 강아지들","⑤ 상점에서 1인분 간편식을 고르는 사람(간판 — 혼자 만들어 먹는 맛있는 집밥)","그 밖에 — 보조견과 산책하는 시각 장애인, 피자와 파스타를 먹는 할머니와 손자"],"numbered":false,"title":"교과서 38~39쪽 그림 속 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_basic#1','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',1,'mc','auto','나와 다르고 익숙하지 않은 것에 대해 공정하지 못하고 한쪽으로 치우친 생각을 가리키는 말은 무엇인가요?',ARRAY['SO3-2-u1-X27']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C9","difficulty":1,"kind":"mc","stem":"나와 다르고 익숙하지 않은 것에 대해 공정하지 못하고 한쪽으로 치우친 생각을 가리키는 말은 무엇인가요?","options":[{"t":"편견","correct":true},{"t":"차별","mis":"SO3-2-u1-X27"},{"t":"존중","mis":"SO3-2-u1-X27"},{"t":"이해","mis":"SO3-2-u1-X27"}],"explanation":["교과서 46쪽 본문이에요.","치우친 생각이에요.","편견이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_basic#2','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',1,'sa','auto','신문 기사에서 2020년 기준 우리나라에서 가장 많은 가구 형태를 찾아 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C9","difficulty":1,"kind":"sa","stem":"신문 기사에서 2020년 기준 우리나라에서 가장 많은 가구 형태를 찾아 쓰세요.","answer":["1인 가구","1인가구"],"explanation":["기사 첫 줄을 봐요.","혼자 사는 가구예요.","1인 가구예요."],"asset":{"type":"passage","lines":["2020년 기준 우리나라에서 가장 많은 가구 형태는 1인 가구이다.","1인 가구는 비교적 작은 집에 사는 경우가 많다.","크기가 작은 세탁기, 냉장고, 식기세척기 등이 새롭게 나오고 있다.","상점에서도 적은 양을 포장한 상품이 많아지고 있다."],"numbered":false,"title":"1인 가구 증가로 생활 모습이 달라진다 — 교과서 44쪽 신문 기사"},"mis":"SO3-2-u1-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_basic#3','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',1,'ox','auto','우리 사회에 다양한 문화가 확산되면서 사람들은 자신이 원하는 다양한 문화를 누리며 살 수 있게 되었어요.',ARRAY['SO3-2-u1-X26']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C9","difficulty":1,"kind":"ox","stem":"우리 사회에 다양한 문화가 확산되면서 사람들은 자신이 원하는 다양한 문화를 누리며 살 수 있게 되었어요.","answer":"O","reason_options":[{"t":"사람들이 누리고 선택할 수 있는 문화가 많아져 일상생활이 풍요로워졌기 때문에","correct":true},{"t":"다양한 문화가 퍼지면 누릴 수 있는 문화가 줄어들기 때문에","mis":"SO3-2-u1-X26"}],"mis":"SO3-2-u1-X26","explanation":["교과서 45쪽 본문이에요.","누릴 문화가 많아졌어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_basic#4','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',1,'mc','auto','교과서 45쪽에서 반려동물의 문제 행동을 바로잡아 주는 직업은 무엇인가요?',ARRAY['SO3-2-u1-X28']::text[],true,'{"seq":4,"concept":"SO3-2-u1-C9","difficulty":1,"kind":"mc","stem":"교과서 45쪽에서 반려동물의 문제 행동을 바로잡아 주는 직업은 무엇인가요?","options":[{"t":"반려동물 훈련사","correct":true},{"t":"수의사","mis":"SO3-2-u1-X28"},{"t":"반려동물 미용사","mis":"SO3-2-u1-X28"},{"t":"인공지능 전문가","mis":"SO3-2-u1-X28"}],"explanation":["반려동물과 관련 있는 직업이에요.","문제 행동을 바로잡아요.","반려동물 훈련사예요."],"variant_rule":{"alt":[{"stem":"교과서 45쪽에서 반려동물의 미용과 청결을 관리해 주는 직업은 무엇인가요?","options":[{"t":"반려동물 미용사","correct":true},{"t":"수의사","mis":"SO3-2-u1-X28"},{"t":"반려동물 훈련사","mis":"SO3-2-u1-X28"},{"t":"인공지능 전문가","mis":"SO3-2-u1-X28"}],"explanation":["반려동물과 관련 있는 직업이에요.","털과 몸을 깨끗이 해요.","반려동물 미용사예요."],"asset":{"type":"passage","lines":["수의사 — 반려동물의 건강을 돌봐 줘요.","반려동물 훈련사 — 반려동물의 문제 행동을 바로잡아 줘요.","반려동물 미용사 — 반려동물의 미용과 청결을 관리해 줘요."],"title":"반려동물과 관련 있는 직업 — 교과서 45쪽"}},{"stem":"교과서 45쪽에서 반려동물의 건강을 돌봐 주는 직업은 무엇인가요?","options":[{"t":"수의사","correct":true},{"t":"반려동물 훈련사","mis":"SO3-2-u1-X28"},{"t":"반려동물 미용사","mis":"SO3-2-u1-X28"},{"t":"인공지능 전문가","mis":"SO3-2-u1-X28"}],"explanation":["반려동물과 관련 있는 직업이에요.","아플 때 찾아가요.","수의사예요."],"asset":{"type":"passage","lines":["수의사 — 반려동물의 건강을 돌봐 줘요.","반려동물 훈련사 — 반려동물의 문제 행동을 바로잡아 줘요.","반려동물 미용사 — 반려동물의 미용과 청결을 관리해 줘요."],"title":"반려동물과 관련 있는 직업 — 교과서 45쪽"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_basic#5','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',2,'mc','auto','교과서 46쪽 그림 속 세 상황에 공통으로 나타난 문제는 무엇인가요?',ARRAY['SO3-2-u1-X28','SO3-2-u1-X26']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"mc","stem":"교과서 46쪽 그림 속 세 상황에 공통으로 나타난 문제는 무엇인가요?","options":[{"t":"낯선 문화에 대한 편견을 가지고 다르게 대우하는 차별","correct":true},{"t":"반려동물로 생긴 이웃 간 갈등","mis":"SO3-2-u1-X28"},{"t":"혼자 사는 사람의 외로움","mis":"SO3-2-u1-X28"},{"t":"아무 문제도 없는 상황","mis":"SO3-2-u1-X26"}],"explanation":["종교, 언어, 피부색이 달라요.","그 까닭으로 부당하게 대해요.","편견과 차별이에요."],"asset":{"type":"passage","lines":["① 종교적인 이유로 고기를 먹지 않는 것을 비난해요.","　「고기를 먹지 않는 것은 옳지 않아.」","② 우리말을 잘하지 못해서 무시해요.","　「아휴, 답답해. 우리말을 너무 못하네.」","③ 자신과 피부색이 다른 사람을 이상한 눈빛으로 쳐다보거나 거리를 둬요.","　「다른 자리에 앉아야지.」"],"numbered":false,"title":"교과서 46쪽 그림 속 세 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_basic#6','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',2,'match','auto','다양한 문화가 확산되면서 나타난 긍정적 효과와 관계있는 사람들을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"match","stem":"다양한 문화가 확산되면서 나타난 긍정적 효과와 관계있는 사람들을 이으세요.","pairs":[{"l":"세계 여러 나라의 문화를 경험할 기회가 늘어남","r":"외국인 이주민"},{"l":"크기가 작은 가전제품과 적은 양을 포장한 상품이 많아짐","r":"1인 가구"},{"l":"수의사, 반려동물 훈련사, 반려동물 미용사 같은 직업이 많아짐","r":"반려동물과 함께 사는 사람"}],"mis":"SO3-2-u1-X28","explanation":["여러 나라 문화예요.","혼자 쓰기 좋은 제품이에요.","반려동물과 관련 있는 직업이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_basic#7','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',2,'blank','auto','편견을 가지고 대상을 다르게 대우하는 것을 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X27']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"blank","stem":"편견을 가지고 대상을 다르게 대우하는 것을 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"차별","correct":true},{"t":"편견","mis":"SO3-2-u1-X27"},{"t":"존중","mis":"SO3-2-u1-X27"},{"t":"관심","mis":"SO3-2-u1-X27"}],"explanation":["교과서 46쪽 본문이에요.","다르게 대우하는 행동이에요.","차별이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_basic#8','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',2,'mc','auto','교과서 47쪽 표에서 반려동물로 이웃 간에 갈등이 생긴 원인 가운데 2위는 무엇인가요?',ARRAY['SO3-2-u1-X05']::text[],true,'{"seq":8,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"mc","stem":"교과서 47쪽 표에서 반려동물로 이웃 간에 갈등이 생긴 원인 가운데 2위는 무엇인가요?","options":[{"t":"배설물","correct":true},{"t":"소음(짖음, 발소리)","mis":"SO3-2-u1-X05"},{"t":"냄새","mis":"SO3-2-u1-X05"},{"t":"물림","mis":"SO3-2-u1-X05"}],"explanation":["표의 순위를 봐요.","1위는 소음이에요.","2위는 배설물이에요."],"asset":{"type":"passage","lines":["1위 소음(짖음, 발소리)","2위 배설물","3위 냄새","4위 목줄이나 입마개 미착용","5위 물림"],"numbered":false,"title":"반려동물로 이웃 간에 갈등이 생긴 주요 원인 — 교과서 47쪽"},"variant_rule":{"alt":[{"stem":"교과서 47쪽 표에서 반려동물로 이웃 간에 갈등이 생긴 원인 가운데 3위는 무엇인가요?","options":[{"t":"냄새","correct":true},{"t":"소음(짖음, 발소리)","mis":"SO3-2-u1-X05"},{"t":"배설물","mis":"SO3-2-u1-X05"},{"t":"물림","mis":"SO3-2-u1-X05"}],"explanation":["표의 순위를 봐요.","2위 다음이에요.","3위는 냄새예요."],"asset":{"type":"passage","lines":["1위 소음(짖음, 발소리)","2위 배설물","3위 냄새","4위 목줄이나 입마개 미착용","5위 물림"],"numbered":false,"title":"반려동물로 이웃 간에 갈등이 생긴 주요 원인 — 교과서 47쪽"}},{"stem":"교과서 47쪽 표에서 반려동물로 이웃 간에 갈등이 생긴 원인 가운데 1위는 무엇인가요?","options":[{"t":"소음(짖음, 발소리)","correct":true},{"t":"배설물","mis":"SO3-2-u1-X05"},{"t":"냄새","mis":"SO3-2-u1-X05"},{"t":"물림","mis":"SO3-2-u1-X05"}],"explanation":["표의 순위를 봐요.","가장 많은 원인이에요.","1위는 소음이에요."],"asset":{"type":"passage","lines":["1위 소음(짖음, 발소리)","2위 배설물","3위 냄새","4위 목줄이나 입마개 미착용","5위 물림"],"numbered":false,"title":"반려동물로 이웃 간에 갈등이 생긴 주요 원인 — 교과서 47쪽"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_basic#9','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',2,'ox','auto','혼자 사는 사람들은 건강이나 안전, 경제적 문제가 생겼을 때 주변에 도움을 청할 사람이 없어 어려움을 겪기도 해요.',ARRAY['SO3-2-u1-X26']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"ox","stem":"혼자 사는 사람들은 건강이나 안전, 경제적 문제가 생겼을 때 주변에 도움을 청할 사람이 없어 어려움을 겪기도 해요.","answer":"O","reason_options":[{"t":"교과서 47쪽에서 1인 가구가 겪는 어려움으로 든 내용이기 때문에","correct":true},{"t":"혼자 살면 어려움이 하나도 없기 때문에","mis":"SO3-2-u1-X26"}],"mis":"SO3-2-u1-X26","explanation":["혼자 살면 외로울 때가 있어요.","아플 때 돌봐 줄 사람이 없어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_basic#10','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',3,'error','auto','편견과 차별에 대해 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X27','SO3-2-u1-X30']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"error","stem":"편견과 차별에 대해 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 다 — 「우리말을 잘하지 못하는 외국인을 무시하는 것은 생각일 뿐이라 차별이 아니야.」","correct":true,"mis_target":"SO3-2-u1-X27"},{"t":"친구 가 — 「종교적인 이유로 고기를 먹지 않는 것을 비난하면 안 돼.」","mis":"SO3-2-u1-X30"},{"t":"친구 나 — 「편견은 한쪽으로 치우친 생각이야.」","mis":"SO3-2-u1-X27"}],"explanation":["무시하는 것은 행동이에요.","다르게 대우했어요.","친구 다가 바르지 않게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_challenge#1','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',2,'sa','auto','신문 기사에서 1인 가구가 늘어나면서 새롭게 나오고 있는 작은 가전제품 가운데 하나를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"sa","stem":"신문 기사에서 1인 가구가 늘어나면서 새롭게 나오고 있는 작은 가전제품 가운데 하나를 쓰세요.","answer":["세탁기","냉장고","식기세척기"],"explanation":["기사 세 번째 줄을 봐요.","크기가 작은 제품이에요.","세탁기, 냉장고, 식기세척기예요."],"asset":{"type":"passage","lines":["2020년 기준 우리나라에서 가장 많은 가구 형태는 1인 가구이다.","1인 가구는 비교적 작은 집에 사는 경우가 많다.","크기가 작은 세탁기, 냉장고, 식기세척기 등이 새롭게 나오고 있다.","상점에서도 적은 양을 포장한 상품이 많아지고 있다."],"numbered":false,"title":"1인 가구 증가로 생활 모습이 달라진다 — 교과서 44쪽 신문 기사"},"mis":"SO3-2-u1-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_challenge#2','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',2,'ox','auto','반려동물을 버리면 버려진 동물이 길거리를 돌아다니며 사람들에게 피해를 주거나 제때 돌봄을 받지 못해 목숨을 잃기도 해요.',ARRAY['SO3-2-u1-X26']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"ox","stem":"반려동물을 버리면 버려진 동물이 길거리를 돌아다니며 사람들에게 피해를 주거나 제때 돌봄을 받지 못해 목숨을 잃기도 해요.","answer":"O","reason_options":[{"t":"버려지는 동물이 생기는 것도 반려동물이 늘며 나타난 문제이기 때문에","correct":true},{"t":"버려진 동물은 스스로 잘 살아가기 때문에","mis":"SO3-2-u1-X26"}],"mis":"SO3-2-u1-X26","explanation":["교과서 47쪽 물음이에요.","버려진 동물이 피해를 입어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_challenge#3','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',3,'mc','auto','교과서 43쪽 자료에서 외국인 이주민이 학생들에게 주는 긍정적 영향으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X26','SO3-2-u1-X28']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"mc","stem":"교과서 43쪽 자료에서 외국인 이주민이 학생들에게 주는 긍정적 영향으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"자신이 태어나고 자란 나라의 문화를 학생들에게 생생하게 알려 줘요","correct":true},{"t":"학생들이 다른 나라 문화를 배울 기회가 줄어들어요","mis":"SO3-2-u1-X26"},{"t":"학생들에게 우리나라 문화만 가르쳐요","mis":"SO3-2-u1-X28"},{"t":"학생들과 만날 기회가 전혀 없어요","mis":"SO3-2-u1-X26"}],"explanation":["교육 프로그램에 참여해요.","자기 나라 문화를 소개해요.","생생하게 알려 줘요."],"asset":{"type":"passage","lines":["한국인과 결혼해 우리나라에 살게 된 외국인 이주민들이 있어요.","이들은 중국, 베트남, 러시아, 볼리비아 등 세계 곳곳에서 왔어요.","이들 가운데 초중고교생에게 세계 여러 나라의 문화를 소개하는","교육 프로그램에 참여하는 사람들이 있어요.","자신이 태어나고 자란 나라의 문화를 학생들에게 생생하게 알려 줘요."],"title":"외국인 이주민이 증가하면서 나타난 모습 — 교과서 43쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_challenge#4','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',3,'mc','auto','교과서 46쪽 첫 번째 그림 같은 상황이 생기는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X27','SO3-2-u1-X30','SO3-2-u1-X26']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"mc","stem":"교과서 46쪽 첫 번째 그림 같은 상황이 생기는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"다른 종교를 가진 사람의 행동을 이해하지 않고 존중하지도 않기 때문이에요","correct":true},{"t":"종교적인 이유로 음식을 먹지 않는 것은 문화가 아니기 때문이에요","mis":"SO3-2-u1-X27"},{"t":"내 생각이 무조건 옳기 때문이에요","mis":"SO3-2-u1-X30"},{"t":"고기를 먹지 않는 사람은 우리 사회에 없기 때문이에요","mis":"SO3-2-u1-X26"}],"explanation":["종교적인 가르침이에요.","그 문화를 이해하지 않았어요.","존중하지 않아서 생긴 상황이에요."],"asset":{"type":"passage","lines":["① 종교적인 이유로 고기를 먹지 않는 것을 비난해요.","　「고기를 먹지 않는 것은 옳지 않아.」","② 우리말을 잘하지 못해서 무시해요.","　「아휴, 답답해. 우리말을 너무 못하네.」","③ 자신과 피부색이 다른 사람을 이상한 눈빛으로 쳐다보거나 거리를 둬요.","　「다른 자리에 앉아야지.」"],"numbered":false,"title":"교과서 46쪽 그림 속 세 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_challenge#5','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',3,'mc','auto','신문 기사 속 김○○ 씨와 건축·인테리어 업체가 반려동물과 관련해 얻는 좋은 점을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u1-X28','SO3-2-u1-X26']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"mc","stem":"신문 기사 속 김○○ 씨와 건축·인테리어 업체가 반려동물과 관련해 얻는 좋은 점을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"김○○ 씨 — 외로움을 잊고 반려동물에게 가족처럼 의지해요 · 업체 — 반려동물을 위한 제품을 만들어 팔 수 있어요","correct":true},{"t":"김○○ 씨 — 이웃과 소음 갈등이 생겨요 · 업체 — 손해만 봐요","mis":"SO3-2-u1-X28"},{"t":"김○○ 씨 — 더 외로워져요 · 업체 — 반려동물 제품을 만들지 않아요","mis":"SO3-2-u1-X26"},{"t":"두 경우 모두 좋은 점이 없어요","mis":"SO3-2-u1-X26"}],"explanation":["김○○ 씨는 외로웠어요.","업체는 제품을 내놓아요.","둘 다 좋은 점을 얻어요."],"asset":{"type":"passage","lines":["30대 직장인 김○○ 씨는 혼자 살기 외로워 강아지를 입양했어요.","강아지는 김○○ 씨가 가장 가까이에서 의지하는 가족과 다름없어요.","건축·인테리어 업계에서도 반려동물을 위한 제품을 속속 내놓고 있어요."],"numbered":false,"title":"반려동물과 함께 사는 김○○ 씨 — 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_challenge#6','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',3,'error','auto','다양한 문화의 확산이 미친 영향을 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X26','SO3-2-u1-X28']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"error","stem":"다양한 문화의 확산이 미친 영향을 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 가 — 「반려동물로 이웃 간 갈등이 생기니 반려동물 문화는 없어져야 해.」","correct":true,"mis_target":"SO3-2-u1-X26"},{"t":"친구 나 — 「1인 가구를 위해 장보기나 청소를 대신 해 주는 활동도 생겼어.」","mis":"SO3-2-u1-X28"},{"t":"친구 다 — 「누리고 선택할 수 있는 문화가 많아져 생활이 풍요로워졌어.」","mis":"SO3-2-u1-X26"}],"explanation":["좋은 점과 문제가 함께 있어요.","문제는 함께 풀어 가요.","친구 가가 바르지 않게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_challenge#7','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',3,'ox','auto','자신과 피부색이 다른 사람을 이상한 눈빛으로 쳐다보거나 거리를 두는 것은 편견이 행동으로 나타난 차별이에요.',ARRAY['SO3-2-u1-X27']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"ox","stem":"자신과 피부색이 다른 사람을 이상한 눈빛으로 쳐다보거나 거리를 두는 것은 편견이 행동으로 나타난 차별이에요.","answer":"O","reason_options":[{"t":"치우친 생각을 가지고 그 사람을 다르게 대우했기 때문에","correct":true},{"t":"쳐다보기만 했으니 아무 문제가 없기 때문에","mis":"SO3-2-u1-X27"}],"mis":"SO3-2-u1-X27","explanation":["거리를 두었어요.","다르게 대우했어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_challenge#8','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',4,'mc','auto','신문 기사 속 동네가 활기를 띠게 된 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X25','SO3-2-u1-X28','SO3-2-u1-X36']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C9","difficulty":4,"kind":"mc","stem":"신문 기사 속 동네가 활기를 띠게 된 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"외국인들이 고향 음식점을 열면서 세계 음식 문화 거리가 만들어져 관광객이 찾게 되었기 때문이에요","correct":true},{"t":"외국인들이 모두 동네를 떠났기 때문이에요","mis":"SO3-2-u1-X25"},{"t":"외국인 이주민에 대한 차별이 심해졌기 때문이에요","mis":"SO3-2-u1-X28"},{"t":"동네에 한 나라의 음식점만 남았기 때문이에요","mis":"SO3-2-u1-X36"}],"explanation":["젊은 외국인들이 살기 시작했어요.","세계 음식 문화 거리가 생겼어요.","관광객이 찾아와요."],"asset":{"type":"passage","lines":["조용한 동네에 젊은 외국인들이 살기 시작했어요.","고향 음식을 그리워하는 외국인들이 식당을 만들면서","자연스럽게 세계 음식 문화 거리가 만들어졌어요.","주말이면 관광객들의 발길도 이어져요."],"title":"활기를 띠게 된 동네 — 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_challenge#9','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',4,'mc','auto','교과서 43~47쪽 내용을 종합해 다양한 문화의 확산이 가져온 변화를 정리한 것으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X26','SO3-2-u1-X28']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C9","difficulty":4,"kind":"mc","stem":"교과서 43~47쪽 내용을 종합해 다양한 문화의 확산이 가져온 변화를 정리한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"관련 활동과 직업이 발달하고 누릴 문화가 많아졌지만, 편견과 차별, 1인 가구의 건강·안전 문제, 반려동물 갈등도 생겼어요","correct":true},{"t":"좋은 점만 생기고 문제는 생기지 않았어요","mis":"SO3-2-u1-X26"},{"t":"문제만 생겨 다양한 문화는 없어지는 것이 좋아요","mis":"SO3-2-u1-X26"},{"t":"외국인 이주민에게만 영향을 주었어요","mis":"SO3-2-u1-X28"}],"explanation":["긍정적 효과가 있어요.","문제도 있어요.","두 면을 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L09_challenge#10','soc',3,2,'u1','L09','tb_g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',4,'essay','teacher','교과서 47쪽 표와 내 경험을 떠올려, 반려동물로 이웃 간에 갈등이 생기는 원인 두 가지를 쓰고 갈등을 줄이려면 반려동물과 함께 사는 사람이 어떻게 하면 좋을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C9","difficulty":4,"kind":"essay","stem":"교과서 47쪽 표와 내 경험을 떠올려, 반려동물로 이웃 간에 갈등이 생기는 원인 두 가지를 쓰고 갈등을 줄이려면 반려동물과 함께 사는 사람이 어떻게 하면 좋을지 쓰세요.","answer_guide":{"answer":"예: 갈등 원인 1위는 짖는 소리와 발소리 같은 소음이고, 2위는 배설물이에요. 반려동물이 늦은 밤에 짖지 않도록 돌보고, 산책할 때 배설물을 바로 치워야 해요.","scoring_points":["표에서 원인 두 가지를 찾았는가","원인에 맞는 방법을 썼는가","이웃을 배려하는 마음이 드러나는가"]},"explanation":["표의 순위를 봐요.","원인에 맞는 방법을 찾아요.","이웃을 배려해요."],"asset":{"type":"passage","lines":["1위 소음(짖음, 발소리)","2위 배설물","3위 냄새","4위 목줄이나 입마개 미착용","5위 물림"],"numbered":false,"title":"반려동물로 이웃 간에 갈등이 생긴 주요 원인 — 교과서 47쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_basic#1','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',1,'mc','auto','만화 영화 이야기에서 미나가 모자를 쓰고 다니는 까닭을 고르세요.',ARRAY['SO3-2-u1-X30']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C10","difficulty":1,"kind":"mc","stem":"만화 영화 이야기에서 미나가 모자를 쓰고 다니는 까닭을 고르세요.","options":[{"t":"다른 사람들이 자신의 피부색을 이상하게 여긴다고 생각해서","correct":true},{"t":"햇볕이 강한 지역에 살아서","mis":"SO3-2-u1-X30"},{"t":"모자를 쓰는 것이 학교 규칙이라서","mis":"SO3-2-u1-X30"},{"t":"미술 시간에 그림을 그리려고","mis":"SO3-2-u1-X30"}],"explanation":["미나의 생각을 찾아요.","피부색을 이상하게 볼까 걱정해요.","그래서 모자를 써요."],"asset":{"type":"passage","lines":["부모님이 외국인 이주민인 미나는 피부색이 검어요.","미나는 다른 사람들이 자신의 피부색을 이상하게 여긴다고 생각해요.","그래서 미나는 집 밖에 나갈 때면 항상 모자를 써요.","어느 날 미술 시간에 한 친구가 모자를 벗은 미나의 모습을 그렸어요.","부끄러움을 느낀 미나는 교실 밖으로 뛰쳐나갔어요."],"title":"만화 영화 속 이야기 — 교과서 48쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_basic#2','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',1,'sa','auto','편견과 차별을 막을 수 있는 제도를 만들고 관련 기관을 운영하는 곳은 어디인가요? 교과서 51쪽에서 찾아 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C10","difficulty":1,"kind":"sa","stem":"편견과 차별을 막을 수 있는 제도를 만들고 관련 기관을 운영하는 곳은 어디인가요? 교과서 51쪽에서 찾아 쓰세요.","answer":["국가 인권 위원회","국가인권위원회"],"explanation":["51쪽 여섯 번째 그림이에요.","사람의 권리를 지켜요.","국가 인권 위원회예요."],"mis":"SO3-2-u1-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_basic#3','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',1,'ox','auto','다양한 문화가 확산되면서 나타나는 문제를 해결하려면 다른 문화보다 우리 문화를 더 소중하게 생각해야 해요.',ARRAY['SO3-2-u1-X31']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C10","difficulty":1,"kind":"ox","stem":"다양한 문화가 확산되면서 나타나는 문제를 해결하려면 다른 문화보다 우리 문화를 더 소중하게 생각해야 해요.","answer":"X","reason_options":[{"t":"내가 누리는 문화가 소중하듯 다른 사람이 누리는 문화도 소중하기 때문에","correct":true},{"t":"우리 문화가 다른 문화보다 더 훌륭하기 때문에","mis":"SO3-2-u1-X31"}],"mis":"SO3-2-u1-X31","explanation":["모든 문화가 소중해요.","서로 다름을 인정해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_basic#4','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',1,'mc','auto','교과서 50~51쪽 그림 ② 반려견과 산책할 수 있는 공원에 알맞은 붙임딱지는 무엇인가요?',ARRAY['SO3-2-u1-X29']::text[],true,'{"seq":4,"concept":"SO3-2-u1-C10","difficulty":1,"kind":"mc","stem":"교과서 50~51쪽 그림 ② 반려견과 산책할 수 있는 공원에 알맞은 붙임딱지는 무엇인가요?","options":[{"t":"반려견과 산책할 때는 입마개를 착용시키고 목줄을 채워요","correct":true},{"t":"한국어에 서툰 외국인을 위해 원활한 의사소통을 지원해요","mis":"SO3-2-u1-X29"},{"t":"학교에서 다양한 문화를 이해하는 교육을 실시해요","mis":"SO3-2-u1-X29"},{"t":"1인 가구를 위한 다양한 프로그램을 운영해요","mis":"SO3-2-u1-X29"}],"explanation":["공원에서 반려견과 산책해요.","이웃을 배려해야 해요.","입마개와 목줄이에요."],"variant_rule":{"alt":[{"stem":"교과서 50~51쪽 그림 ① 학교 건물 안에 알맞은 붙임딱지는 무엇인가요?","options":[{"t":"학교에서 다양한 문화를 이해하는 교육을 실시해요","correct":true},{"t":"반려견과 산책할 때는 입마개를 착용시키고 목줄을 채워요","mis":"SO3-2-u1-X29"},{"t":"한국어에 서툰 외국인을 위해 원활한 의사소통을 지원해요","mis":"SO3-2-u1-X29"},{"t":"1인 가구를 위한 다양한 프로그램을 운영해요","mis":"SO3-2-u1-X29"}],"explanation":["장소가 학교예요.","학생들이 배워요.","다양한 문화를 이해하는 교육이에요."]},{"stem":"교과서 50~51쪽 그림 ④ 시청 건물 안에 알맞은 붙임딱지는 무엇인가요?","options":[{"t":"한국어에 서툰 외국인을 위해 원활한 의사소통을 지원해요","correct":true},{"t":"반려견과 산책할 때는 입마개를 착용시키고 목줄을 채워요","mis":"SO3-2-u1-X29"},{"t":"학교에서 다양한 문화를 이해하는 교육을 실시해요","mis":"SO3-2-u1-X29"},{"t":"1인 가구를 위한 다양한 프로그램을 운영해요","mis":"SO3-2-u1-X29"}],"explanation":["장소가 시청이에요.","말이 서툰 사람을 도와요.","의사소통을 지원해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_basic#5','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',2,'mc','auto','미나와 같은 반 친구라면 미나를 위해 할 수 있는 일로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X30']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"mc","stem":"미나와 같은 반 친구라면 미나를 위해 할 수 있는 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"모자를 벗은 모습도 전혀 이상하지 않다고 말해 줘요","correct":true},{"t":"모자 벗은 그림을 교실에 크게 붙여요","mis":"SO3-2-u1-X30"},{"t":"미나와 이야기하지 않아요","mis":"SO3-2-u1-X30"},{"t":"피부색 이야기를 계속 꺼내 놀려요","mis":"SO3-2-u1-X30"}],"explanation":["미나의 마음을 생각해요.","부끄러움을 느꼈어요.","이상하지 않다고 말해 줘요."],"asset":{"type":"passage","lines":["부모님이 외국인 이주민인 미나는 피부색이 검어요.","미나는 다른 사람들이 자신의 피부색을 이상하게 여긴다고 생각해요.","그래서 미나는 집 밖에 나갈 때면 항상 모자를 써요.","어느 날 미술 시간에 한 친구가 모자를 벗은 미나의 모습을 그렸어요.","부끄러움을 느낀 미나는 교실 밖으로 뛰쳐나갔어요."],"title":"만화 영화 속 이야기 — 교과서 48쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_basic#6','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',2,'match','auto','교과서 50~51쪽 노력과 그 노력으로 예방하거나 해결할 수 있는 문제를 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"match","stem":"교과서 50~51쪽 노력과 그 노력으로 예방하거나 해결할 수 있는 문제를 이으세요.","pairs":[{"l":"② 입마개와 목줄","r":"반려견으로 인한 물림 사고"},{"l":"④ 의사소통 지원","r":"한국어에 서툰 외국인이 생활에 필요한 도움을 받기 어려운 문제"},{"l":"⑤ 혼자 사는 사람 지원","r":"혼자 사는 사람의 건강과 안전 문제"},{"l":"⑦ 버려진 반려동물 돌봄","r":"버려지는 동물 문제"}],"mis":"SO3-2-u1-X29","explanation":["물림 사고를 막아요.","말이 서툰 외국인을 도와요.","혼자 사는 사람과 버려진 동물을 돌봐요."],"asset":{"type":"passage","lines":["① 학교에서 다양한 문화를 이해하는 교육을 실시해요.","② 반려견과 산책할 때는 입마개를 착용시키고 목줄을 채워요.","④ 한국어에 서툰 외국인을 위해 원활한 의사소통을 지원해요.","⑤ 혼자 사는 사람들이 안전하고 편안한 환경에서 살 수 있도록 지원해요.","⑥ 편견과 차별을 막을 수 있는 제도를 만들고 관련 기관을 운영해요.","⑦ 버려진 반려동물을 돌봐 주고 새로운 주인을 만나게 해 줘요.","⑧ 세계 여러 나라의 문화를 이해하고 체험할 수 있는 행사를 열어요.","⑨ 1인 가구를 위한 다양한 프로그램을 운영해요."],"numbered":false,"title":"다양한 문화의 확산에 따른 문제를 해결하려는 노력 — 교과서 50~51쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_basic#7','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',2,'blank','auto','다양한 문화를 대할 때는 서로 다름을 인정하고 (    )하는 태도가 필요해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X31','SO3-2-u1-X30']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"blank","stem":"다양한 문화를 대할 때는 서로 다름을 인정하고 (    )하는 태도가 필요해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"존중","correct":true},{"t":"무시","mis":"SO3-2-u1-X31"},{"t":"경계","mis":"SO3-2-u1-X30"},{"t":"비난","mis":"SO3-2-u1-X30"}],"explanation":["교과서 51쪽 본문이에요.","서로 다름을 인정해요.","존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_basic#8','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',2,'mc','auto','다양한 문화를 대하는 바람직하지 못한 태도의 사례로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X31']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"mc","stem":"다양한 문화를 대하는 바람직하지 못한 태도의 사례로 알맞은 것은 무엇인가요?","options":[{"t":"반려동물을 가족이라고 생각하는 사람들을 비난해요","correct":true},{"t":"나와 다른 문화를 가진 사람들의 어려움에 관심을 가져요","mis":"SO3-2-u1-X31"},{"t":"다른 문화를 올바르게 이해하려고 노력해요","mis":"SO3-2-u1-X31"},{"t":"다른 문화에 대한 편견을 갖지 않아요","mis":"SO3-2-u1-X31"}],"explanation":["바람직하지 못한 태도를 찾아요.","비난하는 것은 존중이 아니에요.","비난하는 태도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_basic#9','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',2,'ox','auto','유니버설 디자인은 나이, 성별, 국적, 언어, 장애, 문화 등과 관계없이 누구나 사용하기 쉽도록 물건이나 시설 등을 디자인하는 것이에요.',ARRAY['SO3-2-u1-X29']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"ox","stem":"유니버설 디자인은 나이, 성별, 국적, 언어, 장애, 문화 등과 관계없이 누구나 사용하기 쉽도록 물건이나 시설 등을 디자인하는 것이에요.","answer":"O","reason_options":[{"t":"교과서 52쪽에서 모두를 위한 디자인이라고 했기 때문에","correct":true},{"t":"특별한 사람만 쓸 수 있게 만든 디자인이기 때문에","mis":"SO3-2-u1-X29"}],"mis":"SO3-2-u1-X29","explanation":["교과서 52쪽이에요.","누구나 쓰기 쉬워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_basic#10','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',3,'error','auto','우리 반 실천 약속을 정하며 친구들이 낸 의견 가운데 약속으로 알맞지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X30','SO3-2-u1-X31']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"error","stem":"우리 반 실천 약속을 정하며 친구들이 낸 의견 가운데 약속으로 알맞지 않은 것을 고르세요.","options":[{"t":"친구 나 — 「우리 문화와 다른 친구는 모둠에 넣지 말자.」","correct":true,"mis_target":"SO3-2-u1-X30"},{"t":"친구 가 — 「다른 문화에 대한 편견을 갖지 않고 차별하지 말자.」","mis":"SO3-2-u1-X30"},{"t":"친구 다 — 「다른 문화의 사람들이 겪는 어려움에 관심을 갖자.」","mis":"SO3-2-u1-X31"}],"explanation":["실천 약속은 존중하는 약속이에요.","모둠에서 빼는 것은 차별이에요.","친구 나의 의견이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_challenge#1','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',2,'sa','auto','교과서 52쪽에서 장애 어린이와 비장애 어린이가 함께 놀 수 있는 시설을 갖춘 놀이터를 무엇이라고 하나요?','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"sa","stem":"교과서 52쪽에서 장애 어린이와 비장애 어린이가 함께 놀 수 있는 시설을 갖춘 놀이터를 무엇이라고 하나요?","answer":["무장애 놀이터","무장애놀이터"],"explanation":["유니버설 디자인이에요.","장애가 있어도 함께 놀아요.","무장애 놀이터예요."],"asset":{"type":"passage","lines":["유니버설 디자인 — 나이, 성별, 국적, 언어, 장애, 문화 등과 관계없이","　누구나 사용하기 쉽도록 물건이나 시설 등을 디자인하는 것","① 어린이, 임산부, 노인, 장애인 등이 편리한 지하철이나 버스 내부 시설","② 앞이 보이지 않는 사람이나 우리글을 모르는 외국인도 쓰기 쉬운 승강기 버튼","③ 장애 어린이와 비장애 어린이가 함께 놀 수 있는 무장애 놀이터"],"numbered":false,"title":"별별 직업 속으로 — 유니버설 디자이너(교과서 52쪽)"},"mis":"SO3-2-u1-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_challenge#2','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',2,'ox','auto','「한국에서 사니까 좋지요?」라는 말에는 외국인이 살던 나라보다 대한민국이 더 낫다는 생각이 깔려 있을 수 있어요.',ARRAY['SO3-2-u1-X34']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"ox","stem":"「한국에서 사니까 좋지요?」라는 말에는 외국인이 살던 나라보다 대한민국이 더 낫다는 생각이 깔려 있을 수 있어요.","answer":"O","reason_options":[{"t":"이 말을 듣는 사람은 자신의 나라가 무시당한다는 느낌을 받을 수도 있기 때문에","correct":true},{"t":"인사말은 어떻게 해도 상대의 기분과 관계없기 때문에","mis":"SO3-2-u1-X34"}],"mis":"SO3-2-u1-X34","explanation":["듣는 사람의 마음을 생각해요.","자기 나라가 무시당한다고 느낄 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_challenge#3','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',3,'mc','auto','「아기도 아니고 강아지를 안고 다니나요?」를 편견과 차별이 없는 표현으로 고친 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X34']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"mc","stem":"「아기도 아니고 강아지를 안고 다니나요?」를 편견과 차별이 없는 표현으로 고친 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「강아지가 편안하게 안겨 있네요.」","correct":true},{"t":"「강아지는 걸어 다녀야지요.」","mis":"SO3-2-u1-X34"},{"t":"「강아지를 왜 그렇게 아끼세요?」","mis":"SO3-2-u1-X34"},{"t":"「아기처럼 안고 다니면 이상해요.」","mis":"SO3-2-u1-X34"}],"explanation":["반려동물을 가족처럼 생각하는 사람이 많아요.","존중하는 말로 바꿔요.","편안하게 안겨 있다고 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_challenge#4','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',3,'mc','auto','교과서 49쪽 활동에서 우리 반 실천 약속을 정하는 차례로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X29']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"mc","stem":"교과서 49쪽 활동에서 우리 반 실천 약속을 정하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"태도의 사례 쓰기 → 모둠에서 필요한 태도 정리하기 → 다른 모둠과 비교해 우리 반 약속 정하기","correct":true},{"t":"우리 반 약속 정하기 → 태도의 사례 쓰기 → 모둠에서 필요한 태도 정리하기","mis":"SO3-2-u1-X29"},{"t":"모둠에서 필요한 태도 정리하기 → 우리 반 약속 정하기 → 태도의 사례 쓰기","mis":"SO3-2-u1-X29"},{"t":"태도의 사례 쓰기 → 우리 반 약속 정하기 → 모둠에서 필요한 태도 정리하기","mis":"SO3-2-u1-X29"}],"explanation":["먼저 혼자 사례를 써요.","모둠에서 정리해요.","반 전체 약속을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_challenge#5','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',3,'mc','auto','국가 인권 위원회가 하는 일로 우리가 얻을 수 있는 도움은 무엇인가요?',ARRAY['SO3-2-u1-X29']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"mc","stem":"국가 인권 위원회가 하는 일로 우리가 얻을 수 있는 도움은 무엇인가요?","options":[{"t":"억울하게 차별을 당했을 때 도움을 요청할 수 있어요","correct":true},{"t":"버려진 반려동물을 데려올 수 있어요","mis":"SO3-2-u1-X29"},{"t":"1인 가구 요리 프로그램에 참여할 수 있어요","mis":"SO3-2-u1-X29"},{"t":"세계 여러 나라 문화를 체험할 수 있어요","mis":"SO3-2-u1-X29"}],"explanation":["편견과 차별을 막는 기관이에요.","억울한 차별이 있을 때예요.","도움을 요청할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_challenge#6','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',3,'error','auto','유니버설 디자인이 적용된 물건이나 시설을 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X29']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"error","stem":"유니버설 디자인이 적용된 물건이나 시설을 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 다 — 「점자를 넣은 승강기 버튼은 앞이 보이는 사람만 쓰라고 만든 거야.」","correct":true,"mis_target":"SO3-2-u1-X29"},{"t":"친구 가 — 「무장애 놀이터에서는 장애 어린이와 비장애 어린이가 함께 놀 수 있어.」","mis":"SO3-2-u1-X29"},{"t":"친구 나 — 「어린이, 임산부, 노인, 장애인 등이 편리하게 쓰는 버스 내부 시설도 있어.」","mis":"SO3-2-u1-X29"}],"explanation":["누구나 쓰기 쉽게 만들어요.","앞이 보이지 않는 사람도 써요.","친구 다가 바르지 않게 말했어요."],"asset":{"type":"passage","lines":["유니버설 디자인 — 나이, 성별, 국적, 언어, 장애, 문화 등과 관계없이","　누구나 사용하기 쉽도록 물건이나 시설 등을 디자인하는 것","① 어린이, 임산부, 노인, 장애인 등이 편리한 지하철이나 버스 내부 시설","② 앞이 보이지 않는 사람이나 우리글을 모르는 외국인도 쓰기 쉬운 승강기 버튼","③ 장애 어린이와 비장애 어린이가 함께 놀 수 있는 무장애 놀이터"],"numbered":false,"title":"별별 직업 속으로 — 유니버설 디자이너(교과서 52쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_challenge#7','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',3,'ox','auto','버려진 반려동물을 돌봐 주고 새로운 주인을 만나게 해 주는 일은 다양한 문화의 확산으로 나타난 문제를 해결하려는 노력이에요.',ARRAY['SO3-2-u1-X29']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"ox","stem":"버려진 반려동물을 돌봐 주고 새로운 주인을 만나게 해 주는 일은 다양한 문화의 확산으로 나타난 문제를 해결하려는 노력이에요.","answer":"O","reason_options":[{"t":"반려동물이 늘며 생긴 버려지는 동물 문제를 해결하는 일이기 때문에","correct":true},{"t":"버려진 반려동물은 우리 사회의 문제가 아니기 때문에","mis":"SO3-2-u1-X29"}],"mis":"SO3-2-u1-X29","explanation":["교과서 51쪽 일곱 번째 그림이에요.","버려진 동물을 돌봐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_challenge#8','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',4,'mc','auto','검은 옷 나라를 더 살기 좋은 곳으로 만드는 방안으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X30','SO3-2-u1-X31']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C10","difficulty":4,"kind":"mc","stem":"검은 옷 나라를 더 살기 좋은 곳으로 만드는 방안으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"이웃 나라처럼 여름에는 소매가 짧고 얇은 옷을 입는 것을 받아들여요","correct":true},{"t":"이웃 나라 사람들의 옷을 이상하다고 놀려요","mis":"SO3-2-u1-X30"},{"t":"일 년 내내 검은 옷만 입도록 더 엄격하게 정해요","mis":"SO3-2-u1-X31"},{"t":"이웃 나라 사람들이 다시는 오지 못하게 해요","mis":"SO3-2-u1-X31"}],"explanation":["여름에 너무 더웠어요.","이웃 나라는 얇은 옷을 입었어요.","좋은 점을 받아들여요."],"asset":{"type":"passage","lines":["옛날 검은 옷 나라 사람들은 일 년 내내 소매가 길고 두꺼운","검은 옷만 입었어요. 겨울에는 견딜 만했지만 여름에는 너무 더웠어요.","어느 해 여름, 비가 많이 내려 먹을 것이 다 떠내려갔어요.","이웃 나라 사람들이 먹을 것을 팔러 왔는데,","짧은 소매의 얇은 옷을 입고 있어 검은 옷 나라 사람들이 깜짝 놀랐어요."],"title":"검은 옷 나라 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_challenge#9','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',4,'mc','auto','검은 옷 나라 이야기가 전하려는 생각으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X31','SO3-2-u1-X17','SO3-2-u1-X21']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C10","difficulty":4,"kind":"mc","stem":"검은 옷 나라 이야기가 전하려는 생각으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"자신의 것만 고집하기보다 다른 문화의 좋은 점을 배우면 사회가 발전할 수 있어요","correct":true},{"t":"한 가지 문화만 지키는 사회가 가장 살기 좋아요","mis":"SO3-2-u1-X31"},{"t":"다른 나라의 문화는 무조건 따라야 해요","mis":"SO3-2-u1-X17"},{"t":"옷차림은 문화와 관계없어요","mis":"SO3-2-u1-X21"}],"explanation":["검은 옷만 고집했어요.","이웃 나라에서 배울 점이 있었어요.","다양한 문화가 사회를 발전시켜요."],"asset":{"type":"passage","lines":["옛날 검은 옷 나라 사람들은 일 년 내내 소매가 길고 두꺼운","검은 옷만 입었어요. 겨울에는 견딜 만했지만 여름에는 너무 더웠어요.","어느 해 여름, 비가 많이 내려 먹을 것이 다 떠내려갔어요.","이웃 나라 사람들이 먹을 것을 팔러 왔는데,","짧은 소매의 얇은 옷을 입고 있어 검은 옷 나라 사람들이 깜짝 놀랐어요."],"title":"검은 옷 나라 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L10_challenge#10','soc',3,2,'u1','L10','tb_g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',4,'essay','teacher','미나 이야기를 떠올려, 다양한 문화가 존중받는 사회를 만들기 위해 우리 반이 지킬 실천 약속 두 가지를 쓰고, 우리 사회가 하는 노력 한 가지를 교과서 50~51쪽에서 골라 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C10","difficulty":4,"kind":"essay","stem":"미나 이야기를 떠올려, 다양한 문화가 존중받는 사회를 만들기 위해 우리 반이 지킬 실천 약속 두 가지를 쓰고, 우리 사회가 하는 노력 한 가지를 교과서 50~51쪽에서 골라 쓰세요.","answer_guide":{"answer":"예: 약속 1 — 다른 문화에 대한 편견을 갖지 않고 차별하지 않아요. 약속 2 — 다른 문화의 사람들이 겪는 어려움에 관심을 갖고 먼저 다가가요. 우리 사회는 국가 인권 위원회를 운영해 편견과 차별을 막는 제도를 만들어요.","scoring_points":["실천 약속 두 가지를 썼는가","약속이 다양한 문화를 존중하는 내용인가","교과서 50~51쪽 노력을 하나 썼는가"]},"explanation":["미나의 어려움을 떠올려요.","우리 반이 지킬 약속을 써요.","사회의 노력도 써요."],"asset":{"type":"passage","lines":["부모님이 외국인 이주민인 미나는 피부색이 검어요.","미나는 다른 사람들이 자신의 피부색을 이상하게 여긴다고 생각해요.","그래서 미나는 집 밖에 나갈 때면 항상 모자를 써요.","어느 날 미술 시간에 한 친구가 모자를 벗은 미나의 모습을 그렸어요.","부끄러움을 느낀 미나는 교실 밖으로 뛰쳐나갔어요."],"title":"만화 영화 속 이야기 — 교과서 48쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_basic#1','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',1,'mc','auto','「배가 고파서 음식을 먹는 행동은 문화입니다.」라는 설명에 대한 판단으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X20','SO3-2-u1-X21']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C11","difficulty":1,"kind":"mc","stem":"「배가 고파서 음식을 먹는 행동은 문화입니다.」라는 설명에 대한 판단으로 알맞은 것은 무엇인가요?","options":[{"t":"태어날 때부터 하게 되는 행동이므로 옳지 않은 설명이에요","correct":true},{"t":"사람이 하는 행동은 모두 문화이므로 옳은 설명이에요","mis":"SO3-2-u1-X20"},{"t":"음식을 먹으니 의식주 문화이므로 옳은 설명이에요","mis":"SO3-2-u1-X21"},{"t":"옳은지 그른지 알 수 없어요","mis":"SO3-2-u1-X20"}],"explanation":["버스 찾기 첫 번째 설명이에요.","태어날 때부터 하는 행동이에요.","문화가 아니라 옳지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_basic#2','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',1,'sa','auto','교과서 54쪽 초대장 만드는 차례에서 가장 먼저 할 일은 무엇인가요? 「축제 ○○ 정하기」의 ○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C11","difficulty":1,"kind":"sa","stem":"교과서 54쪽 초대장 만드는 차례에서 가장 먼저 할 일은 무엇인가요? 「축제 ○○ 정하기」의 ○○에 알맞은 말을 쓰세요.","answer":["주제"],"explanation":["54쪽 첫 번째 차례예요.","무엇에 관한 축제인지 정해요.","주제예요."],"mis":"SO3-2-u1-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_basic#3','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',1,'ox','auto','교과서 53쪽 시 짓기 활동에서는 우리 사회의 다양한 문화의 모습이나 다양한 문화를 대하는 바람직한 태도를 담아 시를 지어요.',ARRAY['SO3-2-u1-X32']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C11","difficulty":1,"kind":"ox","stem":"교과서 53쪽 시 짓기 활동에서는 우리 사회의 다양한 문화의 모습이나 다양한 문화를 대하는 바람직한 태도를 담아 시를 지어요.","answer":"O","reason_options":[{"t":"교과서 53쪽 선택 활동 1에서 그렇게 하라고 했기 때문에","correct":true},{"t":"시에는 공부와 관계없는 내용만 써야 하기 때문에","mis":"SO3-2-u1-X32"}],"mis":"SO3-2-u1-X32","explanation":["53쪽 선택 활동 1이에요.","다양한 문화나 바람직한 태도를 담아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_basic#4','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',1,'mc','auto','교과서 54쪽에서 축제 초대장의 주제로 고를 수 있게 제시한 것이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u1-X32']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C11","difficulty":1,"kind":"mc","stem":"교과서 54쪽에서 축제 초대장의 주제로 고를 수 있게 제시한 것이 아닌 것은 무엇인가요?","options":[{"t":"지능정보화 축제","correct":true},{"t":"외국인 이주민 축제","mis":"SO3-2-u1-X32"},{"t":"1인 가구 축제","mis":"SO3-2-u1-X32"},{"t":"반려동물 축제","mis":"SO3-2-u1-X32"}],"explanation":["주제 세 가지를 떠올려요.","우리 사회의 다양한 문화예요.","지능정보화는 1주제에서 공부했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_basic#5','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',2,'mc','auto','교과서 53쪽 예시 시 「손가락」이 「길고 짧은 손가락」, 「서로 다른 얼굴빛」을 노래하며 전하려는 생각으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X31','SO3-2-u1-X30']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"mc","stem":"교과서 53쪽 예시 시 「손가락」이 「길고 짧은 손가락」, 「서로 다른 얼굴빛」을 노래하며 전하려는 생각으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"서로 다르지만 모두 함께 어울려 사는 소중한 한 가족이라는 생각","correct":true},{"t":"키가 다르면 함께 지낼 수 없다는 생각","mis":"SO3-2-u1-X31"},{"t":"얼굴빛이 다른 사람은 다른 자리에 앉아야 한다는 생각","mis":"SO3-2-u1-X30"},{"t":"손가락은 모두 똑같아야 한다는 생각","mis":"SO3-2-u1-X31"}],"explanation":["손가락은 길이가 달라요.","얼굴빛도 서로 달라요.","그래도 함께 어울려 사는 가족이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_basic#6','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',2,'match','auto','1인 가구 축제 초대장 예시의 프로그램과 열리는 장소를 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"match","stem":"1인 가구 축제 초대장 예시의 프로그램과 열리는 장소를 이으세요.","pairs":[{"l":"1인 가구 음식 만들기","r":"3-1 교실"},{"l":"1인 가구를 위한 주택 모형 관람하기","r":"체육관"},{"l":"1인 가구 여가 생활 체험하기","r":"운동장"}],"mis":"SO3-2-u1-X32","explanation":["프로그램 안내 표를 봐요.","음식 만들기는 교실이에요.","주택 모형은 체육관, 여가 생활은 운동장이에요."],"asset":{"type":"passage","lines":["3학년 1반은 우리 사회의 1인 가구 문화를 알리고자 축제를 준비했어요.","1인 가구 음식 만들기 — 3-1 교실","1인 가구 인기 생활용품 체험하기 — 3-1 교실","1인 가구를 위한 주택 모형 관람하기 — 체육관","1인 가구 건강 체크하기 — 운동장","1인 가구 여가 생활 체험하기 — 운동장","쿠폰: 음료수 1잔(운동장) · 다트 게임 1회(여가 생활 코너)","쿠폰: 행운권 추첨 참가권(3-1 교실)"],"numbered":false,"title":"초대장 예시 — 교과서 54쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_basic#7','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',2,'blank','auto','축제 프로그램의 내용과 장소 등을 정한 다음에는 (    )을 써서 초대장을 완성해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X32']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"blank","stem":"축제 프로그램의 내용과 장소 등을 정한 다음에는 (    )을 써서 초대장을 완성해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"초청하는 글","correct":true},{"t":"축제 주제","mis":"SO3-2-u1-X32"},{"t":"프로그램 목록","mis":"SO3-2-u1-X32"},{"t":"시의 제목","mis":"SO3-2-u1-X32"}],"explanation":["54쪽 세 번째 차례예요.","사람들을 부르는 글이에요.","초청하는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_basic#8','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',2,'mc','auto','교과서 55쪽 설명 가운데 옳지 않은 설명 두 개를 바르게 고른 것은 무엇인가요?',ARRAY['SO3-2-u1-X20','SO3-2-u1-X26']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"mc","stem":"교과서 55쪽 설명 가운데 옳지 않은 설명 두 개를 바르게 고른 것은 무엇인가요?","options":[{"t":"1번과 4번","correct":true},{"t":"2번과 3번","mis":"SO3-2-u1-X20"},{"t":"5번과 6번","mis":"SO3-2-u1-X26"},{"t":"1번과 6번","mis":"SO3-2-u1-X26"}],"explanation":["1번은 태어날 때부터 하는 행동이에요.","4번은 1인 가구가 늘고 있어요.","1번과 4번이 옳지 않아요."],"asset":{"type":"passage","lines":["1 배가 고파서 음식을 먹는 행동은 문화예요.","2 문화는 사람들이 함께 생활하면서 만들어지고 오랫동안 전해져 내려오기도 해요.","3 세계화의 영향으로 우리나라에서 사는 외국인 이주민이 늘어났어요.","4 결혼에 관한 생각 변화, 고령화 등의 영향으로 1인 가구가 줄어들고 있어요.","5 반려동물과 함께 사는 사람이 많아지면서 관련 문화가 널리 퍼지고 있어요.","6 다양한 문화가 확산되면서 낯선 문화에 대한 편견과 차별이 생기기도 해요."],"numbered":false,"title":"재미있게 확인해요 — 버스 찾기 설명(교과서 55쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_basic#9','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',2,'ox','auto','「다양한 문화가 확산되면서 낯선 문화에 대한 편견과 차별이 생기기도 합니다.」는 옳은 설명이에요.',ARRAY['SO3-2-u1-X26']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"ox","stem":"「다양한 문화가 확산되면서 낯선 문화에 대한 편견과 차별이 생기기도 합니다.」는 옳은 설명이에요.","answer":"O","reason_options":[{"t":"다양한 문화가 퍼지며 좋은 점과 함께 편견과 차별 같은 문제도 생기기 때문에","correct":true},{"t":"다양한 문화가 퍼지면 좋은 점만 생기기 때문에","mis":"SO3-2-u1-X26"}],"mis":"SO3-2-u1-X26","explanation":["버스 찾기 6번 설명이에요.","문제도 함께 생겨요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_basic#10','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',3,'error','auto','1인 가구 축제 초대장을 만들며 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X32']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C11","difficulty":3,"kind":"error","stem":"1인 가구 축제 초대장을 만들며 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 가 — 「초청하는 글을 먼저 쓰고, 축제 주제는 맨 나중에 정하자.」","correct":true,"mis_target":"SO3-2-u1-X32"},{"t":"친구 나 — 「프로그램마다 열리는 장소를 정해서 표로 정리하자.」","mis":"SO3-2-u1-X32"},{"t":"친구 다 — 「1인 가구의 문화를 알 수 있는 프로그램을 계획하자.」","mis":"SO3-2-u1-X32"}],"explanation":["차례가 있어요.","주제가 맨 먼저예요.","친구 가가 바르지 않게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_challenge#1','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',2,'sa','auto','교과서 55쪽 「재미있게 확인해요」에서 올바른 설명의 힌트를 모두 따라가면 타야 하는 버스는 어디로 가는 버스인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"sa","stem":"교과서 55쪽 「재미있게 확인해요」에서 올바른 설명의 힌트를 모두 따라가면 타야 하는 버스는 어디로 가는 버스인가요? 두 글자로 쓰세요.","answer":["청주"],"explanation":["설명마다 O, X를 정해요.","힌트로 버스를 하나씩 지워요.","청주로 가는 버스예요."],"mis":"SO3-2-u1-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_challenge#2','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',2,'ox','auto','교과서 55쪽의 설명 「결혼에 관한 생각 변화, 고령화로 혼자 사는 노인 증가 등의 영향으로 1인 가구가 줄어들고 있습니다.」는 옳은 설명이에요.',ARRAY['SO3-2-u1-X25']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"ox","stem":"교과서 55쪽의 설명 「결혼에 관한 생각 변화, 고령화로 혼자 사는 노인 증가 등의 영향으로 1인 가구가 줄어들고 있습니다.」는 옳은 설명이에요.","answer":"X","reason_options":[{"t":"1인 가구는 줄어들지 않고 늘어나고 있기 때문에","correct":true},{"t":"혼자 사는 노인이 늘면 1인 가구는 줄기 때문에","mis":"SO3-2-u1-X25"}],"mis":"SO3-2-u1-X25","explanation":["1인 가구의 변화를 떠올려요.","늘어나고 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_challenge#3','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',3,'mc','auto','반려동물 축제 프로그램 계획으로 가장 알맞지 않은 것은 무엇인가요?',ARRAY['SO3-2-u1-X32']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C11","difficulty":3,"kind":"mc","stem":"반려동물 축제 프로그램 계획으로 가장 알맞지 않은 것은 무엇인가요?","options":[{"t":"1인 가구를 위한 주택 모형 관람하기","correct":true},{"t":"나의 반려동물 소개하기","mis":"SO3-2-u1-X32"},{"t":"반려동물 예절 배우기","mis":"SO3-2-u1-X32"},{"t":"반려동물을 그림으로 나타내기","mis":"SO3-2-u1-X32"}],"explanation":["반려동물 축제예요.","반려동물과 관계있어야 해요.","주택 모형은 1인 가구 축제 프로그램이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_challenge#4','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',3,'mc','auto','교과서 53쪽 예시 시 「함께여서 좋습니다」에 담긴 다양한 문화의 모습으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X36','SO3-2-u1-X30']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C11","difficulty":3,"kind":"mc","stem":"교과서 53쪽 예시 시 「함께여서 좋습니다」에 담긴 다양한 문화의 모습으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"여러 나라에서 온 이웃들이 우리 명절인 설날을 함께 보내요","correct":true},{"t":"한 나라 사람끼리만 설날을 보내요","mis":"SO3-2-u1-X36"},{"t":"낯선 음식을 먹지 않겠다고 다투어요","mis":"SO3-2-u1-X30"},{"t":"외국인 이웃을 명절에 초대하지 않아요","mis":"SO3-2-u1-X30"}],"explanation":["네팔, 방글라데시, 캄보디아에서 온 이웃이에요.","함께 떡국을 준비해요.","설날을 함께 보내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_challenge#5','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',3,'mc','auto','초대장 예시의 쿠폰 가운데 음료수 1잔 쿠폰과 행운권 추첨 참가권을 쓰는 장소를 차례대로 바르게 쓴 것은 무엇인가요?',ARRAY['SO3-2-u1-X32']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C11","difficulty":3,"kind":"mc","stem":"초대장 예시의 쿠폰 가운데 음료수 1잔 쿠폰과 행운권 추첨 참가권을 쓰는 장소를 차례대로 바르게 쓴 것은 무엇인가요?","options":[{"t":"운동장 — 3-1 교실","correct":true},{"t":"3-1 교실 — 운동장","mis":"SO3-2-u1-X32"},{"t":"체육관 — 여가 생활 코너","mis":"SO3-2-u1-X32"},{"t":"여가 생활 코너 — 체육관","mis":"SO3-2-u1-X32"}],"explanation":["쿠폰 칸을 봐요.","음료수는 운동장이에요.","행운권은 3-1 교실이에요."],"asset":{"type":"passage","lines":["3학년 1반은 우리 사회의 1인 가구 문화를 알리고자 축제를 준비했어요.","1인 가구 음식 만들기 — 3-1 교실","1인 가구 인기 생활용품 체험하기 — 3-1 교실","1인 가구를 위한 주택 모형 관람하기 — 체육관","1인 가구 건강 체크하기 — 운동장","1인 가구 여가 생활 체험하기 — 운동장","쿠폰: 음료수 1잔(운동장) · 다트 게임 1회(여가 생활 코너)","쿠폰: 행운권 추첨 참가권(3-1 교실)"],"numbered":false,"title":"초대장 예시 — 교과서 54쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_challenge#6','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',3,'error','auto','교과서 55쪽 설명의 O, X를 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X25','SO3-2-u1-X20']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C11","difficulty":3,"kind":"error","stem":"교과서 55쪽 설명의 O, X를 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 나 — 「3번은 외국인 이주민이 줄었다는 뜻이라 X야.」","correct":true,"mis_target":"SO3-2-u1-X25"},{"t":"친구 가 — 「1번은 태어날 때부터 하는 행동이라 X야.」","mis":"SO3-2-u1-X20"},{"t":"친구 다 — 「2번은 문화의 특성을 바르게 말해서 O야.」","mis":"SO3-2-u1-X20"}],"explanation":["3번을 다시 읽어요.","외국인 이주민이 늘어났어요.","친구 나가 바르지 않게 말했어요."],"asset":{"type":"passage","lines":["1 배가 고파서 음식을 먹는 행동은 문화예요.","2 문화는 사람들이 함께 생활하면서 만들어지고 오랫동안 전해져 내려오기도 해요.","3 세계화의 영향으로 우리나라에서 사는 외국인 이주민이 늘어났어요.","4 결혼에 관한 생각 변화, 고령화 등의 영향으로 1인 가구가 줄어들고 있어요.","5 반려동물과 함께 사는 사람이 많아지면서 관련 문화가 널리 퍼지고 있어요.","6 다양한 문화가 확산되면서 낯선 문화에 대한 편견과 차별이 생기기도 해요."],"numbered":false,"title":"재미있게 확인해요 — 버스 찾기 설명(교과서 55쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_challenge#7','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',3,'ox','auto','초대장의 프로그램은 참여하는 사람이 이해하기 쉽고 그 문화의 특성이 잘 드러나도록 구성해야 해요.',ARRAY['SO3-2-u1-X32']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C11","difficulty":3,"kind":"ox","stem":"초대장의 프로그램은 참여하는 사람이 이해하기 쉽고 그 문화의 특성이 잘 드러나도록 구성해야 해요.","answer":"O","reason_options":[{"t":"사람들이 축제에 와서 그 문화를 알아보고 즐겁게 참여해야 하기 때문에","correct":true},{"t":"문화와 관계없이 재미만 있으면 되기 때문에","mis":"SO3-2-u1-X32"}],"mis":"SO3-2-u1-X32","explanation":["축제의 목적을 떠올려요.","문화를 알리는 축제예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_challenge#8','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',4,'mc','auto','「다양한 문화에 대한 이해와 존중」 주제를 정리한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X20','SO3-2-u1-X36','SO3-2-u1-X31']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C11","difficulty":4,"kind":"mc","stem":"「다양한 문화에 대한 이해와 존중」 주제를 정리한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"문화는 한 사회의 공통의 생활 양식이고, 다양한 문화가 확산되며 좋은 점과 문제가 함께 나타나므로 서로 다름을 인정하고 존중해야 해요","correct":true},{"t":"사람이 하는 행동은 모두 문화이고 문제는 생기지 않아요","mis":"SO3-2-u1-X20"},{"t":"우리 사회에는 하나의 문화만 있어요","mis":"SO3-2-u1-X36"},{"t":"우리 문화만 소중히 여기면 돼요","mis":"SO3-2-u1-X31"}],"explanation":["문화의 뜻이에요.","좋은 점과 문제가 함께 있어요.","서로 다름을 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_challenge#9','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',4,'mc','auto','3학년 1반이 1인 가구 축제를 준비한 까닭을 초대장 글에서 찾은 것으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X30','SO3-2-u1-X31','SO3-2-u1-X32']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C11","difficulty":4,"kind":"mc","stem":"3학년 1반이 1인 가구 축제를 준비한 까닭을 초대장 글에서 찾은 것으로 알맞은 것은 무엇인가요?","options":[{"t":"우리 사회의 1인 가구 문화를 알리고, 사람들이 그 문화를 알아보며 즐거운 시간을 보내게 하려고","correct":true},{"t":"1인 가구를 놀리려고","mis":"SO3-2-u1-X30"},{"t":"한 가지 문화만 남기려고","mis":"SO3-2-u1-X31"},{"t":"축제는 문화와 관계없이 열려서","mis":"SO3-2-u1-X32"}],"explanation":["초대장 첫 줄을 봐요.","1인 가구 문화를 알리고자 해요.","함께 즐기며 알아보게 해요."],"asset":{"type":"passage","lines":["3학년 1반은 우리 사회의 1인 가구 문화를 알리고자 축제를 준비했어요.","1인 가구 음식 만들기 — 3-1 교실","1인 가구 인기 생활용품 체험하기 — 3-1 교실","1인 가구를 위한 주택 모형 관람하기 — 체육관","1인 가구 건강 체크하기 — 운동장","1인 가구 여가 생활 체험하기 — 운동장","쿠폰: 음료수 1잔(운동장) · 다트 게임 1회(여가 생활 코너)","쿠폰: 행운권 추첨 참가권(3-1 교실)"],"numbered":false,"title":"초대장 예시 — 교과서 54쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_L11_challenge#10','soc',3,2,'u1','L11','tb_g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',4,'essay','teacher','외국인 이주민 축제, 1인 가구 축제, 반려동물 축제 가운데 하나를 골라 초대장에 넣을 프로그램 두 가지와 장소를 정하고, 초청하는 글을 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C11","difficulty":4,"kind":"essay","stem":"외국인 이주민 축제, 1인 가구 축제, 반려동물 축제 가운데 하나를 골라 초대장에 넣을 프로그램 두 가지와 장소를 정하고, 초청하는 글을 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 반려동물 축제 — 나의 반려동물 소개하기(체육관), 반려동물 예절 배우기(체육관). 우리 반은 반려동물과 함께 사는 이웃의 문화를 알리고자 축제를 준비했습니다. 축제에 오셔서 반려동물 문화를 알아보고 즐거운 시간을 보내시기 바랍니다.","scoring_points":["축제 주제를 하나 골랐는가","주제에 어울리는 프로그램 두 가지와 장소를 정했는가","초청하는 글을 두 문장으로 썼는가"]},"explanation":["주제를 골라요.","프로그램과 장소를 정해요.","초청하는 글을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#1','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C2',1,'mc','auto','그래프를 보고 알 수 있는 내용으로 알맞은 것은 어느 것인가요?',ARRAY['SO3-2-u1-X06','SO3-2-u1-X09','SO3-2-u1-X18','SO3-2-u1-X25']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C2","difficulty":1,"kind":"mc","stem":"그래프를 보고 알 수 있는 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리나라의 저출산이 심해지고 있어요","correct":true},{"t":"초등학교의 수가 늘어나고 있어요","mis":"SO3-2-u1-X06"},{"t":"사람들의 평균 수명이 줄어들고 있어요","mis":"SO3-2-u1-X09"},{"t":"다른 나라와의 교류가 활발해지고 있어요","mis":"SO3-2-u1-X18"},{"t":"우리나라를 찾는 외국인의 수가 줄어들고 있어요","mis":"SO3-2-u1-X25"}],"explanation":["태어나는 아이의 수가 점점 줄어요.","아이를 적게 낳는 사람이 많아졌어요.","저출산이 심해지고 있어요."],"asset":{"type":"passage","lines":["1970년 — 101만 명 · 1980년 — 86만 명","1990년 — 65만 명 · 2000년 — 64만 명","2010년 — 47만 명 · 2020년 — 27만 명","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"numbered":false,"title":"우리나라에서 연도별 태어나는 아이의 수 — 교과서 15쪽 그래프"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#2','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C3',1,'mc','auto','고령화로 나타난 생활 모습의 변화로 알맞은 것은 어느 것인가요?',ARRAY['SO3-2-u1-X06','SO3-2-u1-X10','SO3-2-u1-X08','SO3-2-u1-X18']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C3","difficulty":1,"kind":"mc","stem":"고령화로 나타난 생활 모습의 변화로 알맞은 것은 어느 것인가요?","options":[{"t":"노인을 위한 여러 교육 프로그램을 운영해요","correct":true},{"t":"출산을 도와주는 병원의 수가 늘어나요","mis":"SO3-2-u1-X06"},{"t":"노인의 건강을 관리하는 비용이 줄어들어요","mis":"SO3-2-u1-X10"},{"t":"전체 사람 수 중에서 노인의 수가 줄어들어요","mis":"SO3-2-u1-X08"},{"t":"세계 여러 나라의 음식을 파는 상점이 많아져요","mis":"SO3-2-u1-X18"}],"explanation":["노인이 많아졌어요.","노인을 위한 시설과 프로그램이 늘어요.","교육 프로그램을 운영해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#3','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C4',1,'sa','auto','두 친구의 대화에서 빈칸에 공통으로 들어갈 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"sa","stem":"두 친구의 대화에서 빈칸에 공통으로 들어갈 알맞은 말을 쓰세요.","answer":["인공지능"],"explanation":["사람처럼 정보를 익혀요.","수준과 흥미에 맞는 공부를 도와요.","인공지능이에요."],"asset":{"type":"speech","turns":[{"who":"승주","text":"(    )은/는 사람처럼 정보를 익히고 처리하여 다양한 상황에 적용할 수 있는 기능을 갖춘 컴퓨터 시스템이래."},{"who":"지한","text":"그래서 (    )을/를 활용해 자신의 수준과 흥미에 맞는 공부를 할 수 있구나."}]},"mis":"SO3-2-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#4','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C4',1,'mc','auto','「인터넷에서 이미지나 동영상 파일에 담긴 이름, 집 주소, 전화번호 등이 노출되어 피해가 발생할 수 있으므로 주의해야 합니다.」 이 문제의 대응 방안으로 적절한 것은 어느 것인가요?',ARRAY['SO3-2-u1-X12','SO3-2-u1-X18','SO3-2-u1-X14']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"mc","stem":"「인터넷에서 이미지나 동영상 파일에 담긴 이름, 집 주소, 전화번호 등이 노출되어 피해가 발생할 수 있으므로 주의해야 합니다.」 이 문제의 대응 방안으로 적절한 것은 어느 것인가요?","options":[{"t":"사이버 범죄를 예방하려고 노력해요","correct":true},{"t":"농작물의 상태를 실시간으로 관찰해요","mis":"SO3-2-u1-X12"},{"t":"새로운 일자리를 준비하는 교육을 해요","mis":"SO3-2-u1-X12"},{"t":"안전하고 쾌적한 보육 시설을 운영해요","mis":"SO3-2-u1-X18"},{"t":"스마트폰 사용 시간을 늘리도록 노력해요","mis":"SO3-2-u1-X14"}],"explanation":["개인 정보가 노출되는 문제예요.","범죄에 이용될 수 있어요.","사이버 범죄를 예방해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#5','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C5',1,'sa','auto','「세계 여러 나라가 다양한 분야에서 교류하면서 전 세계가 하나로 연결되는 현상을 (    )(이)라고 합니다.」 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u1-C5","difficulty":1,"kind":"sa","stem":"「세계 여러 나라가 다양한 분야에서 교류하면서 전 세계가 하나로 연결되는 현상을 (    )(이)라고 합니다.」 빈칸에 알맞은 말을 쓰세요.","answer":["세계화"],"explanation":["교과서 27쪽 본문이에요.","세계가 하나로 연결돼요.","세계화예요."],"mis":"SO3-2-u1-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#6','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C7',1,'mc','auto','「이것」에 해당하는 것은 어느 것인가요? 「이것은 한 사회의 사람들이 지닌 공통의 생활 양식입니다. 이것에는 의식주뿐만 아니라 말과 글, 종교, 규범 등이 있습니다.」',ARRAY['SO3-2-u1-X21']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C7","difficulty":1,"kind":"mc","stem":"「이것」에 해당하는 것은 어느 것인가요? 「이것은 한 사회의 사람들이 지닌 공통의 생활 양식입니다. 이것에는 의식주뿐만 아니라 말과 글, 종교, 규범 등이 있습니다.」","options":[{"t":"문화","correct":true},{"t":"국가","mis":"SO3-2-u1-X21"},{"t":"역사","mis":"SO3-2-u1-X21"},{"t":"지역","mis":"SO3-2-u1-X21"},{"t":"음악","mis":"SO3-2-u1-X21"}],"explanation":["공통의 생활 양식이에요.","의식주, 말과 글, 종교, 규범이 있어요.","문화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#7','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C9',1,'mc','auto','우리 사회에 외국인 이주민이 증가하면서 나타난 긍정적 영향을 보기에서 골라 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO3-2-u1-X28']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C9","difficulty":1,"kind":"mc","stem":"우리 사회에 외국인 이주민이 증가하면서 나타난 긍정적 영향을 보기에서 골라 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"㉡, ㉣","correct":true},{"t":"㉠, ㉡","mis":"SO3-2-u1-X28"},{"t":"㉠, ㉢","mis":"SO3-2-u1-X28"},{"t":"㉡, ㉢","mis":"SO3-2-u1-X28"},{"t":"㉢, ㉣","mis":"SO3-2-u1-X28"}],"explanation":["긍정적 영향을 골라요.","무시와 차별은 문제예요.","㉡과 ㉣이에요."],"asset":{"type":"passage","lines":["㉠ 우리말을 잘하지 못하는 외국인을 무시해요.","㉡ 외국인 이주민이 우리 사회의 여러 분야에서 활동해요.","㉢ 외국인 이주민이 모여 사는 지역에 대한 차별이 심해져요.","㉣ 세계 여러 나라의 문화를 접할 수 있는 기회가 늘어났어요."],"numbered":false,"title":"보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#8','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C8',1,'mc','auto','빈칸에 공통으로 들어갈 알맞은 말은 어느 것인가요? 「부모나 자녀, 형제 등과 같이 살지 않고 혼자 사는 경우를 (    )(이)라고 합니다. (    )이/가 늘어나면서 크기가 작은 가전제품과 적은 양을 포장한 상품이 인기를 끌고 있습니다.」',ARRAY['SO3-2-u1-X24']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C8","difficulty":1,"kind":"mc","stem":"빈칸에 공통으로 들어갈 알맞은 말은 어느 것인가요? 「부모나 자녀, 형제 등과 같이 살지 않고 혼자 사는 경우를 (    )(이)라고 합니다. (    )이/가 늘어나면서 크기가 작은 가전제품과 적은 양을 포장한 상품이 인기를 끌고 있습니다.」","options":[{"t":"1인 가구","correct":true},{"t":"노인","mis":"SO3-2-u1-X24"},{"t":"어린이","mis":"SO3-2-u1-X24"},{"t":"초등학생","mis":"SO3-2-u1-X24"},{"t":"외국인 이주민","mis":"SO3-2-u1-X24"}],"explanation":["혼자 사는 경우예요.","작은 가전제품이 인기예요.","1인 가구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#9','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C9',2,'mc','auto','「고기를 먹지 않는 것은 옳지 않아.」라고 말하며 종교적인 이유로 고기를 먹지 않는 것을 비난하는 상황에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO3-2-u1-X27','SO3-2-u1-X30','SO3-2-u1-X28']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"mc","stem":"「고기를 먹지 않는 것은 옳지 않아.」라고 말하며 종교적인 이유로 고기를 먹지 않는 것을 비난하는 상황에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"다른 문화에 대한 편견을 갖고 있어요","correct":true},{"t":"공공장소에서 질서를 지키지 않아요","mis":"SO3-2-u1-X27"},{"t":"자신과 피부색이 다른 사람을 배려해요","mis":"SO3-2-u1-X30"},{"t":"혼자 사는 사람에 대한 관심이 부족해요","mis":"SO3-2-u1-X28"},{"t":"1인 가구와 관련 있는 문화가 확산되었어요","mis":"SO3-2-u1-X28"}],"explanation":["종교적인 가르침이에요.","그 문화를 치우쳐 보았어요.","편견을 갖고 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#10','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C10',2,'essay','teacher','「반려동물과 함께 사는 사람이 많아지면서 이웃 간에 갈등이 생기고 있습니다. 특히 반려견으로 인한 물림 사고가 끊이지 않고 있습니다.」 이 문제를 해결하기 위한 방안을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"essay","stem":"「반려동물과 함께 사는 사람이 많아지면서 이웃 간에 갈등이 생기고 있습니다. 특히 반려견으로 인한 물림 사고가 끊이지 않고 있습니다.」 이 문제를 해결하기 위한 방안을 한 가지 쓰세요.","answer_guide":{"answer":"예: 반려견과 산책할 때는 반려견에게 입마개를 착용시키고 목줄을 채워요.","scoring_points":["물림 사고와 관계있는 방안인가","반려견과 함께 사는 사람이 지킬 점으로 썼는가","이웃을 배려하는 마음이 드러나는가"]},"explanation":["물림 사고를 막아야 해요.","교과서 50쪽 그림 ②를 떠올려요.","입마개와 목줄이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#11','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C5',2,'mc','auto','세계화로 나타난 일상생활 모습으로 알맞은 것을 고르세요.',ARRAY['SO3-2-u1-X15']::text[],false,'{"seq":11,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"mc","stem":"세계화로 나타난 일상생활 모습으로 알맞은 것을 고르세요.","options":[{"t":"다른 나라에서 온 식품이나 물건을 구입할 수 있어요","correct":true},{"t":"먼 나라 소식을 전혀 알 수 없어요","mis":"SO3-2-u1-X15"},{"t":"물건은 우리나라 안에서만 주고받아요","mis":"SO3-2-u1-X15"},{"t":"다른 나라 사람과 함께하는 행사는 없어요","mis":"SO3-2-u1-X15"}],"explanation":["세계 여러 나라가 교류해요.","물건이 오가요.","다른 나라 식품을 살 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#12','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C2',2,'blank','auto','생각 그물에서 저출산 가지의 해결 노력에는 양육비 지원과 (    ) 운영이 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X07']::text[],false,'{"seq":12,"concept":"SO3-2-u1-C2","difficulty":2,"kind":"blank","stem":"생각 그물에서 저출산 가지의 해결 노력에는 양육비 지원과 (    ) 운영이 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"보육 시설","correct":true},{"t":"노인 복지관","mis":"SO3-2-u1-X07"},{"t":"사이버 범죄 신고","mis":"SO3-2-u1-X07"},{"t":"세종 학당","mis":"SO3-2-u1-X07"}],"explanation":["교과서 56쪽 생각 그물이에요.","아이를 맡길 곳이에요.","보육 시설이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#13','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C9',2,'blank','auto','생각 그물에서 다양한 문화의 확산으로 나타난 문제에는 낯선 문화에 대한 편견과 (    ), 1인 가구의 건강과 안전 문제, 반려동물로 이웃 간에 생기는 갈등이 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X27']::text[],false,'{"seq":13,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"blank","stem":"생각 그물에서 다양한 문화의 확산으로 나타난 문제에는 낯선 문화에 대한 편견과 (    ), 1인 가구의 건강과 안전 문제, 반려동물로 이웃 간에 생기는 갈등이 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"차별","correct":true},{"t":"존중","mis":"SO3-2-u1-X27"},{"t":"배려","mis":"SO3-2-u1-X27"},{"t":"교류","mis":"SO3-2-u1-X27"}],"explanation":["교과서 57쪽 생각 그물이에요.","편견과 짝을 이뤄요.","차별이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#14','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C7',2,'mc','auto','에스파냐의 한 지역에서 8월에 열리는 축제는 무엇인가요?',ARRAY['SO3-2-u1-X22']::text[],false,'{"seq":14,"concept":"SO3-2-u1-C7","difficulty":2,"kind":"mc","stem":"에스파냐의 한 지역에서 8월에 열리는 축제는 무엇인가요?","options":[{"t":"서로 토마토를 마구 던지는 축제","correct":true},{"t":"원숭이에게 과일과 채소를 주는 축제","mis":"SO3-2-u1-X22"},{"t":"모형 참치를 멀리 던지는 축제","mis":"SO3-2-u1-X22"},{"t":"함께 떡국을 나누는 축제","mis":"SO3-2-u1-X22"}],"explanation":["교과서 37쪽을 떠올려요.","8월에 열려요.","토마토 축제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#15','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C11',2,'mc','auto','딩고 놀이에서 이기는 사람은 누구인가요?',ARRAY['SO3-2-u1-X32']::text[],false,'{"seq":15,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"mc","stem":"딩고 놀이에서 이기는 사람은 누구인가요?","options":[{"t":"카드 4장을 한 주제로 모아 「딩고!」라고 먼저 외친 사람","correct":true},{"t":"카드를 가장 많이 버린 사람","mis":"SO3-2-u1-X32"},{"t":"진행자","mis":"SO3-2-u1-X32"},{"t":"카드를 가장 늦게 집은 사람","mis":"SO3-2-u1-X32"}],"explanation":["놀이 방법 마지막 줄이에요.","카드 4장을 한 주제로 모아요.","먼저 외친 사람이 이겨요."],"asset":{"type":"passage","lines":["3~4명이 한 모둠이 되고, 모둠에서 한 명을 진행자로 정해요.","딩고 카드를 섞어 각자 4장씩 나눠 갖고, 남은 카드는 뒤집어 펼쳐 놓아요.","진행자가 「버려!」를 외치면 필요 없는 카드 1장을 책상 가운데에 뒤집어 놓아요.","진행자가 「집어!」를 외치면 책상에 놓인 카드 중 1장을 집어 가져가요.","카드 4장을 한 주제로 모아 「딩고!」라고 먼저 외친 사람이 이겨요."],"numbered":false,"title":"교실 놀이를 함께해요 — 딩고 놀이(교과서 58~59쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#16','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C8',2,'mc','auto','교과서 8~9쪽 「가방 주인 찾기」에서 가방 주인은 누구인가요?',ARRAY['SO3-2-u1-X24']::text[],false,'{"seq":16,"concept":"SO3-2-u1-C8","difficulty":2,"kind":"mc","stem":"교과서 8~9쪽 「가방 주인 찾기」에서 가방 주인은 누구인가요?","options":[{"t":"102호 사람","correct":true},{"t":"101호 사람","mis":"SO3-2-u1-X24"},{"t":"201호 사람","mis":"SO3-2-u1-X24"},{"t":"202호 사람","mis":"SO3-2-u1-X24"}],"explanation":["수첩에 또롱이 산책과 부모님께 안부 전화가 있어요.","강아지와 살고 부모님과 따로 살아요.","102호 사람이에요."],"asset":{"type":"passage","lines":["가방 속 — 이빨 자국이 난 곰 인형, 강아지 쿠키, 부모님 사진, 수첩","수첩 — 또롱이와 산책하기 · 부모님께 안부 전화하기 · 또롱이 인형 사기","101호 — 부모님, 아들, 강아지 초코와 함께 살아요.","102호 — 회사 때문에 부모님과 따로 살고, 강아지와 산책하려고 준비해요.","201호 — 아기가 있고, 고양이에게 밥을 줄 시간이에요.","202호 — 한국말이 서툴고, 회사 일로 가족이 모두 한국에 왔어요."],"numbered":false,"title":"가방 주인 찾기 — 교과서 8~9쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#17','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C1',3,'mc','auto','사회 변화의 원인과 그 원인으로 나타난 사회 변화를 바르게 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u1-X02']::text[],false,'{"seq":17,"concept":"SO3-2-u1-C1","difficulty":3,"kind":"mc","stem":"사회 변화의 원인과 그 원인으로 나타난 사회 변화를 바르게 짝지은 것은 무엇인가요?","options":[{"t":"평균 수명의 증가 — 고령화","correct":true},{"t":"과학 기술의 발달 — 저출산","mis":"SO3-2-u1-X02"},{"t":"다른 나라와의 교류 — 지능정보화","mis":"SO3-2-u1-X02"},{"t":"사람 수의 변화 — 세계화","mis":"SO3-2-u1-X02"}],"explanation":["오래 살게 되었어요.","노인의 비율이 높아져요.","고령화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#18','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C4',3,'mc','auto','65세 이상 인구 비율이 계속 높아질 것으로 예상되는 자료(가)와 인공지능 기술 사진(나)이 나타내는 사회 변화를 차례대로 바르게 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u1-X18']::text[],false,'{"seq":18,"concept":"SO3-2-u1-C4","difficulty":3,"kind":"mc","stem":"65세 이상 인구 비율이 계속 높아질 것으로 예상되는 자료(가)와 인공지능 기술 사진(나)이 나타내는 사회 변화를 차례대로 바르게 짝지은 것은 무엇인가요?","options":[{"t":"가 — 고령화, 나 — 지능정보화","correct":true},{"t":"가 — 저출산, 나 — 세계화","mis":"SO3-2-u1-X18"},{"t":"가 — 지능정보화, 나 — 고령화","mis":"SO3-2-u1-X18"},{"t":"가 — 세계화, 나 — 저출산","mis":"SO3-2-u1-X18"}],"explanation":["노인의 비율이 높아져요.","인공지능 기술이에요.","고령화와 지능정보화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#19','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C5',3,'mc','auto','지능정보화와 세계화에 대응하는 태도에서 비슷한 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X13','SO3-2-u1-X17','SO3-2-u1-X19']::text[],false,'{"seq":19,"concept":"SO3-2-u1-C5","difficulty":3,"kind":"mc","stem":"지능정보화와 세계화에 대응하는 태도에서 비슷한 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"좋은 점은 누리되 생기는 문제는 따져 보고 보완하려고 노력해요","correct":true},{"t":"좋은 점만 보고 문제는 생각하지 않아요","mis":"SO3-2-u1-X13"},{"t":"문제가 있으니 아예 받아들이지 않아요","mis":"SO3-2-u1-X17"},{"t":"나와 관계없으니 관심을 두지 않아요","mis":"SO3-2-u1-X19"}],"explanation":["두 변화 모두 좋은 점이 있어요.","문제도 있어요.","따져 보고 보완해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#20','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C9',3,'mc','auto','다양한 문화가 확산되며 나타난 모습을 긍정적 효과와 문제로 바르게 나눈 것은 무엇인가요?',ARRAY['SO3-2-u1-X28','SO3-2-u1-X26']::text[],false,'{"seq":20,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"mc","stem":"다양한 문화가 확산되며 나타난 모습을 긍정적 효과와 문제로 바르게 나눈 것은 무엇인가요?","options":[{"t":"긍정적 효과 — 반려동물과 관련 있는 직업 증가 · 문제 — 1인 가구의 외로움과 불안함","correct":true},{"t":"긍정적 효과 — 편견과 차별 · 문제 — 세계 여러 나라 문화 경험","mis":"SO3-2-u1-X28"},{"t":"긍정적 효과 — 이웃 간 갈등 · 문제 — 작은 가전제품 증가","mis":"SO3-2-u1-X28"},{"t":"두 가지 모두 문제예요","mis":"SO3-2-u1-X26"}],"explanation":["직업이 늘었어요.","혼자 살면 외로울 때가 있어요.","바르게 나누어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#21','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C10',3,'mc','auto','한국 생활에 적응하는 데 필요한 정보를 다양한 언어로 제공하는 노력으로 도움을 받는 사람은 누구인가요?',ARRAY['SO3-2-u1-X29']::text[],false,'{"seq":21,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"mc","stem":"한국 생활에 적응하는 데 필요한 정보를 다양한 언어로 제공하는 노력으로 도움을 받는 사람은 누구인가요?","options":[{"t":"한국어에 서툰 외국인","correct":true},{"t":"반려견과 산책하는 사람","mis":"SO3-2-u1-X29"},{"t":"혼자 사는 노인만","mis":"SO3-2-u1-X29"},{"t":"인공지능 전문가","mis":"SO3-2-u1-X29"}],"explanation":["교과서 50쪽 옆 설명이에요.","여러 언어로 알려 줘요.","한국어에 서툰 외국인이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#22','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C10',3,'mc','auto','「혼자 사는 것 보니까 능력이 부족하거나 문제가 있을 거야.」라는 말이 문제가 되는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X34','SO3-2-u1-X25']::text[],false,'{"seq":22,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"mc","stem":"「혼자 사는 것 보니까 능력이 부족하거나 문제가 있을 거야.」라는 말이 문제가 되는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"1인 가구를 바르지 않은 모습으로 여기는 편견이 담겨 듣는 사람의 삶을 인정하지 않기 때문이에요","correct":true},{"t":"혼자 사는 사람을 걱정하는 좋은 말이라 문제가 없어요","mis":"SO3-2-u1-X34"},{"t":"말은 생각일 뿐이라 상대에게 아무 영향을 주지 않아요","mis":"SO3-2-u1-X34"},{"t":"1인 가구는 실제로 줄어들고 있어서예요","mis":"SO3-2-u1-X25"}],"explanation":["듣는 사람의 마음을 생각해요.","삶을 인정받지 못한다고 느껴요.","편견이 담긴 말이에요."],"asset":{"type":"passage","lines":["⑴ 한국에 와서 사는 외국인에게 — 「한국에서 사니까 좋지요?」","⑵ 혼자 사는 사람을 두고 — 「혼자 사는 것 보니까 능력이 부족하거나 문제가 있을 거야.」","⑶ 반려동물을 안은 사람에게 — 「아기도 아니고 강아지를 안고 다니나요?」"],"title":"무심결에 하는 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#23','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C1',4,'mc','auto','「사회 변화와 다양한 문화」 단원에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u1-X01','SO3-2-u1-X19','SO3-2-u1-X26']::text[],false,'{"seq":23,"concept":"SO3-2-u1-C1","difficulty":4,"kind":"mc","stem":"「사회 변화와 다양한 문화」 단원에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"여러 원인으로 사회가 변해 생활이 달라지고, 다양한 문화가 확산되는 사회에서는 생긴 문제에 함께 대응하며 서로 다름을 존중해야 해요","correct":true},{"t":"사회는 변하지 않고 문화도 하나뿐이에요","mis":"SO3-2-u1-X01"},{"t":"사회 변화의 문제는 나라에서만 해결하면 돼요","mis":"SO3-2-u1-X19"},{"t":"다양한 문화가 퍼지면 좋은 점만 생겨요","mis":"SO3-2-u1-X26"}],"explanation":["1주제는 사회 변화예요.","2주제는 다양한 문화예요.","함께 대응하고 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#24','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C4',4,'essay','teacher','65세 이상 인구 비율이 계속 높아질 것으로 예상되는 자료를 보고, 고령화로 생길 수 있는 문제를 쓰고 그 문제를 지능정보화 기술로 해결하는 방안을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-2-u1-C4","difficulty":4,"kind":"essay","stem":"65세 이상 인구 비율이 계속 높아질 것으로 예상되는 자료를 보고, 고령화로 생길 수 있는 문제를 쓰고 그 문제를 지능정보화 기술로 해결하는 방안을 쓰세요.","answer_guide":{"answer":"예: 건강 문제로 활동하기 힘든 노인이 많아지고, 노인들의 건강을 관리하고 생활을 유지하는 비용이 늘어나요. 노인들을 위한 휴대용 건강 측정 기기를 만들어 스스로 건강을 살피게 하면 도움이 돼요.","scoring_points":["고령화로 생길 수 있는 문제를 썼는가","지능정보화 기술을 활용한 방안을 썼는가","방안이 문제와 알맞게 이어지는가"]},"explanation":["노인이 많아지면 무엇이 달라질까요?","인공지능 기술을 떠올려요.","문제와 방안을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_a#25','soc',3,2,'u1','','tb_g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C10',4,'essay','teacher','검은 옷 나라 이야기의 뒤에 이어질 내용을 「다양한 문화가 사회를 발전시킨다.」라는 생각이 담기도록 지어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-2-u1-C10","difficulty":4,"kind":"essay","stem":"검은 옷 나라 이야기의 뒤에 이어질 내용을 「다양한 문화가 사회를 발전시킨다.」라는 생각이 담기도록 지어 쓰세요.","answer_guide":{"answer":"예: 이웃 나라 사람들이 다녀간 뒤 검은 옷 나라에서는 소매를 접어 입는 사람이 나타났어요. 곧 긴소매를 잘라 짧게 입는 사람이 생겼고, 마침내 밝은색의 얇은 옷을 입고 더위를 이겨 내는 사람들이 많아졌어요. 사람들은 다른 문화에서 좋은 점을 배울 수 있다는 것을 깨달았어요.","scoring_points":["앞 이야기와 자연스럽게 이어지는가","다른 문화의 좋은 점을 받아들이는 내용이 있는가","다양한 문화가 사회를 발전시킨다는 생각이 드러나는가"]},"explanation":["검은 옷만 고집했던 까닭을 떠올려요.","이웃 나라의 좋은 점을 받아들여요.","사회가 나아지는 모습으로 이어요."],"asset":{"type":"passage","lines":["옛날 검은 옷 나라 사람들은 일 년 내내 소매가 길고 두꺼운","검은 옷만 입었어요. 겨울에는 견딜 만했지만 여름에는 너무 더웠어요.","어느 해 여름, 비가 많이 내려 먹을 것이 다 떠내려갔어요.","이웃 나라 사람들이 먹을 것을 팔러 왔는데,","짧은 소매의 얇은 옷을 입고 있어 검은 옷 나라 사람들이 깜짝 놀랐어요."],"title":"검은 옷 나라 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#1','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C2',1,'sa','auto','그래프에서 2000년에 태어난 아이의 수는 몇만 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C2","difficulty":1,"kind":"sa","stem":"그래프에서 2000년에 태어난 아이의 수는 몇만 명인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["2000년 막대를 찾아요.","단위는 만 명이에요.","64만 명이에요."],"asset":{"type":"passage","lines":["1970년 — 101만 명 · 1980년 — 86만 명","1990년 — 65만 명 · 2000년 — 64만 명","2010년 — 47만 명 · 2020년 — 27만 명","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"numbered":false,"title":"우리나라에서 연도별 태어나는 아이의 수 — 교과서 15쪽 그래프"},"mis":"SO3-2-u1-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#2','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C3',1,'sa','auto','자료에서 1980년에는 100명 가운데 몇 명 정도가 노인이었나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C3","difficulty":1,"kind":"sa","stem":"자료에서 1980년에는 100명 가운데 몇 명 정도가 노인이었나요? 숫자로 쓰세요.","answer":["4"],"explanation":["1980년 줄을 봐요.","가장 적었어요.","4명 정도예요."],"asset":{"type":"passage","lines":["1980년 — 100명 가운데 4명 정도가 노인이었어요.","2020년 — 100명 가운데 16명 정도가 노인이었어요.","2050년(예상) — 100명 가운데 40명 정도가 노인일 거예요.","(노인 — 65세 이상인 사람)"],"numbered":false,"title":"우리나라가 100명이 사는 마을이라면 — 교과서 18쪽"},"mis":"SO3-2-u1-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#3','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C4',1,'mc','auto','인공지능을 활용한 다양한 기술이 사회 전반에 폭넓은 영향을 미치는 현상은 무엇인가요?',ARRAY['SO3-2-u1-X11','SO3-2-u1-X18']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"mc","stem":"인공지능을 활용한 다양한 기술이 사회 전반에 폭넓은 영향을 미치는 현상은 무엇인가요?","options":[{"t":"지능정보화","correct":true},{"t":"정보 통신 기술","mis":"SO3-2-u1-X11"},{"t":"세계화","mis":"SO3-2-u1-X18"},{"t":"고령화","mis":"SO3-2-u1-X18"}],"explanation":["인공지능이에요.","사회 전반에 영향을 줘요.","지능정보화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#4','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C4',1,'ox','auto','인터넷에 있는 정보는 비판 없이 무조건 믿어도 돼요.',ARRAY['SO3-2-u1-X14']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"ox","stem":"인터넷에 있는 정보는 비판 없이 무조건 믿어도 돼요.","answer":"X","reason_options":[{"t":"인공지능이 만든 거짓 정보도 있어 맞는지 살펴봐야 하기 때문에","correct":true},{"t":"인터넷 정보는 모두 사실이기 때문에","mis":"SO3-2-u1-X14"}],"mis":"SO3-2-u1-X14","explanation":["가짜 뉴스도 있어요.","비판하며 살펴봐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#5','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C5',1,'mc','auto','세계화로 나타난 문제로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X17']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C5","difficulty":1,"kind":"mc","stem":"세계화로 나타난 문제로 알맞은 것은 무엇인가요?","options":[{"t":"감염병이 전 세계로 빠르게 퍼질 수 있어요","correct":true},{"t":"다른 나라 영화를 볼 수 있어요","mis":"SO3-2-u1-X17"},{"t":"세종 학당에서 한국어를 배울 수 있어요","mis":"SO3-2-u1-X17"},{"t":"지구를 위한 시간 행사에 참여할 수 있어요","mis":"SO3-2-u1-X17"}],"explanation":["문제를 찾아요.","여러 나라를 오가는 사람이 많아요.","감염병이 빠르게 퍼져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#6','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C7',1,'sa','auto','사람들이 마땅히 따르고 지켜야 할 생각이나 행동의 기준을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u1-C7","difficulty":1,"kind":"sa","stem":"사람들이 마땅히 따르고 지켜야 할 생각이나 행동의 기준을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["규범"],"explanation":["교과서 36쪽 낱말 풀이예요.","지켜야 할 기준이에요.","규범이에요."],"mis":"SO3-2-u1-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#7','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C9',1,'sa','auto','외국인 이주민이 증가하면서 세계 여러 나라의 무엇을 경험할 기회가 늘어났나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO3-2-u1-C9","difficulty":1,"kind":"sa","stem":"외국인 이주민이 증가하면서 세계 여러 나라의 무엇을 경험할 기회가 늘어났나요? 두 글자로 쓰세요.","answer":["문화"],"explanation":["교과서 43쪽 본문이에요.","여러 나라의 생활 양식이에요.","문화예요."],"mis":"SO3-2-u1-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#8','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C8',1,'sa','auto','사람과 더불어 살아가며 친밀감과 안정감을 주는 동물을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-2-u1-C8","difficulty":1,"kind":"sa","stem":"사람과 더불어 살아가며 친밀감과 안정감을 주는 동물을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["반려동물"],"explanation":["교과서 42쪽 낱말 풀이예요.","함께 살아요.","반려동물이에요."],"mis":"SO3-2-u1-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#9','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C9',2,'ox','auto','「아휴, 답답해. 우리말을 너무 못하네.」라고 하며 외국인을 무시하는 것은 차별이에요.',ARRAY['SO3-2-u1-X27']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"ox","stem":"「아휴, 답답해. 우리말을 너무 못하네.」라고 하며 외국인을 무시하는 것은 차별이에요.","answer":"O","reason_options":[{"t":"우리말을 잘하지 못한다는 까닭으로 그 사람을 다르게 대우했기 때문에","correct":true},{"t":"말로만 했으니 다르게 대우한 것이 아니기 때문에","mis":"SO3-2-u1-X27"}],"mis":"SO3-2-u1-X27","explanation":["무시했어요.","다르게 대우했어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#10','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C10',2,'mc','auto','반려견으로 인한 물림 사고를 예방할 수 있는 노력은 무엇인가요?',ARRAY['SO3-2-u1-X29','SO3-2-u1-X30']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"mc","stem":"반려견으로 인한 물림 사고를 예방할 수 있는 노력은 무엇인가요?","options":[{"t":"반려견과 산책할 때 입마개를 착용시키고 목줄을 채워요","correct":true},{"t":"반려견을 목줄 없이 뛰어놀게 해요","mis":"SO3-2-u1-X29"},{"t":"물림 사고는 저절로 줄어드니 그냥 둬요","mis":"SO3-2-u1-X29"},{"t":"반려견을 기르는 이웃을 비난해요","mis":"SO3-2-u1-X30"}],"explanation":["사고를 막는 방법이에요.","입마개와 목줄을 해요.","이웃을 배려해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#11','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C5',2,'sa','auto','자료에서 칠레에서 재배해 들여온 상품은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"sa","stem":"자료에서 칠레에서 재배해 들여온 상품은 무엇인가요? 두 글자로 쓰세요.","answer":["포도"],"explanation":["칠레를 찾아요.","재배한 과일이에요.","포도예요."],"asset":{"type":"passage","lines":["벨기에에서 만든 초콜릿 · 프랑스에서 만든 화장품","칠레에서 재배한 포도 · 미국에서 만든 청바지","독일에서 만든 프라이팬"],"title":"세계 곳곳에서 들여온 상품 — 신문 기사"},"mis":"SO3-2-u1-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#12','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C3',2,'mc','auto','생각 그물에서 고령화 가지에 들어갈 내용이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u1-X18']::text[],false,'{"seq":12,"concept":"SO3-2-u1-C3","difficulty":2,"kind":"mc","stem":"생각 그물에서 고령화 가지에 들어갈 내용이 아닌 것은 무엇인가요?","options":[{"t":"학생 수 감소","correct":true},{"t":"노인을 위한 시설 증가","mis":"SO3-2-u1-X18"},{"t":"일을 하거나 일자리를 찾는 노인 증가","mis":"SO3-2-u1-X18"},{"t":"복지 제도 운영","mis":"SO3-2-u1-X18"}],"explanation":["고령화 가지를 떠올려요.","노인과 관계있어요.","학생 수 감소는 저출산 가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#13','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C9',2,'mc','auto','생각 그물에서 다양한 문화의 확산이 가져온 긍정적 영향이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u1-X26']::text[],false,'{"seq":13,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"mc","stem":"생각 그물에서 다양한 문화의 확산이 가져온 긍정적 영향이 아닌 것은 무엇인가요?","options":[{"t":"반려동물로 이웃 간에 갈등 발생","correct":true},{"t":"다양한 나라의 문화 경험","mis":"SO3-2-u1-X26"},{"t":"1인 가구를 위한 제품이나 활동 증가","mis":"SO3-2-u1-X26"},{"t":"반려동물과 화목한 생활","mis":"SO3-2-u1-X26"}],"explanation":["긍정적 영향과 문제를 나눠요.","갈등은 문제예요.","나머지는 긍정적 영향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#14','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C7',2,'ox','auto','세계 여러 나라의 축제를 보면 각 나라의 다양한 문화를 알 수 있어요.',ARRAY['SO3-2-u1-X22']::text[],false,'{"seq":14,"concept":"SO3-2-u1-C7","difficulty":2,"kind":"ox","stem":"세계 여러 나라의 축제를 보면 각 나라의 다양한 문화를 알 수 있어요.","answer":"O","reason_options":[{"t":"축제는 한 사회의 문화를 잘 드러내기 때문에","correct":true},{"t":"축제는 문화와 아무 관계가 없기 때문에","mis":"SO3-2-u1-X22"}],"mis":"SO3-2-u1-X22","explanation":["교과서 37쪽 본문이에요.","축제는 문화를 드러내요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#15','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C11',2,'ox','auto','딩고 놀이는 3~4명이 한 모둠이 되어 모둠에서 한 명을 진행자로 정해요.',ARRAY['SO3-2-u1-X32']::text[],false,'{"seq":15,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"ox","stem":"딩고 놀이는 3~4명이 한 모둠이 되어 모둠에서 한 명을 진행자로 정해요.","answer":"O","reason_options":[{"t":"교과서 58쪽 놀이 방법에 나온 내용이기 때문에","correct":true},{"t":"진행자 없이 모두 함께 외치기 때문에","mis":"SO3-2-u1-X32"}],"mis":"SO3-2-u1-X32","explanation":["놀이 준비를 떠올려요.","진행자를 정해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#16','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C8',2,'ox','auto','「가방 주인 찾기」의 202호 사람은 회사 일로 가족이 모두 한국으로 온 외국인 가족이에요.',ARRAY['SO3-2-u1-X24']::text[],false,'{"seq":16,"concept":"SO3-2-u1-C8","difficulty":2,"kind":"ox","stem":"「가방 주인 찾기」의 202호 사람은 회사 일로 가족이 모두 한국으로 온 외국인 가족이에요.","answer":"O","reason_options":[{"t":"한국말이 서툴다고 하며 회사 일로 가족이 모두 한국에 왔다고 했기 때문에","correct":true},{"t":"202호 사람은 혼자 사는 사람이기 때문에","mis":"SO3-2-u1-X24"}],"mis":"SO3-2-u1-X24","explanation":["202호 이야기를 읽어요.","가족이 모두 한국에 왔어요.","그래서 O예요."],"asset":{"type":"passage","lines":["가방 속 — 이빨 자국이 난 곰 인형, 강아지 쿠키, 부모님 사진, 수첩","수첩 — 또롱이와 산책하기 · 부모님께 안부 전화하기 · 또롱이 인형 사기","101호 — 부모님, 아들, 강아지 초코와 함께 살아요.","102호 — 회사 때문에 부모님과 따로 살고, 강아지와 산책하려고 준비해요.","201호 — 아기가 있고, 고양이에게 밥을 줄 시간이에요.","202호 — 한국말이 서툴고, 회사 일로 가족이 모두 한국에 왔어요."],"numbered":false,"title":"가방 주인 찾기 — 교과서 8~9쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#17','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C3',3,'ox','auto','태어나는 아이의 수가 줄어드는 것도 고령화가 나타나는 까닭 가운데 하나예요.',ARRAY['SO3-2-u1-X08']::text[],false,'{"seq":17,"concept":"SO3-2-u1-C3","difficulty":3,"kind":"ox","stem":"태어나는 아이의 수가 줄어드는 것도 고령화가 나타나는 까닭 가운데 하나예요.","answer":"O","reason_options":[{"t":"아이는 줄고 사람들은 오래 살면서 전체에서 노인이 차지하는 비율이 높아지기 때문에","correct":true},{"t":"고령화는 노인의 수만 관계있기 때문에","mis":"SO3-2-u1-X08"}],"mis":"SO3-2-u1-X08","explanation":["교과서 18쪽 본문이에요.","아이는 줄고 노인은 오래 살아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#18','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C4',3,'ox','auto','노인에게 약 먹을 시간을 알려 주는 가정용 로봇은 고령화에 대비하는 노력에 지능정보화 기술을 활용한 예라고 할 수 있어요.',ARRAY['SO3-2-u1-X13']::text[],false,'{"seq":18,"concept":"SO3-2-u1-C4","difficulty":3,"kind":"ox","stem":"노인에게 약 먹을 시간을 알려 주는 가정용 로봇은 고령화에 대비하는 노력에 지능정보화 기술을 활용한 예라고 할 수 있어요.","answer":"O","reason_options":[{"t":"노인을 대상으로 하는 물건 개발에 인공지능 기술이 쓰였기 때문에","correct":true},{"t":"로봇은 노인에게 도움이 되지 않기 때문에","mis":"SO3-2-u1-X13"}],"mis":"SO3-2-u1-X13","explanation":["교과서 20쪽 사진 ③이에요.","노인을 위한 물건이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#19','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C4',3,'ox','auto','인터넷·스마트폰 과의존 문제를 막으려면 정해진 규칙에 따라 인터넷이나 태블릿 컴퓨터를 사용해야 해요.',ARRAY['SO3-2-u1-X14']::text[],false,'{"seq":19,"concept":"SO3-2-u1-C4","difficulty":3,"kind":"ox","stem":"인터넷·스마트폰 과의존 문제를 막으려면 정해진 규칙에 따라 인터넷이나 태블릿 컴퓨터를 사용해야 해요.","answer":"O","reason_options":[{"t":"지나치게 쓰지 않도록 규칙을 지키는 습관이 필요하기 때문에","correct":true},{"t":"편리하니 오래 쓸수록 좋기 때문에","mis":"SO3-2-u1-X14"}],"mis":"SO3-2-u1-X14","explanation":["과의존은 지나치게 쓰는 거예요.","규칙을 지켜요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#20','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C9',3,'ox','auto','1인 가구가 늘어나며 상점에 적은 양을 포장한 상품이 많아진 것은 다양한 문화의 확산이 가져온 긍정적 효과예요.',ARRAY['SO3-2-u1-X28']::text[],false,'{"seq":20,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"ox","stem":"1인 가구가 늘어나며 상점에 적은 양을 포장한 상품이 많아진 것은 다양한 문화의 확산이 가져온 긍정적 효과예요.","answer":"O","reason_options":[{"t":"혼자 사는 사람들이 편리하게 생활할 수 있게 되었기 때문에","correct":true},{"t":"1인 가구는 사회에 아무 영향을 주지 않기 때문에","mis":"SO3-2-u1-X28"}],"mis":"SO3-2-u1-X28","explanation":["교과서 44쪽 기사예요.","혼자 쓰기 편해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#21','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C10',3,'ox','auto','학교에서 다양한 문화를 이해하는 교육을 받으면 다른 문화의 특징을 이해하는 데 도움이 돼요.',ARRAY['SO3-2-u1-X29']::text[],false,'{"seq":21,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"ox","stem":"학교에서 다양한 문화를 이해하는 교육을 받으면 다른 문화의 특징을 이해하는 데 도움이 돼요.","answer":"O","reason_options":[{"t":"다른 나라의 문화를 체험하며 그 문화의 특징을 알게 되기 때문에","correct":true},{"t":"학교 교육은 다른 문화와 관계없기 때문에","mis":"SO3-2-u1-X29"}],"mis":"SO3-2-u1-X29","explanation":["교과서 50쪽 그림 ①이에요.","다양한 문화를 배워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#22','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C10',3,'ox','auto','무심결에 한 말이 다른 사람에게는 상처가 될 수 있으므로 서로의 문화를 존중하는 표현을 써야 해요.',ARRAY['SO3-2-u1-X34']::text[],false,'{"seq":22,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"ox","stem":"무심결에 한 말이 다른 사람에게는 상처가 될 수 있으므로 서로의 문화를 존중하는 표현을 써야 해요.","answer":"O","reason_options":[{"t":"말 속에 다른 문화에 대한 편견과 차별이 담기기도 하기 때문에","correct":true},{"t":"무심결에 한 말은 듣는 사람의 기분과 관계없기 때문에","mis":"SO3-2-u1-X34"}],"mis":"SO3-2-u1-X34","explanation":["말에도 편견이 담겨요.","존중하는 표현을 써요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#23','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C8',4,'mc','auto','1인 가구와 반려동물 문화가 늘어난 것을 사회 변화와 이어 설명한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X25']::text[],false,'{"seq":23,"concept":"SO3-2-u1-C8","difficulty":4,"kind":"mc","stem":"1인 가구와 반려동물 문화가 늘어난 것을 사회 변화와 이어 설명한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"고령화로 혼자 사는 노인이 늘며 1인 가구가 늘었고, 1인 가구가 늘고 생활 수준이 높아지며 반려동물과 사는 사람도 많아졌어요","correct":true},{"t":"저출산으로 학생이 늘어 1인 가구가 늘었어요","mis":"SO3-2-u1-X25"},{"t":"세계화로 반려동물이 줄었어요","mis":"SO3-2-u1-X25"},{"t":"1인 가구와 반려동물은 사회 변화와 관계없어요","mis":"SO3-2-u1-X25"}],"explanation":["고령화와 1인 가구를 이어요.","1인 가구와 반려동물을 이어요.","사회 변화가 문화를 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#24','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C2',4,'essay','teacher','신문 기사처럼 ○○구가 임산부와 아기를 키우는 가정에 교통비와 물품을 지원하는 노력이 저출산에 줄 영향을 예상해 쓰고, 교과서 17쪽 방법 가운데 함께 쓰면 좋을 방법을 하나 더 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-2-u1-C2","difficulty":4,"kind":"essay","stem":"신문 기사처럼 ○○구가 임산부와 아기를 키우는 가정에 교통비와 물품을 지원하는 노력이 저출산에 줄 영향을 예상해 쓰고, 교과서 17쪽 방법 가운데 함께 쓰면 좋을 방법을 하나 더 쓰세요.","answer_guide":{"answer":"예: 아이를 낳고 키우는 부담이 줄어 저출산 문제를 해결하는 데 도움을 줄 것 같아요. 부모가 자녀를 키우기 위해 일정 기간 일을 쉴 수 있는 제도도 함께 운영하면 좋겠어요.","scoring_points":["저출산에 줄 영향을 예상했는가","교과서 17쪽 방법을 하나 더 골랐는가","까닭이 알맞은가"]},"explanation":["지원이 부담을 덜어요.","17쪽 방법을 떠올려요.","함께 쓰면 좋을 방법을 써요."],"asset":{"type":"passage","lines":["임산부가 안전하게 이동할 수 있도록 교통비를 지원한다.","24개월 이하 아기를 키우는 가정에 택시 이용 포인트를 준다.","아이를 가지려고 노력하는 부부에게 의료비를 지원한다.","태어나는 아이를 위한 물품을 지원한다."],"numbered":false,"title":"○○구가 하는 일 — 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_b#25','soc',3,2,'u1','','tb_g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C10',4,'essay','teacher','미나가 겪는 어려움을 쓰고, 미나와 같은 반 친구라면 미나를 위해 어떤 일을 할지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-2-u1-C10","difficulty":4,"kind":"essay","stem":"미나가 겪는 어려움을 쓰고, 미나와 같은 반 친구라면 미나를 위해 어떤 일을 할지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 미나는 사람들이 자신의 피부색을 이상하게 여긴다고 생각해 늘 모자를 쓰고, 모자를 벗은 그림을 보고 부끄러움을 느꼈어요. 나는 미나에게 모자를 벗은 모습도 전혀 이상하지 않다고 말해 주고 함께 놀 거예요. 서로 다름을 인정하고 존중해야 하기 때문이에요.","scoring_points":["미나의 어려움을 썼는가","내가 할 일을 썼는가","존중하는 태도와 이어 까닭을 썼는가"]},"explanation":["미나의 마음을 생각해요.","내가 할 수 있는 일을 써요.","까닭을 써요."],"asset":{"type":"passage","lines":["부모님이 외국인 이주민인 미나는 피부색이 검어요.","미나는 다른 사람들이 자신의 피부색을 이상하게 여긴다고 생각해요.","그래서 미나는 집 밖에 나갈 때면 항상 모자를 써요.","어느 날 미술 시간에 한 친구가 모자를 벗은 미나의 모습을 그렸어요.","부끄러움을 느낀 미나는 교실 밖으로 뛰쳐나갔어요."],"title":"만화 영화 속 이야기 — 교과서 48쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#1','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C2',1,'ox','auto','그래프의 세로는 연도를 나타내요.',ARRAY['SO3-2-u1-X05']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C2","difficulty":1,"kind":"ox","stem":"그래프의 세로는 연도를 나타내요.","answer":"X","reason_options":[{"t":"세로는 태어나는 아이의 수를, 가로는 연도를 나타내기 때문에","correct":true},{"t":"아래쪽에 적힌 연도가 세로 칸이기 때문에","mis":"SO3-2-u1-X05"}],"mis":"SO3-2-u1-X05","explanation":["가로와 세로를 확인해요.","세로는 태어나는 아이의 수예요.","그래서 X예요."],"asset":{"type":"passage","lines":["1970년 — 101만 명 · 1980년 — 86만 명","1990년 — 65만 명 · 2000년 — 64만 명","2010년 — 47만 명 · 2020년 — 27만 명","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"numbered":false,"title":"우리나라에서 연도별 태어나는 아이의 수 — 교과서 15쪽 그래프"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#2','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C3',1,'ox','auto','고령화는 전체 사람 수에서 노인의 수가 차지하는 비율이 낮아지는 현상이에요.',ARRAY['SO3-2-u1-X08']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C3","difficulty":1,"kind":"ox","stem":"고령화는 전체 사람 수에서 노인의 수가 차지하는 비율이 낮아지는 현상이에요.","answer":"X","reason_options":[{"t":"고령화는 노인의 수가 차지하는 비율이 높아지는 현상이기 때문에","correct":true},{"t":"노인이 많아지면 비율은 낮아지기 때문에","mis":"SO3-2-u1-X08"}],"mis":"SO3-2-u1-X08","explanation":["고령화의 뜻을 떠올려요.","비율이 높아져요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#3','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C4',1,'ox','auto','인공지능이 주변 상황을 실시간으로 파악해 운전자의 안전한 운전을 도와주는 것은 지능정보화로 달라진 생활 모습이에요.',ARRAY['SO3-2-u1-X12']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"ox","stem":"인공지능이 주변 상황을 실시간으로 파악해 운전자의 안전한 운전을 도와주는 것은 지능정보화로 달라진 생활 모습이에요.","answer":"O","reason_options":[{"t":"교과서 23쪽에 나온 지능정보화의 모습이기 때문에","correct":true},{"t":"자동차 운전은 인공지능과 관계없기 때문에","mis":"SO3-2-u1-X12"}],"mis":"SO3-2-u1-X12","explanation":["교과서 23쪽 그림이에요.","인공지능이 운전을 도와요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#4','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C4',1,'mc','auto','경찰청에서 사이버 범죄 신고 시스템을 운영하는 까닭은 무엇인가요?',ARRAY['SO3-2-u1-X14']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"mc","stem":"경찰청에서 사이버 범죄 신고 시스템을 운영하는 까닭은 무엇인가요?","options":[{"t":"사이버 범죄를 감시하고 피해를 줄이려고","correct":true},{"t":"인터넷 사용 시간을 늘리려고","mis":"SO3-2-u1-X14"},{"t":"가짜 뉴스를 더 많이 만들려고","mis":"SO3-2-u1-X14"},{"t":"개인 정보를 널리 알리려고","mis":"SO3-2-u1-X14"}],"explanation":["교과서 25쪽 사진 ①이에요.","범죄를 감시해요.","피해를 줄이려고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#5','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C5',1,'ox','auto','세종 학당은 다른 나라에서 한국어를 배우려는 사람들에게 한국어를 중심으로 한국에 관한 내용을 가르치는 곳이에요.',ARRAY['SO3-2-u1-X16']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C5","difficulty":1,"kind":"ox","stem":"세종 학당은 다른 나라에서 한국어를 배우려는 사람들에게 한국어를 중심으로 한국에 관한 내용을 가르치는 곳이에요.","answer":"O","reason_options":[{"t":"교과서 28쪽 신문 기사에 나온 내용이기 때문에","correct":true},{"t":"세종 학당은 우리나라 사람에게 다른 나라 말을 가르치기 때문에","mis":"SO3-2-u1-X16"}],"mis":"SO3-2-u1-X16","explanation":["28쪽 기사를 떠올려요.","한국어를 가르쳐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#6','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C7',1,'ox','auto','포크와 나이프로 먹는 모습과 숟가락과 젓가락으로 먹는 모습이 다른 것은 지역에 따라 음식을 먹는 도구가 다르기 때문이에요.',ARRAY['SO3-2-u1-X23']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C7","difficulty":1,"kind":"ox","stem":"포크와 나이프로 먹는 모습과 숟가락과 젓가락으로 먹는 모습이 다른 것은 지역에 따라 음식을 먹는 도구가 다르기 때문이에요.","answer":"O","reason_options":[{"t":"지역이나 주로 먹는 음식에 따라 생활 양식이 다르게 나타나기 때문에","correct":true},{"t":"한 가지 도구만 알맞은 도구이기 때문에","mis":"SO3-2-u1-X23"}],"mis":"SO3-2-u1-X23","explanation":["교과서 35쪽 사진 ③·④예요.","먹는 도구가 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#7','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C9',1,'ox','auto','외국인 이주민이 참여하는 행사에서는 다양한 문화를 체험할 수 있어요.',ARRAY['SO3-2-u1-X26']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C9","difficulty":1,"kind":"ox","stem":"외국인 이주민이 참여하는 행사에서는 다양한 문화를 체험할 수 있어요.","answer":"O","reason_options":[{"t":"교과서 43쪽에서 외국인 이주민이 참여하는 행사에서 다양한 문화를 체험할 수 있다고 했기 때문에","correct":true},{"t":"외국인 이주민은 행사에 참여할 수 없기 때문에","mis":"SO3-2-u1-X26"}],"mis":"SO3-2-u1-X26","explanation":["교과서 43쪽 말풍선이에요.","다양한 문화를 체험해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#8','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C8',1,'ox','auto','오늘날 우리 사회는 외국인 이주민이 증가하고 반려동물과 함께 사는 사람이 많아지는 등 다양한 문화가 확산되고 있어요.',ARRAY['SO3-2-u1-X25']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C8","difficulty":1,"kind":"ox","stem":"오늘날 우리 사회는 외국인 이주민이 증가하고 반려동물과 함께 사는 사람이 많아지는 등 다양한 문화가 확산되고 있어요.","answer":"O","reason_options":[{"t":"교과서 42쪽 꼭 기억해요에서 확인한 내용이기 때문에","correct":true},{"t":"우리 사회의 문화는 한 가지로 줄어들고 있기 때문에","mis":"SO3-2-u1-X25"}],"mis":"SO3-2-u1-X25","explanation":["여러 사람들이 늘었어요.","문화가 다양해져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#9','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C10',2,'mc','auto','만화 영화 속 미나가 미술 시간에 교실 밖으로 뛰쳐나간 까닭은 무엇인가요?',ARRAY['SO3-2-u1-X30']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"mc","stem":"만화 영화 속 미나가 미술 시간에 교실 밖으로 뛰쳐나간 까닭은 무엇인가요?","options":[{"t":"친구가 모자를 벗은 미나의 모습을 그렸고, 그 그림을 보고 부끄러움을 느꼈기 때문이에요","correct":true},{"t":"미술을 싫어했기 때문이에요","mis":"SO3-2-u1-X30"},{"t":"모자를 잃어버렸기 때문이에요","mis":"SO3-2-u1-X30"},{"t":"친구가 미나에게 모자를 선물했기 때문이에요","mis":"SO3-2-u1-X30"}],"explanation":["미술 시간에 무슨 일이 있었나요?","모자를 벗은 모습을 그렸어요.","부끄러움을 느꼈어요."],"asset":{"type":"passage","lines":["부모님이 외국인 이주민인 미나는 피부색이 검어요.","미나는 다른 사람들이 자신의 피부색을 이상하게 여긴다고 생각해요.","그래서 미나는 집 밖에 나갈 때면 항상 모자를 써요.","어느 날 미술 시간에 한 친구가 모자를 벗은 미나의 모습을 그렸어요.","부끄러움을 느낀 미나는 교실 밖으로 뛰쳐나갔어요."],"title":"만화 영화 속 이야기 — 교과서 48쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#10','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C10',2,'ox','auto','목줄이나 입마개를 하지 않는 것도 반려동물로 이웃 간에 갈등이 생기는 원인 가운데 하나예요.',ARRAY['SO3-2-u1-X28']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"ox","stem":"목줄이나 입마개를 하지 않는 것도 반려동물로 이웃 간에 갈등이 생기는 원인 가운데 하나예요.","answer":"O","reason_options":[{"t":"교과서 47쪽 표에서 4위 원인으로 나와 있기 때문에","correct":true},{"t":"목줄과 입마개는 이웃과 관계없기 때문에","mis":"SO3-2-u1-X28"}],"mis":"SO3-2-u1-X28","explanation":["갈등 원인 표를 떠올려요.","4위 원인이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#11','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C5',2,'ox','auto','학교에서 영어와 세계 여러 나라에 관한 내용을 배우는 것도 세계화로 달라진 생활 모습이에요.',ARRAY['SO3-2-u1-X15']::text[],false,'{"seq":11,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"ox","stem":"학교에서 영어와 세계 여러 나라에 관한 내용을 배우는 것도 세계화로 달라진 생활 모습이에요.","answer":"O","reason_options":[{"t":"교과서 27쪽 사진 ④에 나온 세계화의 모습이기 때문에","correct":true},{"t":"학교 공부는 세계화와 관계없기 때문에","mis":"SO3-2-u1-X15"}],"mis":"SO3-2-u1-X15","explanation":["27쪽 사진 ④예요.","세계 여러 나라를 배워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#12','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C4',2,'mc','auto','생각 그물에서 지능정보화 가지의 해결 노력으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X18']::text[],false,'{"seq":12,"concept":"SO3-2-u1-C4","difficulty":2,"kind":"mc","stem":"생각 그물에서 지능정보화 가지의 해결 노력으로 알맞은 것은 무엇인가요?","options":[{"t":"사이버 범죄 예방과 올바른 인터넷·스마트폰 사용 습관","correct":true},{"t":"우리나라의 생활 양식을 소중히 여기는 태도","mis":"SO3-2-u1-X18"},{"t":"양육비 지원","mis":"SO3-2-u1-X18"},{"t":"일자리 제공","mis":"SO3-2-u1-X18"}],"explanation":["지능정보화의 문제를 떠올려요.","사이버 범죄와 과의존이에요.","그에 맞는 해결 노력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#13','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C10',2,'mc','auto','생각 그물에서 다양한 문화의 문제를 해결하는 노력으로 나온 것은 무엇인가요?',ARRAY['SO3-2-u1-X29']::text[],false,'{"seq":13,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"mc","stem":"생각 그물에서 다양한 문화의 문제를 해결하는 노력으로 나온 것은 무엇인가요?","options":[{"t":"다문화 이해 교육, 1인 가구를 위한 지원 활동, 반려동물 예절 준수","correct":true},{"t":"양육비 지원, 보육 시설 운영","mis":"SO3-2-u1-X29"},{"t":"사이버 범죄 예방","mis":"SO3-2-u1-X29"},{"t":"노인 일자리 제공","mis":"SO3-2-u1-X29"}],"explanation":["다양한 문화 가지의 해결 노력이에요.","교육, 지원, 예절이에요.","나머지는 1주제 내용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#14','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C7',2,'mc','auto','교과서 36쪽에서 중국의 새 학년이 시작하는 시기는 언제인가요?',ARRAY['SO3-2-u1-X22']::text[],false,'{"seq":14,"concept":"SO3-2-u1-C7","difficulty":2,"kind":"mc","stem":"교과서 36쪽에서 중국의 새 학년이 시작하는 시기는 언제인가요?","options":[{"t":"매년 9월","correct":true},{"t":"매년 3월","mis":"SO3-2-u1-X22"},{"t":"매년 8월","mis":"SO3-2-u1-X22"},{"t":"매년 1월","mis":"SO3-2-u1-X22"}],"explanation":["36쪽 「가」를 봐요.","우리 학교는 3월이에요.","중국은 9월이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#15','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C11',2,'mc','auto','딩고 놀이에서 진행자가 「버려!」를 외치면 무엇을 하나요?',ARRAY['SO3-2-u1-X32']::text[],false,'{"seq":15,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"mc","stem":"딩고 놀이에서 진행자가 「버려!」를 외치면 무엇을 하나요?","options":[{"t":"필요 없다고 생각한 카드 1장을 동시에 책상 가운데에 뒤집어서 내려놓아요","correct":true},{"t":"책상에 놓인 카드 중 1장을 집어 가져가요","mis":"SO3-2-u1-X32"},{"t":"카드를 모두 섞어 다시 나눠요","mis":"SO3-2-u1-X32"},{"t":"「딩고!」라고 외쳐요","mis":"SO3-2-u1-X32"}],"explanation":["버리는 차례예요.","필요 없는 카드예요.","책상 가운데에 뒤집어 놓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#16','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C6',2,'mc','auto','단원을 시작하며 「들어 본 말에 색칠해 보세요」에 나온 말이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u1-X18']::text[],false,'{"seq":16,"concept":"SO3-2-u1-C6","difficulty":2,"kind":"mc","stem":"단원을 시작하며 「들어 본 말에 색칠해 보세요」에 나온 말이 아닌 것은 무엇인가요?","options":[{"t":"유니버설 디자인","correct":true},{"t":"저출산","mis":"SO3-2-u1-X18"},{"t":"1인 가구","mis":"SO3-2-u1-X18"},{"t":"반려동물","mis":"SO3-2-u1-X18"}],"explanation":["교과서 10쪽 여덟 낱말을 떠올려요.","저출산부터 반려동물까지예요.","유니버설 디자인은 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#17','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C6',3,'error','auto','사회 변화를 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X16','SO3-2-u1-X13','SO3-2-u1-X06']::text[],false,'{"seq":17,"concept":"SO3-2-u1-C6","difficulty":3,"kind":"error","stem":"사회 변화를 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 나 — 「세계화로 우리나라는 다른 나라의 영향을 받기만 해.」","correct":true,"mis_target":"SO3-2-u1-X16"},{"t":"친구 가 — 「지능정보화로 생활이 편리해졌지만 사이버 범죄도 생겼어.」","mis":"SO3-2-u1-X13"},{"t":"친구 다 — 「저출산이 계속되면 일할 수 있는 사람이 줄어들 거야.」","mis":"SO3-2-u1-X06"}],"explanation":["우리나라도 세계에 영향을 줘요.","세종 학당과 한국 라면을 떠올려요.","친구 나가 바르지 않게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#18','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C3',3,'mc','auto','고령화로 생길 수 있는 문제로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X10','SO3-2-u1-X33','SO3-2-u1-X03']::text[],false,'{"seq":18,"concept":"SO3-2-u1-C3","difficulty":3,"kind":"mc","stem":"고령화로 생길 수 있는 문제로 가장 알맞은 것은 무엇인가요?","options":[{"t":"건강 문제로 활동하기 힘든 노인이 많아지고, 건강 관리와 생활 유지 비용이 늘어나요","correct":true},{"t":"노인이 모두 사라져 복지관이 필요 없어져요","mis":"SO3-2-u1-X10"},{"t":"노인이 많아지는 것은 노인들의 잘못이에요","mis":"SO3-2-u1-X33"},{"t":"학교가 부족해 오전반, 오후반이 생겨요","mis":"SO3-2-u1-X03"}],"explanation":["노인이 많아져요.","건강을 돌볼 일이 늘어요.","비용도 늘어나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#19','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C5',3,'error','auto','세계화에 대응하는 광고 문구를 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X17']::text[],false,'{"seq":19,"concept":"SO3-2-u1-C5","difficulty":3,"kind":"error","stem":"세계화에 대응하는 광고 문구를 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 다 — 「첫 번째 문구는 다른 나라 생활 양식을 무조건 따르자는 뜻이야.」","correct":true,"mis_target":"SO3-2-u1-X17"},{"t":"친구 가 — 「두 번째 문구는 세계인의 관심으로 모두가 행복해지자는 뜻이야.」","mis":"SO3-2-u1-X17"},{"t":"친구 나 — 「세 번째 문구는 작은 관심이 세계인의 행복을 만든다는 뜻이야.」","mis":"SO3-2-u1-X17"}],"explanation":["첫 번째 문구는 우리 전통을 소중히 여겨요.","무조건 따르자는 뜻이 아니에요.","친구 다가 바르지 않게 말했어요."],"asset":{"type":"passage","lines":["첫 번째 — 소중히 여기는 우리 전통, 더 나은 세계화","두 번째 — 세계인의 관심으로 만드는 모두가 행복한 세상","세 번째 — 우리의 작은 관심이 만드는 세계인의 더 큰 행복"],"title":"세계화에 대응하는 태도를 담은 광고 문구 — 교과서 29쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#20','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C9',3,'error','auto','다양한 문화가 퍼진 영향을 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X26','SO3-2-u1-X28']::text[],false,'{"seq":20,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"error","stem":"다양한 문화가 퍼진 영향을 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 나 — 「다양한 문화가 퍼지면서 사람들이 누릴 수 있는 문화가 줄어들었어.」","correct":true,"mis_target":"SO3-2-u1-X26"},{"t":"친구 가 — 「외국인 이주민 덕분에 여러 나라 문화를 경험할 기회가 늘었어.」","mis":"SO3-2-u1-X28"},{"t":"친구 다 — 「혼자 사는 사람이 아플 때 도움을 청할 사람이 없기도 해.」","mis":"SO3-2-u1-X28"}],"explanation":["누릴 문화가 많아졌어요.","줄어든 게 아니에요.","친구 나가 바르지 않게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#21','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C10',3,'error','auto','교과서 50~51쪽 노력이 주는 도움을 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X29']::text[],false,'{"seq":21,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"error","stem":"교과서 50~51쪽 노력이 주는 도움을 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 다 — 「입마개와 목줄은 반려견을 기르지 않는 사람과는 아무 관계가 없어.」","correct":true,"mis_target":"SO3-2-u1-X29"},{"t":"친구 가 — 「1인 가구 프로그램은 혼자 사는 사람의 건강과 안전에 도움이 돼.」","mis":"SO3-2-u1-X29"},{"t":"친구 나 — 「국가 인권 위원회 덕분에 억울한 차별을 당했을 때 도움을 요청할 수 있어.」","mis":"SO3-2-u1-X29"}],"explanation":["물림 사고는 이웃에게도 일어나요.","입마개와 목줄은 이웃을 지켜요.","친구 다가 바르지 않게 말했어요."],"asset":{"type":"passage","lines":["① 학교에서 다양한 문화를 이해하는 교육을 실시해요.","② 반려견과 산책할 때는 입마개를 착용시키고 목줄을 채워요.","④ 한국어에 서툰 외국인을 위해 원활한 의사소통을 지원해요.","⑤ 혼자 사는 사람들이 안전하고 편안한 환경에서 살 수 있도록 지원해요.","⑥ 편견과 차별을 막을 수 있는 제도를 만들고 관련 기관을 운영해요.","⑦ 버려진 반려동물을 돌봐 주고 새로운 주인을 만나게 해 줘요.","⑧ 세계 여러 나라의 문화를 이해하고 체험할 수 있는 행사를 열어요.","⑨ 1인 가구를 위한 다양한 프로그램을 운영해요."],"numbered":false,"title":"다양한 문화의 확산에 따른 문제를 해결하려는 노력 — 교과서 50~51쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#22','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C10',3,'mc','auto','「한국에서 사니까 좋지요?」를 편견이 없는 표현으로 고친 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X34','SO3-2-u1-X30']::text[],false,'{"seq":22,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"mc","stem":"「한국에서 사니까 좋지요?」를 편견이 없는 표현으로 고친 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「한국에서 사니까 어때요?」","correct":true},{"t":"「한국이 더 좋은 나라죠?」","mis":"SO3-2-u1-X34"},{"t":"「살던 나라보다 한국이 낫죠?」","mis":"SO3-2-u1-X34"},{"t":"「한국말은 왜 못하세요?」","mis":"SO3-2-u1-X30"}],"explanation":["어느 나라가 낫다는 생각을 빼요.","상대의 생각을 물어요.","「어때요?」가 알맞아요."],"asset":{"type":"passage","lines":["⑴ 한국에 와서 사는 외국인에게 — 「한국에서 사니까 좋지요?」","⑵ 혼자 사는 사람을 두고 — 「혼자 사는 것 보니까 능력이 부족하거나 문제가 있을 거야.」","⑶ 반려동물을 안은 사람에게 — 「아기도 아니고 강아지를 안고 다니나요?」"],"title":"무심결에 하는 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#23','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C5',4,'mc','auto','세계화의 영향을 받은 우리 사회의 다양한 문화로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X25','SO3-2-u1-X15','SO3-2-u1-X36']::text[],false,'{"seq":23,"concept":"SO3-2-u1-C5","difficulty":4,"kind":"mc","stem":"세계화의 영향을 받은 우리 사회의 다양한 문화로 가장 알맞은 것은 무엇인가요?","options":[{"t":"직장, 공부, 결혼 등으로 우리나라에 사는 외국인 이주민이 늘며 다양한 나라의 음식과 물건을 파는 거리가 생겼어요","correct":true},{"t":"세계화로 외국인 이주민이 줄었어요","mis":"SO3-2-u1-X25"},{"t":"세계화는 다양한 문화와 아무 관계가 없어요","mis":"SO3-2-u1-X15"},{"t":"세계화로 우리나라에는 한 가지 문화만 남았어요","mis":"SO3-2-u1-X36"}],"explanation":["세계화로 이주민이 늘었어요.","다양한 나라의 거리가 생겼어요.","두 주제가 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#24','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C4',4,'essay','teacher','지능정보화로 나타난 문제 가운데 하나를 골라 그 문제로 생길 수 있는 피해를 쓰고, 학교에서 인터넷이나 태블릿 컴퓨터를 쓸 때 지켜야 할 점을 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-2-u1-C4","difficulty":4,"kind":"essay","stem":"지능정보화로 나타난 문제 가운데 하나를 골라 그 문제로 생길 수 있는 피해를 쓰고, 학교에서 인터넷이나 태블릿 컴퓨터를 쓸 때 지켜야 할 점을 두 가지 쓰세요.","answer_guide":{"answer":"예: 인공지능이 만든 가짜 뉴스를 진짜로 믿는 사람이 생겨 큰 혼란이 일어날 수 있어요. 나는 인터넷에 있는 정보를 비판 없이 무조건 믿지 않고, 선생님의 가르침이나 정해진 규칙에 따라 태블릿 컴퓨터를 쓸 거예요.","scoring_points":["문제와 피해를 알맞게 썼는가","지켜야 할 점 두 가지를 썼는가","지켜야 할 점이 문제와 이어지는가"]},"explanation":["네 가지 문제를 떠올려요.","생길 수 있는 피해를 예상해요.","지킬 점을 두 가지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_c#25','soc',3,2,'u1','','tb_g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C11',4,'essay','teacher','우리 사회의 다양한 문화의 모습이나 다양한 문화를 대하는 바람직한 태도를 담아 네 줄 정도의 짧은 시를 짓고, 시에 담은 생각을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-2-u1-C11","difficulty":4,"kind":"essay","stem":"우리 사회의 다양한 문화의 모습이나 다양한 문화를 대하는 바람직한 태도를 담아 네 줄 정도의 짧은 시를 짓고, 시에 담은 생각을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 시 「우리 동네」 — 인도 음식점 맨손 식사 / 공원에서 뛰노는 강아지 / 서로 달라 더 재미있는 / 함께 사는 우리 동네. 담은 생각 — 서로 다른 문화가 함께 어울리면 동네가 더 즐거워진다는 생각이에요.","scoring_points":["다양한 문화의 모습이나 태도를 담았는가","네 줄 정도로 시를 지었는가","담은 생각을 한 문장으로 썼는가"]},"explanation":["다양한 문화의 모습을 떠올려요.","짧은 시로 지어요.","담은 생각을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#1','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C2',1,'mc','auto','그래프에서 태어난 아이가 가장 많았던 해는 언제인가요?',ARRAY['SO3-2-u1-X05']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C2","difficulty":1,"kind":"mc","stem":"그래프에서 태어난 아이가 가장 많았던 해는 언제인가요?","options":[{"t":"1970년","correct":true},{"t":"2020년","mis":"SO3-2-u1-X05"},{"t":"1990년","mis":"SO3-2-u1-X05"},{"t":"2000년","mis":"SO3-2-u1-X05"}],"explanation":["가장 긴 막대를 찾아요.","101만 명이에요.","1970년이에요."],"asset":{"type":"passage","lines":["1970년 — 101만 명 · 1980년 — 86만 명","1990년 — 65만 명 · 2000년 — 64만 명","2010년 — 47만 명 · 2020년 — 27만 명","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"numbered":false,"title":"우리나라에서 연도별 태어나는 아이의 수 — 교과서 15쪽 그래프"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#2','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C3',1,'mc','auto','노인 일자리 설명회를 여는 것은 고령화에 대비하는 어떤 노력인가요?',ARRAY['SO3-2-u1-X18']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C3","difficulty":1,"kind":"mc","stem":"노인 일자리 설명회를 여는 것은 고령화에 대비하는 어떤 노력인가요?","options":[{"t":"노인들에게 알맞은 일자리를 제공하는 노력","correct":true},{"t":"아이를 낳고 키우는 데 필요한 돈을 지원하는 노력","mis":"SO3-2-u1-X18"},{"t":"사이버 범죄를 감시하는 노력","mis":"SO3-2-u1-X18"},{"t":"다른 나라에 우리 생활 양식을 알리는 노력","mis":"SO3-2-u1-X18"}],"explanation":["교과서 20쪽 사진 ②예요.","노인 일자리 설명회예요.","일자리를 제공하는 노력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#3','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C4',1,'blank','auto','애플리케이션으로 주문하면 (    )이 음식을 배달해 주는 모습은 지능정보화로 달라진 생활 모습이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X12']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"blank","stem":"애플리케이션으로 주문하면 (    )이 음식을 배달해 주는 모습은 지능정보화로 달라진 생활 모습이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"로봇","correct":true},{"t":"노인","mis":"SO3-2-u1-X12"},{"t":"보육 시설","mis":"SO3-2-u1-X12"},{"t":"세종 학당","mis":"SO3-2-u1-X12"}],"explanation":["교과서 22쪽 그림 ③이에요.","길거리를 달려요.","배달 로봇이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#4','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C4',1,'sa','auto','다른 사람과 구별해 개인을 알 수 있는 모든 정보를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"sa","stem":"다른 사람과 구별해 개인을 알 수 있는 모든 정보를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["개인 정보","개인정보"],"explanation":["교과서 24쪽 낱말 풀이예요.","이름, 주소, 전화번호 같은 것이에요.","개인 정보예요."],"mis":"SO3-2-u1-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#5','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C5',1,'blank','auto','세계화에 대응하려면 다른 나라의 생활 양식을 무조건 따르지 않고 (    )을 따져 받아들이는 태도가 필요해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X17']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C5","difficulty":1,"kind":"blank","stem":"세계화에 대응하려면 다른 나라의 생활 양식을 무조건 따르지 않고 (    )을 따져 받아들이는 태도가 필요해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"장단점","correct":true},{"t":"가격","mis":"SO3-2-u1-X17"},{"t":"나이","mis":"SO3-2-u1-X17"},{"t":"거리","mis":"SO3-2-u1-X17"}],"explanation":["교과서 29쪽 본문이에요.","좋은 점과 나쁜 점이에요.","장단점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#6','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C7',1,'mc','auto','사람이 살아가기 위해 꼭 필요한 옷, 음식, 집을 함께 이르는 말은 무엇인가요?',ARRAY['SO3-2-u1-X21']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C7","difficulty":1,"kind":"mc","stem":"사람이 살아가기 위해 꼭 필요한 옷, 음식, 집을 함께 이르는 말은 무엇인가요?","options":[{"t":"의식주","correct":true},{"t":"규범","mis":"SO3-2-u1-X21"},{"t":"초원","mis":"SO3-2-u1-X21"},{"t":"생활 수준","mis":"SO3-2-u1-X21"}],"explanation":["교과서 36쪽 낱말 풀이예요.","옷·음식·집이에요.","의식주예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#7','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C8',1,'mc','auto','우리나라에 사는 외국인 이주민이 늘어난 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X25']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C8","difficulty":1,"kind":"mc","stem":"우리나라에 사는 외국인 이주민이 늘어난 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"세계화의 영향으로 직장, 공부, 결혼 등 다양한 목적으로 우리나라에 와서 살기 때문이에요","correct":true},{"t":"1인 가구가 줄어들었기 때문이에요","mis":"SO3-2-u1-X25"},{"t":"반려동물이 늘었기 때문이에요","mis":"SO3-2-u1-X25"},{"t":"우리나라 사람이 모두 다른 나라로 떠났기 때문이에요","mis":"SO3-2-u1-X25"}],"explanation":["교과서 40쪽 본문이에요.","세계화의 영향이에요.","여러 목적으로 와서 살아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#8','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C9',1,'mc','auto','1인 가구의 편리한 생활을 돕는 활동으로 교과서 44쪽에서 든 것은 무엇인가요?',ARRAY['SO3-2-u1-X28']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C9","difficulty":1,"kind":"mc","stem":"1인 가구의 편리한 생활을 돕는 활동으로 교과서 44쪽에서 든 것은 무엇인가요?","options":[{"t":"장보기, 세탁, 청소를 대신 해 주는 활동","correct":true},{"t":"반려견 훈련","mis":"SO3-2-u1-X28"},{"t":"세계 음식 축제","mis":"SO3-2-u1-X28"},{"t":"노인 일자리 설명회","mis":"SO3-2-u1-X28"}],"explanation":["교과서 44쪽 물음이에요.","혼자 사는 사람을 도와요.","집안일을 대신 해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#9','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C9',2,'error','auto','교과서 46쪽 세 그림을 보고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X27','SO3-2-u1-X30']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"error","stem":"교과서 46쪽 세 그림을 보고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 다 — 「피부색이 다른 사람과 거리를 두는 것은 편견도 차별도 아니야.」","correct":true,"mis_target":"SO3-2-u1-X27"},{"t":"친구 가 — 「종교적인 이유로 음식을 먹지 않는 문화가 있어.」","mis":"SO3-2-u1-X27"},{"t":"친구 나 — 「우리말을 잘하지 못하는 외국인을 이해해야 해.」","mis":"SO3-2-u1-X30"}],"explanation":["거리를 두는 것은 행동이에요.","다르게 대우했어요.","친구 다가 바르지 않게 말했어요."],"asset":{"type":"passage","lines":["① 종교적인 이유로 고기를 먹지 않는 것을 비난해요.","　「고기를 먹지 않는 것은 옳지 않아.」","② 우리말을 잘하지 못해서 무시해요.","　「아휴, 답답해. 우리말을 너무 못하네.」","③ 자신과 피부색이 다른 사람을 이상한 눈빛으로 쳐다보거나 거리를 둬요.","　「다른 자리에 앉아야지.」"],"numbered":false,"title":"교과서 46쪽 그림 속 세 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#10','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C9',2,'match','auto','반려동물로 이웃 간에 갈등이 생긴 원인을 순위와 이으세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"match","stem":"반려동물로 이웃 간에 갈등이 생긴 원인을 순위와 이으세요.","pairs":[{"l":"1위","r":"소음(짖음, 발소리)"},{"l":"2위","r":"배설물"},{"l":"3위","r":"냄새"},{"l":"5위","r":"물림"}],"mis":"SO3-2-u1-X05","explanation":["가장 많은 원인은 소음이에요.","그다음은 배설물과 냄새예요.","물림은 5위예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#11','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C5',2,'match','auto','세계 곳곳에서 들여온 상품과 그 상품을 만든 나라를 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"match","stem":"세계 곳곳에서 들여온 상품과 그 상품을 만든 나라를 이으세요.","pairs":[{"l":"초콜릿","r":"벨기에"},{"l":"화장품","r":"프랑스"},{"l":"청바지","r":"미국"},{"l":"프라이팬","r":"독일"}],"mis":"SO3-2-u1-X15","explanation":["만든 나라를 찾아요.","여러 나라에서 들여왔어요.","세계화의 모습이에요."],"asset":{"type":"passage","lines":["벨기에에서 만든 초콜릿 · 프랑스에서 만든 화장품","칠레에서 재배한 포도 · 미국에서 만든 청바지","독일에서 만든 프라이팬"],"title":"세계 곳곳에서 들여온 상품 — 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#12','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C6',2,'sa','auto','생각 그물에서 「다른 나라와의 교류 활발 · 문제: 전통적인 생활 양식 약화, 감염병의 빠른 확산」이 들어가는 사회 변화는 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"SO3-2-u1-C6","difficulty":2,"kind":"sa","stem":"생각 그물에서 「다른 나라와의 교류 활발 · 문제: 전통적인 생활 양식 약화, 감염병의 빠른 확산」이 들어가는 사회 변화는 무엇인가요? 세 글자로 쓰세요.","answer":["세계화"],"explanation":["다른 나라와의 교류예요.","감염병이 퍼져요.","세계화예요."],"mis":"SO3-2-u1-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#13','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C10',2,'ox','auto','생각 그물의 예시 답처럼 다양한 문화를 대할 때는 서로 다름을 인정하고 존중해야 해요.',ARRAY['SO3-2-u1-X31']::text[],false,'{"seq":13,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"ox","stem":"생각 그물의 예시 답처럼 다양한 문화를 대할 때는 서로 다름을 인정하고 존중해야 해요.","answer":"O","reason_options":[{"t":"내가 누리는 문화가 소중하듯 다른 사람이 누리는 문화도 소중하기 때문에","correct":true},{"t":"우리와 다른 문화는 받아들이지 않아야 하기 때문에","mis":"SO3-2-u1-X31"}],"mis":"SO3-2-u1-X31","explanation":["바람직한 태도를 떠올려요.","서로 다름을 인정해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#14','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C7',2,'sa','auto','수종이의 가족은 생일에 무엇을 만들어 먹나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"SO3-2-u1-C7","difficulty":2,"kind":"sa","stem":"수종이의 가족은 생일에 무엇을 만들어 먹나요? 두 글자로 쓰세요.","answer":["국수"],"explanation":["세 번째 가족을 봐요.","면발이 길어요.","국수예요."],"asset":{"type":"passage","lines":["세윤이의 가족은 생일에 미역국을 끓여 먹어요.","민지의 가족은 생일에 사탕을 뿌린 빵을 만들어 먹어요.","수종이의 가족은 생일에 면발이 긴 국수를 만들어 먹어요.","「수종아, 긴 면발처럼 오래오래 살렴.」"],"title":"세 가족의 생일 축하 모습 — 교과서 34쪽"},"mis":"SO3-2-u1-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#15','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C11',2,'sa','auto','딩고 놀이를 시작할 때 각자 카드를 몇 장씩 나눠 갖나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"sa","stem":"딩고 놀이를 시작할 때 각자 카드를 몇 장씩 나눠 갖나요? 숫자로 쓰세요.","answer":["4"],"explanation":["카드를 섞어 나눠요.","한 주제로 모을 수만큼이에요.","4장씩이에요."],"mis":"SO3-2-u1-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#16','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C6',2,'match','auto','단원에서 공부할 내용과 그 내용이 처음 나오는 교과서 쪽을 이으세요.','{}'::text[],false,'{"seq":16,"concept":"SO3-2-u1-C6","difficulty":2,"kind":"match","stem":"단원에서 공부할 내용과 그 내용이 처음 나오는 교과서 쪽을 이으세요.","pairs":[{"l":"저출산으로 달라진 생활 모습","r":"교과서 15쪽"},{"l":"세계화로 달라진 생활 모습","r":"교과서 27쪽"},{"l":"우리 사회의 다양한 문화","r":"교과서 38쪽"},{"l":"다양한 문화의 확산이 미친 영향","r":"교과서 43쪽"}],"mis":"SO3-2-u1-X18","explanation":["교과서 10~11쪽 활동이에요.","쪽수를 보고 찾아요.","주제마다 쪽이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#17','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C6',3,'mc','auto','사회 변화와 그 변화로 나타난 모습이 바르게 짝지어지지 않은 것은 무엇인가요?',ARRAY['SO3-2-u1-X18']::text[],false,'{"seq":17,"concept":"SO3-2-u1-C6","difficulty":3,"kind":"mc","stem":"사회 변화와 그 변화로 나타난 모습이 바르게 짝지어지지 않은 것은 무엇인가요?","options":[{"t":"세계화 — 노인 전문 병원과 요양 시설 운영","correct":true},{"t":"저출산 — 가족 구성원의 수 감소","mis":"SO3-2-u1-X18"},{"t":"지능정보화 — 인공지능을 활용한 배달 로봇","mis":"SO3-2-u1-X18"},{"t":"고령화 — 일하는 노인 증가","mis":"SO3-2-u1-X18"}],"explanation":["짝을 하나씩 확인해요.","노인 전문 병원은 고령화예요.","세계화와 짝이 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#18','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C4',3,'error','auto','고령화와 지능정보화를 함께 생각하며 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO3-2-u1-X13','SO3-2-u1-X10','SO3-2-u1-X12']::text[],false,'{"seq":18,"concept":"SO3-2-u1-C4","difficulty":3,"kind":"error","stem":"고령화와 지능정보화를 함께 생각하며 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 가 — 「노인은 기술을 쓰지 못하니 인공지능 기술은 고령화 문제와 관계없어.」","correct":true,"mis_target":"SO3-2-u1-X13"},{"t":"친구 나 — 「위급할 때 도움을 요청하는 기기를 만들면 혼자 사는 노인에게 도움이 돼.」","mis":"SO3-2-u1-X10"},{"t":"친구 다 — 「인공지능 상담사로 궁금한 점을 해결할 수 있어.」","mis":"SO3-2-u1-X12"}],"explanation":["기술이 노인의 생활을 도와요.","두 변화를 이어 생각해요.","친구 가가 바르지 않게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#19','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C2',3,'mc','auto','저출산 해결 방법을 고른 친구들의 의견이 서로 다를 때 교과서 17쪽 활동에서 하도록 한 일은 무엇인가요?',ARRAY['SO3-2-u1-X35','SO3-2-u1-X07']::text[],false,'{"seq":19,"concept":"SO3-2-u1-C2","difficulty":3,"kind":"mc","stem":"저출산 해결 방법을 고른 친구들의 의견이 서로 다를 때 교과서 17쪽 활동에서 하도록 한 일은 무엇인가요?","options":[{"t":"친구가 고른 방법을 쓰고 서로 의견을 나눠요","correct":true},{"t":"가장 좋은 방법 하나만 정답으로 정해요","mis":"SO3-2-u1-X35"},{"t":"나와 다른 의견은 지워요","mis":"SO3-2-u1-X35"},{"t":"방법을 고르지 않고 넘어가요","mis":"SO3-2-u1-X07"}],"explanation":["17쪽 마지막 활동이에요.","친구의 방법을 써요.","서로 의견을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#20','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C8',3,'mc','auto','교과서 38~39쪽 그림 ②·③·⑤에 나타난 문화를 차례대로 바르게 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u1-X24']::text[],false,'{"seq":20,"concept":"SO3-2-u1-C8","difficulty":3,"kind":"mc","stem":"교과서 38~39쪽 그림 ②·③·⑤에 나타난 문화를 차례대로 바르게 짝지은 것은 무엇인가요?","options":[{"t":"외국인 이주민 — 외국인 이주민 — 1인 가구","correct":true},{"t":"1인 가구 — 반려동물 — 외국인 이주민","mis":"SO3-2-u1-X24"},{"t":"반려동물 — 1인 가구 — 외국인 이주민","mis":"SO3-2-u1-X24"},{"t":"외국인 이주민 — 반려동물 — 반려동물","mis":"SO3-2-u1-X24"}],"explanation":["②는 인도 음식점, ③은 결혼식이에요.","⑤는 1인분 간편식이에요.","이주민, 이주민, 1인 가구예요."],"asset":{"type":"passage","lines":["① 1층 바둑 두는 할아버지 · 2층 아프리카 미술 방송을 보는 부부","　· 3층 고양이가 좋아하는 간식을 알아보는 어린이","② 새로 문을 연 인도 음식점에서 맨손으로 음식을 먹는 사람들","③ 야외 결혼식장 — 한국인 남자와 외국인 여자의 결혼식","④ 공원의 반려동물 전용 놀이터에서 뛰노는 강아지들","⑤ 상점에서 1인분 간편식을 고르는 사람(간판 — 혼자 만들어 먹는 맛있는 집밥)","그 밖에 — 보조견과 산책하는 시각 장애인, 피자와 파스타를 먹는 할머니와 손자"],"numbered":false,"title":"교과서 38~39쪽 그림 속 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#21','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C3',3,'mc','auto','신문 기사 속 노인 센터에서 오후에 운영하는 활동은 무엇인가요?',ARRAY['SO3-2-u1-X10']::text[],false,'{"seq":21,"concept":"SO3-2-u1-C3","difficulty":3,"kind":"mc","stem":"신문 기사 속 노인 센터에서 오후에 운영하는 활동은 무엇인가요?","options":[{"t":"치매 예방 활동","correct":true},{"t":"건강 체크","mis":"SO3-2-u1-X10"},{"t":"물리 치료","mis":"SO3-2-u1-X10"},{"t":"졸업식","mis":"SO3-2-u1-X10"}],"explanation":["오전과 오후를 나눠 읽어요.","오전에는 건강 체크와 물리 치료예요.","오후에는 치매 예방 활동이에요."],"asset":{"type":"passage","lines":["아이들 소리로 가득했던 초등학교가 2015년 졸업생 3명을 끝으로 문을 닫았다.","이듬해 이곳은 노인 센터로 바뀌었다.","이 지역은 주민 3명 중 1명꼴로 65세 이상인 노인이다.","70대부터 100세 넘은 어르신까지 42명이 9시에 등교하고 4시에 하교한다.","오전에는 건강 체크와 물리 치료, 오후에는 치매 예방 활동을 한다."],"numbered":false,"title":"초등학교에서 노인 센터로 — 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#22','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C10',3,'mc','auto','검은 옷 나라 사람들의 문제점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X31']::text[],false,'{"seq":22,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"mc","stem":"검은 옷 나라 사람들의 문제점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"여름에도 덥고 두꺼운 검은 옷만 고집해 생활하기가 힘들었어요","correct":true},{"t":"이웃 나라에서 먹을 것을 사 왔어요","mis":"SO3-2-u1-X31"},{"t":"겨울에 따뜻한 옷을 입었어요","mis":"SO3-2-u1-X31"},{"t":"짧은 소매 옷을 너무 많이 입었어요","mis":"SO3-2-u1-X31"}],"explanation":["여름에 너무 더웠어요.","그래도 검은 옷만 입었어요.","한 가지만 고집했어요."],"asset":{"type":"passage","lines":["옛날 검은 옷 나라 사람들은 일 년 내내 소매가 길고 두꺼운","검은 옷만 입었어요. 겨울에는 견딜 만했지만 여름에는 너무 더웠어요.","어느 해 여름, 비가 많이 내려 먹을 것이 다 떠내려갔어요.","이웃 나라 사람들이 먹을 것을 팔러 왔는데,","짧은 소매의 얇은 옷을 입고 있어 검은 옷 나라 사람들이 깜짝 놀랐어요."],"title":"검은 옷 나라 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#23','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C10',4,'mc','auto','교과서 52쪽 유니버설 디자인과 교과서 46쪽 편견·차별 문제를 함께 생각할 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X29','SO3-2-u1-X30','SO3-2-u1-X31']::text[],false,'{"seq":23,"concept":"SO3-2-u1-C10","difficulty":4,"kind":"mc","stem":"교과서 52쪽 유니버설 디자인과 교과서 46쪽 편견·차별 문제를 함께 생각할 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"타고난 조건이나 처한 환경이 달라도 모두가 함께 누릴 수 있게 배려하는 노력이 다양한 문화가 존중받는 사회를 만들어요","correct":true},{"t":"특별한 사람만 쓸 수 있는 물건이 많아져야 해요","mis":"SO3-2-u1-X29"},{"t":"다른 점이 있는 사람은 따로 지내야 해요","mis":"SO3-2-u1-X30"},{"t":"우리와 같은 사람만 편하면 돼요","mis":"SO3-2-u1-X31"}],"explanation":["누구나 쓰기 쉽게 만들어요.","다르다고 차별하지 않아요.","함께 누리는 사회를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#24','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C5',4,'essay','teacher','세계화로 우리나라가 세계에 영향을 주는 모습을 교과서 28쪽과 30쪽에서 하나씩 찾아 쓰고, 이를 통해 알 수 있는 세계화의 뜻을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-2-u1-C5","difficulty":4,"kind":"essay","stem":"세계화로 우리나라가 세계에 영향을 주는 모습을 교과서 28쪽과 30쪽에서 하나씩 찾아 쓰고, 이를 통해 알 수 있는 세계화의 뜻을 쓰세요.","answer_guide":{"answer":"예: 세종 학당이 우리의 말과 글, 음식, 한복을 세계에 알려요. 한국 라면이 인기를 끌어 우리나라 회사가 미국, 중국 등에 라면 공장을 지었어요. 세계화는 세계 여러 나라가 다양한 분야에서 교류하며 전 세계가 하나로 연결되는 현상이에요.","scoring_points":["28쪽에서 모습을 찾았는가","30쪽에서 모습을 찾았는가","세계화의 뜻을 바르게 썼는가"]},"explanation":["세종 학당을 떠올려요.","초코과자와 라면을 떠올려요.","세계화의 뜻을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u1_review_d#25','soc',3,2,'u1','','tb_g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C9',4,'essay','teacher','외국인 이주민, 1인 가구, 반려동물과 함께 사는 사람 가운데 하나를 골라, 그 문화가 확산되며 나타난 긍정적 효과와 문제를 하나씩 쓰고 문제를 해결하기 위한 노력을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-2-u1-C9","difficulty":4,"kind":"essay","stem":"외국인 이주민, 1인 가구, 반려동물과 함께 사는 사람 가운데 하나를 골라, 그 문화가 확산되며 나타난 긍정적 효과와 문제를 하나씩 쓰고 문제를 해결하기 위한 노력을 쓰세요.","answer_guide":{"answer":"예: 1인 가구가 늘어나며 크기가 작은 가전제품과 적은 양을 포장한 상품이 많아졌어요. 하지만 혼자 사는 사람은 아플 때 도움을 청할 사람이 없어 어려움을 겪기도 해요. 그래서 혼자 사는 사람들이 안전하고 편안한 환경에서 살 수 있도록 지원해요.","scoring_points":["하나를 골랐는가","긍정적 효과와 문제를 하나씩 썼는가","문제에 맞는 노력을 썼는가"]},"explanation":["하나를 골라요.","긍정적 효과와 문제를 써요.","해결 노력을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
